)


## -----------------------------------------------------------------------------
## 13. VERIFY CONSECUTIVE TIMESTAMPS ARE EXACTLY ONE HOUR APART (requirement #11)
## -----------------------------------------------------------------------------
diffs_final <- as.numeric(difftime(gwl_regularized$datetime[-1],
                                   gwl_regularized$datetime[-n_total], units = "mins"))
all_exact_hourly <- all(abs(diffs_final - 60) < 1e-6)

cat("\nVerification — all consecutive gaps exactly 60 minutes apart:", all_exact_hourly, "\n")
if (!all_exact_hourly) {
  bad_idx <- which(abs(diffs_final - 60) >= 1e-6)
  warning(length(bad_idx), " irregular spacing(s) remain after regularization — inspect before proceeding.")
} else {
  cat("PASSED: the regularized grid is exactly hourly from end to end.\n")
}


## -----------------------------------------------------------------------------
## 14. BEFORE-VS-AFTER QC TABLES (requirement #10)
## -----------------------------------------------------------------------------
before_snapshot <- data.frame(
  stage = "before (Step 1/2 raw)",
  n_rows = nrow(gwl_step1),
