)

before_after_comparison <- dplyr::bind_rows(before_snapshot, after_snapshot)

cat("\n--- Before vs. after comparison ----------------------------------\n")
print(before_after_comparison)


## -----------------------------------------------------------------------------
## 15. PLOT 1 — FULL REGULARIZED SERIES WITH IMPUTED VALUES MARKED
## -----------------------------------------------------------------------------
p_full_series <- ggplot2::ggplot(gwl_regularized, ggplot2::aes(x = datetime, y = gwl)) +
  ggplot2::geom_line(linewidth = 0.25, colour = "grey50") +
  {if (n_imputed > 0)
    ggplot2::geom_point(data = dplyr::filter(gwl_regularized, imputed_flag),
                        ggplot2::aes(x = datetime, y = gwl), colour = "red", size = 1.2)
  } +
