print(p_full_series)


## -----------------------------------------------------------------------------
## 16. PLOT 2 — ZOOMED OBSERVED-VS-IMPUTED VIEW AROUND EVERY SHORT GAP (req #9)
## -----------------------------------------------------------------------------
short_gaps <- gap_events |> dplyr::filter(gap_type == "short_isolated")
buffer_hours <- 12  # context window shown on each side of a short gap

if (nrow(short_gaps) > 0) {
  zoom_data <- purrr::map_dfr(seq_len(nrow(short_gaps)), function(i) {
    g <- short_gaps[i, ]
