    ggplot2::scale_colour_manual(values = c(observed = "steelblue", imputed_linear = "red",
                                            imputed_spline = "darkorange")) +
    ggplot2::facet_wrap(~panel_label, scales = "free_x") +
    ggplot2::labs(title = "Observed vs. Imputed Values Around Each Short Gap",
                  x = "Datetime", y = "GWL", colour = "Status") +
    ggplot2::theme_minimal() +
    ggplot2::theme(legend.position = "bottom")
  
  print(p_gap_zoom)
} else {
