ggplot2::ggsave(file.path("figures", "03_full_series_imputed.png"), p_full_series,
                width = 10, height = 5, dpi = 300)
ggplot2::ggsave(file.path("figures", "03_full_series_imputed.pdf"), p_full_series,
                width = 10, height = 5)

if (!is.null(p_gap_zoom)) {
  ggplot2::ggsave(file.path("figures", "03_gap_zoom_panels.png"), p_gap_zoom,
                  width = 11, height = 7, dpi = 300)
  ggplot2::ggsave(file.path("figures", "03_gap_zoom_panels.pdf"), p_gap_zoom,
                  width = 11, height = 7)
}

ggplot2::ggsave(file.path("figures", "03_interval_before_after.png"), p_interval_compare,
                width = 9, height = 5.5, dpi = 300)
