cat("Basic FSSM fitted: m =", p, "components, diagonal H and Q (per Requirement 1's",
    "explicit translation).\n")
cat("Optimizer convergence code:", convergence_code, ifelse(convergence_code == 0, "(clean)", "(SEE WARNING ABOVE)"), "\n")
cat("Training log-likelihood   :", round(fitted_loglik, 3), "\n")
if (length(degenerate_components) > 0) {
  cat("Degenerate (near-constant-coefficient) components:", paste(degenerate_components, collapse = ", "), "\n")
} else {
  cat("No degenerate components detected.\n")
}
