  ggplot2::ggsave(file.path("figures", paste0(name, ".png")), plot_obj, width = width, height = height, dpi = 300)
  ggplot2::ggsave(file.path("figures", paste0(name, ".pdf")), plot_obj, width = width, height = height)
}
save_fig(p1_level_filtered_smoothed, "12_01_filtered_smoothed_level", height = 10)
save_fig(p2_dynamic_slope,           "12_02_dynamic_slope")
save_fig(p3_residual_acf,            "12_03_residual_acf", height = 10)
save_fig(p4_actual_vs_fitted,        "12_04_actual_vs_fitted")
save_fig(p5_actual_vs_forecast,      "12_05_actual_vs_forecast")

cat("Figures exported to figures/ (300 dpi PNG + PDF), filenames prefixed '12_'.\n")


## -----------------------------------------------------------------------------
## EXPORT TABLES
## -----------------------------------------------------------------------------
tables_step12 <- list(
  model_comparison_table = model_comparison_table_L,
  ljung_box_table          = ljung_box_table,
  split_info                 = data.frame(split_source = split_source, n_train = n_train, n_test = n_test,
                                          train_start = as.character(min(train_dates)), train_end = as.character(max(train_dates)),
                                          test_start = as.character(min(test_dates)), test_end = as.character(max(test_dates)))
)
writexl::write_xlsx(tables_step12, path = file.path("Output_files", "12_level_state_space.xlsx"))
invisible(mapply(
