## -----------------------------------------------------------------------------
## STEP 12 OUTPUT VARIABLES CARRIED FORWARD
## -----------------------------------------------------------------------------
## level_state_space_results (saved as models/12_level_state_space.rds):
##   preferred_fit, preferred_eval : the chosen model's fitted KFAS object and
##                                   its filtered/smoothed states, one-step
##                                   forecasts -> PRIMARY INPUT for Step 14's
##                                   level-forecast component of
##                                   GWL_{d+1}(h) = L_{d+1} + sum_k beta phi_k(h)
##   daily_level_df, full_dates, L_d_full : carried unchanged for downstream use
## =============================================================================



## =============================================================================
## STEP 13 — ADD ANNUAL SEASONAL EFFECTS TO THE GWL FUNCTIONAL STATE-SPACE
##           FRAMEWORK
## Project : Hourly Groundwater Level (GWL) analysis — well GT2648C03
## Continues directly from STEP 6 (daily_level_df), STEP 8 (models/08_fpca.rds),
## STEP 9 (models/09_selected_fpca.rds), and STEP 12 (models/12_level_state_space.rds).
## =============================================================================
## PURPOSE OF STEP 13
## Create harmonic seasonal predictors from day-of-year (DOY):
##     sin(2*pi*k*DOY/365.25),  cos(2*pi*k*DOY/365.25),   k = 1, 2, 3, ...
## and test whether they improve (a) the daily-level state-space model
## (Step 12) and (b) — where the evidence already collected in Step 8
## supports it — the FPC-score FSSM (Steps 9-11).
##
## MECHANISM CHOICE (explicit, justified): harmonics are added here as
## DETERMINISTIC regression states (KFAS::SSMregression(..., Q = 0)) -- i.e.
## a FIXED (time-invariant) coefficient per sin/cos term, estimated via
## diffuse initialization through the Kalman filter/smoother. This is the
## classical harmonic-regression formulation matching the requested formula
## exactly, and is a DIFFERENT mechanism from Step 12's "trend + annual
## seasonal" variant, which used KFAS's built-in STOCHASTIC trigonometric
## seasonal STATE (a slowly evolving amplitude/phase, Q > 0). Both are
## reported in the same comparison table for transparency; they are not
## conflated or silently treated as the same thing.
##
## HOW MANY HARMONIC PAIRS: rather than assuming a single pair (K=1) or an
## arbitrary larger number, a LADDER of K = 0..4 harmonic pairs is fitted for
## the daily-level model and compared on AIC/BIC + genuine out-of-sample
## rolling forecast RMSE/MAE (Requirement: "consider whether additional
## harmonic pairs improve the model").
##
## CAUSAL INTERPRETATION CAUTION (Requirement 6, honoured throughout): any
## seasonal pattern found here is a STATISTICAL regularity in calendar time
## (day-of-year). It is NOT, by itself, evidence of a specific recharge,
## discharge, irrigation, or pumping MECHANISM -- multiple physically
## distinct processes (rainfall seasonality, agricultural pumping schedules,
## barometric/thermal effects) can all produce an annual statistical cycle
## indistinguishable from this analysis alone. No causal recharge language is
## used anywhere in this script's output.
## =============================================================================


## -----------------------------------------------------------------------------
## 1. PACKAGES
## -----------------------------------------------------------------------------
required_packages <- c("dplyr", "tidyr", "lubridate", "ggplot2", "writexl",
                       "scales", "purrr", "KFAS")
missing_packages <- required_packages[!required_packages %in% installed.packages()[, "Package"]]
if (length(missing_packages) > 0) install.packages(missing_packages, dependencies = TRUE)
invisible(lapply(required_packages, library, character.only = TRUE))


## -----------------------------------------------------------------------------
## 2. FOLDERS
## -----------------------------------------------------------------------------
dir.create("models",  showWarnings = FALSE)
dir.create("tables",  showWarnings = FALSE)
dir.create("figures", showWarnings = FALSE)


## -----------------------------------------------------------------------------
## 3. LOAD STEP 6, STEP 8, STEP 9, STEP 12 OUTPUTS (authoritative inputs)
## -----------------------------------------------------------------------------
step6_path  <- file.path("data_clean", "06_centered_daily_curves.rds")
step8_path  <- file.path("data_clean", "08_fpca.rds")
step9_path  <- file.path("data_clean", "09_selected_fpca.rds")
step12_path <- file.path("data_clean", "12_level_state_space.rds")
stopifnot(file.exists(step6_path), file.exists(step8_path),
          file.exists(step9_path), file.exists(step12_path))

centered_curves_results <- readRDS(step6_path)
fpca_results              <- readRDS(step8_path)
selected_fpca_results      <- readRDS(step9_path)
step12_results               <- readRDS(step12_path)

daily_level_df <- centered_curves_results$daily_level_df |> dplyr::arrange(date)

full_dates  <- step12_results$full_dates
L_d_full    <- step12_results$L_d_full
train_dates <- step12_results$train_dates
test_dates  <- step12_results$test_dates

train_end_date <- min(test_dates) - 1
train_idx <- which(full_dates <= train_end_date)
test_idx  <- which(full_dates %in% test_dates)
L_d_train <- L_d_full[train_idx]
n_obs_train <- sum(!is.na(L_d_train))
n_train <- length(train_dates); n_test <- length(test_dates)

cat("Loaded Step 6 (daily_level_df), Step 8 (FPCA/score ACF), Step 9 (selected FPCA),\n",
    "and Step 12 (level state-space baseline models).\n", sep = "")
cat("Full daily grid:", length(full_dates), "days. Train:", n_train, "days, Test:", n_test, "days.\n")


## -----------------------------------------------------------------------------
## 4. HARMONIC SEASONAL PREDICTORS FROM DAY-OF-YEAR
## -----------------------------------------------------------------------------
## sin(2*pi*k*DOY/365.25), cos(2*pi*k*DOY/365.25), k = 1..K -- 365.25 (not 365)
## is used consistently throughout this project (Step 8's annual-lag ACF
## check, Step 4's context) to account for leap years without introducing a
## slow phase drift over the ~5.6-year record.
DOY_full <- lubridate::yday(full_dates)

build_harmonics <- function(K, DOY) {
  mat <- matrix(NA_real_, nrow = length(DOY), ncol = 2 * K)
  cn <- character(2 * K)
  for (k in 1:K) {
    mat[, 2 * k - 1] <- sin(2 * pi * k * DOY / 365.25)
    mat[, 2 * k]     <- cos(2 * pi * k * DOY / 365.25)
    cn[2 * k - 1] <- paste0("sin_k", k)
    cn[2 * k]     <- paste0("cos_k", k)
  }
  colnames(mat) <- cn
  mat
}

K_max <- 4
cat("\nHarmonic-pair ladder to be tested for the daily-level model: K = 0 (baseline, reused",
    "from Step 12) through K =", K_max, "\n")


## =============================================================================
## PART A — SEASONAL TERMS FOR THE DAILY-LEVEL MODEL (Requirement 1)
## =============================================================================

## -----------------------------------------------------------------------------
## 5. K = 0 BASELINE — REUSE STEP 12's BEST NON-SEASONAL MODEL, NOT REFIT
## -----------------------------------------------------------------------------
## The null model for this harmonic-regression ladder is whichever of Step
## 12's two NON-seasonal structures (local level vs. local linear trend) had
## the lower BIC -- NOT necessarily Step 12's overall "preferred" model,
## which may have been the stochastic trigonometric-seasonal variant (a
## different, non-nested mechanism, reported separately below for context).
bic_level <- step12_results$all_evals$local_level$BIC
bic_trend <- step12_results$all_evals$local_linear_trend$BIC
if (bic_level <= bic_trend) {
  trend_degree <- 1; base_label <- "Local level"
  baseline_fit <- step12_results$all_fits$local_level
  baseline_eval <- step12_results$all_evals$local_level
} else {
  trend_degree <- 2; base_label <- "Local linear trend"
  baseline_fit <- step12_results$all_fits$local_linear_trend
  baseline_eval <- step12_results$all_evals$local_linear_trend
}
cat("\nBase (non-seasonal) trend structure for the harmonic ladder:", base_label,
    "(degree =", trend_degree, ") -- lower BIC than the alternative non-seasonal structure.\n")

var_L <- var(L_d_train, na.rm = TRUE)


## -----------------------------------------------------------------------------
## 6. FIT K = 1..K_max HARMONIC-REGRESSION VARIANTS
## -----------------------------------------------------------------------------
## SSMtrend()/SSMregression() are called BARE (no KFAS:: prefix) inside every
## model FORMULA below -- a namespace-qualified call inside a formula's RHS
## is mishandled by R's model.frame()/terms() parsing (confirmed directly in
## Step 12's execution: "invalid type (list) for variable ..."), even though
## KFAS::SSModel()/KFAS::fitSSM()/KFAS::KFS() themselves (outside any
## formula) are unaffected and remain namespace-qualified below.
fit_harmonic_level_model <- function(K) {
  harmonics_full  <- build_harmonics(K, DOY_full)
  harmonics_train <- harmonics_full[train_idx, , drop = FALSE]
  
  cat("\n--- Fitting daily-level model:", base_label, "+", K, "harmonic pair(s) ---\n")
  trend_Q_spec <- if (trend_degree == 1) list(matrix(NA)) else list(matrix(NA), matrix(NA))
  model_train <- KFAS::SSModel(
    L_d_train ~ SSMtrend(trend_degree, Q = trend_Q_spec) +
      SSMregression(~ harmonics_train - 1, Q = 0),
    H = matrix(NA)
  )
  n_var_params <- sum(is.na(model_train$Q)) + sum(is.na(model_train$H))
  n_reg_params <- ncol(harmonics_train)   # regression coefficients counted as free parameters (standard AIC/BIC convention)
  n_params <- n_var_params + n_reg_params
  
  inits <- rep(log(pmax(var_L, 1e-8) / 2), n_var_params)
  t0 <- Sys.time()
  fit <- KFAS::fitSSM(model_train, inits = inits, method = "BFGS",
                      control = list(maxit = 500, reltol = 1e-10))
  t1 <- Sys.time()
  convergence_code <- fit$optim.out$convergence
  training_loglik <- as.numeric(logLik(fit$model))
  AIC_v <- -2 * training_loglik + 2 * n_params
  BIC_v <- -2 * training_loglik + n_params * log(n_obs_train)
  cat("  Free parameters (variance + regression):", n_var_params, "+", n_reg_params,
      "=", n_params, "| Convergence:", convergence_code, "\n")
  cat("  Training log-likelihood:", round(training_loglik, 3),
      "| AIC:", round(AIC_v, 1), "| BIC:", round(BIC_v, 1), "\n")
  
  ## Full-grid model for genuine (causal, filtering-only) one-day-ahead
  ## forecasts at the test days, and full-sample smoothing for the
  ## "estimated seasonal pattern" plots (Requirements 4-5).
  Q_hat_trend <- fit$model$Q
  H_hat <- fit$model$H
  trend_Q_fixed <- if (trend_degree == 1) list(Q_hat_trend[1, 1, 1, drop = FALSE]) else
    list(Q_hat_trend[1, 1, 1, drop = FALSE], Q_hat_trend[2, 2, 1, drop = FALSE])
  model_full <- KFAS::SSModel(
    L_d_full ~ SSMtrend(trend_degree, Q = trend_Q_fixed) +
      SSMregression(~ harmonics_full - 1, Q = 0),
    H = H_hat
  )
  kfs_full <- KFAS::KFS(model_full, filtering = c("state", "mean"), smoothing = c("state", "mean"))
  
  one_step_ahead <- as.numeric(L_d_full) - as.numeric(kfs_full$v)
  forecast_test <- one_step_ahead[test_idx]
  actual_test   <- L_d_full[test_idx]
  resid_test <- actual_test - forecast_test
  RMSE_test <- sqrt(mean(resid_test^2, na.rm = TRUE))
  MAE_test  <- mean(abs(resid_test), na.rm = TRUE)
  cat("  Test RMSE:", round(RMSE_test, 5), "| Test MAE:", round(MAE_test, 5), "\n")
  
  v <- as.numeric(kfs_full$v); F_diag <- as.numeric(kfs_full$F)
  std_resid <- v / sqrt(F_diag)
  train_mask <- seq_along(full_dates) %in% train_idx
  std_resid_train <- std_resid[train_mask]; std_resid_train <- std_resid_train[!is.na(std_resid_train)]
  lb <- stats::Box.test(std_resid_train, lag = 14, type = "Ljung-Box")
  
  list(K = K, harmonics_full = harmonics_full, fit = fit, kfs_full = kfs_full,
       n_var_params = n_var_params, n_reg_params = n_reg_params, n_params = n_params,
       convergence_code = convergence_code, training_loglik = training_loglik,
       AIC = AIC_v, BIC = BIC_v, RMSE_test = RMSE_test, MAE_test = MAE_test,
       forecast_test = forecast_test, actual_test = actual_test,
       ljung_box_p_value = lb$p.value, std_resid = std_resid)
}

harmonic_fits <- purrr::map(1:K_max, fit_harmonic_level_model)
names(harmonic_fits) <- paste0("K", 1:K_max)


## -----------------------------------------------------------------------------
## 7. LEVEL-MODEL COMPARISON TABLE (Requirement 3: AIC/BIC, forecast RMSE/MAE,
##    residual ACF) — INCLUDES Step 12's stochastic seasonal variant FOR
##    CONTEXT ONLY (different mechanism, not part of the nested K-ladder)
## -----------------------------------------------------------------------------
baseline_lb_p <- step12_results$ljung_box_table |>
  dplyr::filter(model == base_label) |> dplyr::pull(p_value)
step12_stochastic_lb_p <- step12_results$ljung_box_table |>
  dplyr::filter(model == "Trend + annual seasonal") |> dplyr::pull(p_value)

level_seasonal_comparison_table <- dplyr::bind_rows(
  data.frame(
    model = paste0(base_label, " (K=0, no seasonality -- Step 12 baseline, reused)"),
    K_harmonic_pairs = 0, n_parameters = baseline_fit$n_params,
    convergence_code = baseline_fit$convergence_code,
    training_loglik = round(baseline_fit$training_loglik, 3),
    AIC = round(baseline_eval$AIC, 2), BIC = round(baseline_eval$BIC, 2),
    test_RMSE = round(baseline_eval$RMSE_test, 6), test_MAE = round(baseline_eval$MAE_test, 6),
    ljung_box_p_value = round(baseline_lb_p, 4), mechanism = "none"
  ),
  purrr::map_dfr(harmonic_fits, function(h) {
    data.frame(
      model = paste0(base_label, " + ", h$K, " harmonic pair(s)"),
      K_harmonic_pairs = h$K, n_parameters = h$n_params, convergence_code = h$convergence_code,
      training_loglik = round(h$training_loglik, 3), AIC = round(h$AIC, 2), BIC = round(h$BIC, 2),
      test_RMSE = round(h$RMSE_test, 6), test_MAE = round(h$MAE_test, 6),
      ljung_box_p_value = round(h$ljung_box_p_value, 4), mechanism = "deterministic harmonic regression (this step)"
    )
  }),
  data.frame(
    model = "Local linear trend + annual seasonal (Step 12, stochastic trigonometric state -- CONTEXT ONLY, not nested)",
    K_harmonic_pairs = NA_integer_, n_parameters = step12_results$all_fits$trend_plus_seasonal$n_params,
    convergence_code = step12_results$all_fits$trend_plus_seasonal$convergence_code,
    training_loglik = round(step12_results$all_fits$trend_plus_seasonal$training_loglik, 3),
    AIC = round(step12_results$all_evals$trend_plus_seasonal$AIC, 2),
    BIC = round(step12_results$all_evals$trend_plus_seasonal$BIC, 2),
    test_RMSE = round(step12_results$all_evals$trend_plus_seasonal$RMSE_test, 6),
    test_MAE = round(step12_results$all_evals$trend_plus_seasonal$MAE_test, 6),
    ljung_box_p_value = round(step12_stochastic_lb_p, 4), mechanism = "stochastic trigonometric seasonal state (Step 12)"
  )
) |> dplyr::arrange(BIC)

cat("\n--- Requirement 3: Level-model AIC/BIC/forecast/residual comparison ----\n")
print(level_seasonal_comparison_table)


## -----------------------------------------------------------------------------
## PREFERRED LEVEL-SEASONAL SPECIFICATION -- not on likelihood alone
## -----------------------------------------------------------------------------
nested_rows <- level_seasonal_comparison_table |>
  dplyr::filter(mechanism != "stochastic trigonometric seasonal state (Step 12)")
preferred_by_BIC_level     <- nested_rows |> dplyr::arrange(BIC) |> dplyr::slice(1)
preferred_by_forecast_level <- nested_rows |> dplyr::arrange(test_RMSE) |> dplyr::slice(1)

if (identical(preferred_by_BIC_level$model, preferred_by_forecast_level$model)) {
  preferred_level_row <- preferred_by_BIC_level
} else {
  preferred_level_row <- preferred_by_forecast_level   # forecast validity prioritized, per project convention
}
cat("\n*** PREFERRED LEVEL-MODEL SPECIFICATION: ", preferred_level_row$model, " ***\n", sep = "")
seasonality_added_to_level <- preferred_level_row$K_harmonic_pairs > 0
cat("Annual seasonality added to the daily-level model:", seasonality_added_to_level, "\n")


## =============================================================================
## PART B — SEASONAL COVARIATES IN THE FPC-SCORE FSSM, "WHERE APPROPRIATE"
## (Requirement 2)
## =============================================================================
## "Where appropriate" is operationalized using evidence ALREADY COMPUTED in
## Step 8: score_acf_table there tested each "important" FPC's autocorrelation
## at an approximate ANNUAL lag (365 days) against a white-noise band. Only
## components FLAGGED there as exceeding that band at the annual lag are
## tested here for a harmonic-regression covariate -- not all p=19 components
## blanket-tested, and not none. This is a targeted, evidence-based test.
##
## SCOPE NOTE (explicit, not a silent simplification): this test uses a
## simple per-component AR(1) + harmonic-regression comparison (exactly
## mirroring Step 9's per-component AR(1) forecast-evaluation precedent), NOT
## a full rebuild of the joint 19-dimensional multivariate SSMcustom FSSM
## (Steps 10-11). Embedding a component-specific deterministic regressor into
## that shared multivariate structure -- while leaving other components as
## pure diagonal loading -- is a substantively larger structural change and is
## explicitly DEFERRED (candidate for Step 14 or a dedicated later step), not
## silently done here.
score_acf_table <- fpca_results$score_acf_table
annual_flagged <- score_acf_table |>
  dplyr::filter(lag == 365, exceeds_white_noise_band) |>
  dplyr::pull(component) |>
  unique()

cat("\n--- Requirement 2: FPCs flagged (Step 8) with significant annual ACF ---\n")
if (length(annual_flagged) == 0) {
  cat("No 'important' FPC showed a significant annual-lag autocorrelation in Step 8.\n",
      "No FPC-score seasonal covariate test is performed -- 'where appropriate'\n",
      "correctly evaluates to 'not appropriate' here, and this is reported\n",
      "honestly rather than testing components without supporting evidence.\n", sep = "")
  fpc_seasonal_comparison_table <- data.frame(
    component = character(0), model = character(0), AIC = numeric(0), BIC = numeric(0),
    test_RMSE = numeric(0), test_MAE = numeric(0)
  )
} else {
  cat("Flagged component(s):", paste(annual_flagged, collapse = ", "), "\n")
  
  scores_selected <- selected_fpca_results$scores_selected
  acf_segment_dates_fpc <- selected_fpca_results$forecast_evaluation$acf_segment_dates
  train_dates_fpc <- selected_fpca_results$forecast_evaluation$train_dates
  test_dates_fpc  <- selected_fpca_results$forecast_evaluation$test_dates
  
  scores_seg_df <- scores_selected |>
    dplyr::filter(date %in% acf_segment_dates_fpc) |> dplyr::arrange(date)
  DOY_seg <- lubridate::yday(scores_seg_df$date)
  harmonics_seg_K1 <- build_harmonics(1, DOY_seg)   # single fundamental annual pair, matching the requested formula
  
  n_train_fpc <- length(train_dates_fpc); n_test_fpc <- length(test_dates_fpc)
  train_idx_fpc <- 1:n_train_fpc
  test_idx_fpc  <- (n_train_fpc + 1):(n_train_fpc + n_test_fpc)
  
  test_component_seasonality <- function(pc_name) {
    y_full_pc <- scores_seg_df[[pc_name]]
    y_train_pc <- y_full_pc[train_idx_fpc]
    xreg_train <- harmonics_seg_K1[train_idx_fpc, , drop = FALSE]
    xreg_test  <- harmonics_seg_K1[test_idx_fpc, , drop = FALSE]
    y_test_pc  <- y_full_pc[test_idx_fpc]
    
    fit_no_season <- tryCatch(
      suppressWarnings(stats::arima(y_train_pc, order = c(1, 0, 0), include.mean = TRUE, method = "ML")),
      error = function(e) NULL)
    fit_season <- tryCatch(
      suppressWarnings(stats::arima(y_train_pc, order = c(1, 0, 0), include.mean = TRUE, method = "ML",
                                    xreg = xreg_train)),
      error = function(e) NULL)
    if (is.null(fit_no_season) || is.null(fit_season)) return(NULL)
    
    forecast_no_season <- as.numeric(stats::predict(fit_no_season, n.ahead = n_test_fpc)$pred)
    forecast_season <- as.numeric(stats::predict(fit_season, n.ahead = n_test_fpc, newxreg = xreg_test)$pred)
    
    metrics <- function(forecast) {
      resid <- y_test_pc - forecast
      c(RMSE = sqrt(mean(resid^2)), MAE = mean(abs(resid)))
    }
    m_no <- metrics(forecast_no_season); m_yes <- metrics(forecast_season)
    
    dplyr::bind_rows(
      data.frame(component = pc_name, model = "AR(1), no seasonal covariate",
                 AIC = AIC(fit_no_season), BIC = BIC(fit_no_season),
                 test_RMSE = m_no["RMSE"], test_MAE = m_no["MAE"]),
      data.frame(component = pc_name, model = "AR(1) + annual harmonic covariate (K=1)",
                 AIC = AIC(fit_season), BIC = BIC(fit_season),
                 test_RMSE = m_yes["RMSE"], test_MAE = m_yes["MAE"])
    )
  }
  
  fpc_seasonal_comparison_table <- purrr::map_dfr(annual_flagged, test_component_seasonality) |>
    dplyr::mutate(across(c(AIC, BIC, test_RMSE, test_MAE), ~round(., 5)))
  
  cat("\nPer-component AR(1) vs. AR(1)+harmonic comparison:\n")
  print(fpc_seasonal_comparison_table)
  
  seasonal_helps_fpc <- fpc_seasonal_comparison_table |>
    dplyr::group_by(component) |>
    dplyr::summarise(
      BIC_improves = BIC[model == "AR(1) + annual harmonic covariate (K=1)"] < BIC[model == "AR(1), no seasonal covariate"],
      RMSE_improves = test_RMSE[model == "AR(1) + annual harmonic covariate (K=1)"] < test_RMSE[model == "AR(1), no seasonal covariate"],
      .groups = "drop"
    )
  cat("\nComponents where the annual harmonic covariate improves BOTH BIC and\n",
      "out-of-sample forecast RMSE (genuine evidence, not likelihood alone):\n", sep = "")
  print(seasonal_helps_fpc)
}


## =============================================================================
## PLOTS
## =============================================================================
pub_theme <- ggplot2::theme_minimal(base_size = 12) +
  ggplot2::theme(plot.title = ggplot2::element_text(face = "bold"),
                 panel.grid.minor = ggplot2::element_blank())

preferred_K <- preferred_level_row$K_harmonic_pairs
preferred_harmonic_fit <- if (preferred_K > 0) harmonic_fits[[paste0("K", preferred_K)]] else NULL

if (!is.null(preferred_harmonic_fit)) {
  harmonic_cols <- colnames(preferred_harmonic_fit$harmonics_full)
  kfs_pref <- preferred_harmonic_fit$kfs_full
  beta_cols_present <- harmonic_cols[harmonic_cols %in% colnames(kfs_pref$alphahat)]
  beta_hat <- kfs_pref$alphahat[nrow(kfs_pref$alphahat), beta_cols_present]   # time-invariant coefficient (Q=0); take the full-sample smoothed value
  
  ## PLOT 1 (Requirement 4) — Estimated annual seasonal PATTERN over day-of-year
  doy_grid <- 1:365
  harmonics_doy_grid <- build_harmonics(preferred_K, doy_grid)
  seasonal_shape <- as.numeric(harmonics_doy_grid[, beta_cols_present, drop = FALSE] %*% beta_hat)
  seasonal_shape_df <- data.frame(day_of_year = doy_grid, seasonal_contribution = seasonal_shape)
  
  p1_seasonal_pattern <- ggplot2::ggplot(seasonal_shape_df, ggplot2::aes(x = day_of_year, y = seasonal_contribution)) +
    ggplot2::geom_line(colour = "steelblue4", linewidth = 0.8) +
    ggplot2::geom_hline(yintercept = 0, colour = "grey60", linetype = "dotted") +
    ggplot2::scale_x_continuous(breaks = c(1, 91, 152, 244, 335), labels = c("Jan", "Apr", "Jun", "Sep", "Dec")) +
    ggplot2::labs(
      title = paste0("Estimated Annual Seasonal Pattern in Daily GWL Level (", preferred_K, " harmonic pair(s))"),
      subtitle = "Statistical calendar-time regularity -- NOT a claim about a specific recharge/discharge mechanism (Requirement 6)",
      x = "Day of year", y = "Seasonal contribution to L_d"
    ) +
    pub_theme
  
  ## PLOT 2 (Requirement 5) — Predicted seasonal CONTRIBUTION through the actual timeline
  harmonics_full_pref <- preferred_harmonic_fit$harmonics_full
  seasonal_contribution_ts <- as.numeric(harmonics_full_pref[, beta_cols_present, drop = FALSE] %*% beta_hat)
  seasonal_ts_df <- data.frame(date = full_dates, seasonal_contribution = seasonal_contribution_ts)
  
  p2_seasonal_through_time <- ggplot2::ggplot(seasonal_ts_df, ggplot2::aes(x = date, y = seasonal_contribution)) +
    ggplot2::geom_line(colour = "firebrick3", linewidth = 0.4) +
    ggplot2::geom_hline(yintercept = 0, colour = "grey60", linetype = "dotted") +
    ggplot2::labs(
      title = "Predicted Seasonal Contribution to Daily GWL Level Through Time",
      subtitle = "Same annual pattern repeated across the record's calendar years",
      x = "Date", y = "Seasonal contribution to L_d"
    ) +
    pub_theme
} else {
  cat("\nPreferred level model has K=0 harmonic pairs (seasonality not supported) --\n",
      "Requirement 4/5 plots are still produced using the smallest tested harmonic\n",
      "specification (K=1) for illustrative/diagnostic purposes, clearly labelled\n",
      "as NOT the preferred model.\n", sep = "")
  illustrative_fit <- harmonic_fits[["K1"]]
  harmonic_cols <- colnames(illustrative_fit$harmonics_full)
  kfs_illust <- illustrative_fit$kfs_full
  beta_cols_present <- harmonic_cols[harmonic_cols %in% colnames(kfs_illust$alphahat)]
  beta_hat <- kfs_illust$alphahat[nrow(kfs_illust$alphahat), beta_cols_present]
  
  doy_grid <- 1:365
  harmonics_doy_grid <- build_harmonics(1, doy_grid)
  seasonal_shape <- as.numeric(harmonics_doy_grid[, beta_cols_present, drop = FALSE] %*% beta_hat)
  seasonal_shape_df <- data.frame(day_of_year = doy_grid, seasonal_contribution = seasonal_shape)
  p1_seasonal_pattern <- ggplot2::ggplot(seasonal_shape_df, ggplot2::aes(x = day_of_year, y = seasonal_contribution)) +
    ggplot2::geom_line(colour = "grey40", linewidth = 0.8) +
    ggplot2::geom_hline(yintercept = 0, colour = "grey60", linetype = "dotted") +
    ggplot2::labs(title = "Illustrative Annual Pattern (K=1) -- seasonality NOT supported as preferred",
                  subtitle = "Statistical calendar-time regularity only -- see Requirement 6 caution",
                  x = "Day of year", y = "Seasonal contribution to L_d") +
    pub_theme
  
  harmonics_full_illust <- illustrative_fit$harmonics_full
  seasonal_contribution_ts <- as.numeric(harmonics_full_illust[, beta_cols_present, drop = FALSE] %*% beta_hat)
  seasonal_ts_df <- data.frame(date = full_dates, seasonal_contribution = seasonal_contribution_ts)
  p2_seasonal_through_time <- ggplot2::ggplot(seasonal_ts_df, ggplot2::aes(x = date, y = seasonal_contribution)) +
    ggplot2::geom_line(colour = "grey40", linewidth = 0.4) +
    ggplot2::geom_hline(yintercept = 0, colour = "grey60", linetype = "dotted") +
    ggplot2::labs(title = "Illustrative Seasonal Contribution Through Time (K=1, not preferred)",
                  x = "Date", y = "Seasonal contribution to L_d") +
    pub_theme
}

## PLOT 3 — AIC/BIC vs. number of harmonic pairs (nested ladder only)
p3_aic_bic_vs_K <- level_seasonal_comparison_table |>
