  ggplot2::ggsave(file.path("figures", paste0(name, ".pdf")), plot_obj, width = width, height = height)
}
save_fig(p1_actual_vs_forecast, "14_01_actual_vs_forecast_curves", height = 8)
save_fig(p2_error_by_hour,      "14_02_forecast_error_by_hour")

cat("Figures exported to figures/ (300 dpi PNG + PDF), filenames prefixed '14_'.\n")


## -----------------------------------------------------------------------------
## REQUIREMENT 9 — EXPORT HOURLY FORECASTS
## -----------------------------------------------------------------------------
gwl_forecast_export_df <- as.data.frame(gwl_forecast_test) |>
  dplyr::mutate(date = rownames(gwl_forecast_test)) |>
  dplyr::select(date, dplyr::everything())

tables_step14 <- list(
  hourly_forecasts               = gwl_forecast_export_df,
