  level_source_label <- base_label
}
full_dates_level <- step12_results$full_dates
L_d_full          <- step12_results$L_d_full

cat("Loaded all Step 5-17 inputs. m =", p, "FPCs. Level source:", level_source_label, "\n")
cat("Gap-free segment:", n_seg, "days. Train:", n_train, ", Test:", n_test, "days.\n")


## =============================================================================
## REQUIREMENT 1 — INITIAL TRAINING PERIOD (explicit statement, reused unchanged)
## =============================================================================
cat("\n--- Requirement 1: Initial training period ------------------------------\n")
cat("Initial training period (SAME for every model family, unchanged since Step 9):\n",
    "  ", as.character(min(train_dates)), " to ", as.character(max(train_dates)),
    " (", n_train, " days).\n", sep = "")
cat("All model PARAMETERS (ARIMA orders, ETS components, FSSM H/Q, level model\n",
    "structure) were estimated ONCE on this window, in Steps 10-17. Step 18 never\n",
    "re-estimates them; only the forecast ORIGIN advances (Requirement 2/3 below).\n", sep = "")


## =============================================================================
## REQUIREMENT 2/3 — ROLLING ORIGIN DEFINITION (fixed parameters, expanding
## INFORMATION as origin advances, never re-estimated)
## =============================================================================
H_max <- 7   # horizons 1..7 days, per the roadmap
## Common origin set: origins must be within the TEST portion of the model
## sequence, with h=1..7 targets still inside the gap-free segment (so every
## horizon has the SAME origins available -- a fair horizon curve, Requirement 5).
test_row_idx_model <- (n_train):(n_seg - 1)   # indices into model_dates/att for test rows (mirrors Step 10/11's convention)
stopifnot(length(test_row_idx_model) == n_test)
origin_rows_model <- test_row_idx_model[1]:(test_row_idx_model[n_test] - H_max)
