    RMSE = sqrt(mean((actual - predicted)^2)),
    MAE  = mean(abs(actual - predicted)),
    Bias = mean(actual - predicted),
    sMAPE = smape(actual, predicted),
    SE_abs_error = sd(abs(actual - predicted)) / sqrt(dplyr::n()),
    SE_bias      = sd(actual - predicted) / sqrt(dplyr::n()),
    .groups = "drop"
  )

## Functional ISE by horizon -- WHERE APPROPRIATE (curve-native families only)
compute_functional_ise_by_horizon <- function(results_list, method_name, needs_projection = FALSE) {
  purrr::map_dfr(1:H_max, function(h) {
    ise_vals <- purrr::map_dbl(results_list, function(r) {
      if (anyNA(r$target[h])) return(NA_real_)
      actual_curve_h <- r$actual[h, ]
      if (anyNA(actual_curve_h)) return(NA_real_)
      actual_coefs_h <- project_to_bspline_coefs(actual_curve_h)
      forecast_coefs_h <- if (needs_projection) project_to_bspline_coefs(r$predicted[h, ]) else r$coefs_forecast[, h]
      functional_ise(actual_coefs_h, forecast_coefs_h)
    })
    data.frame(method = method_name, horizon = h,
               mean_functional_ISE = mean(ise_vals, na.rm = TRUE),
               median_functional_ISE = median(ise_vals, na.rm = TRUE),
               n_valid = sum(!is.na(ise_vals)))
  })
}

functional_ise_table <- dplyr::bind_rows(
  compute_functional_ise_by_horizon(persistence_results_list, "Persistence", needs_projection = TRUE),
  compute_functional_ise_by_horizon(fpca_indep_results_list, "FPCA + independent scores (Step 17)", needs_projection = FALSE),
  compute_functional_ise_by_horizon(basic_fssm_results_list, "Basic FSSM (Step 10)", needs_projection = FALSE),
  compute_functional_ise_by_horizon(final_fssm_results_list, "Final FSSM (Step 11+12/13)", needs_projection = FALSE)
)

