  ggplot2::scale_fill_gradient2(low = "seagreen4", mid = "white", high = "firebrick3", midpoint = 0,
                                name = "% change\nvs. selected") +
  ggplot2::labs(title = "Sensitivity Heatmap: % Change in Error vs. the Originally Selected Specification",
                subtitle = "★ = the specification actually used in this project. Negative (green) = candidate performs BETTER than selected.",
                x = "Candidate value", y = NULL) +
