## PLOT 3 — Improvement-over-persistence, by horizon
p3_improvement_over_persistence <- ggplot2::ggplot(improvement_over_persistence_table |> dplyr::filter(scale == "curve (24h)"),
                                                   ggplot2::aes(x = horizon, y = pct_RMSE_improvement, colour = method)) +
  ggplot2::geom_hline(yintercept = 0, colour = "grey50", linetype = "dashed") +
  ggplot2::geom_hline(yintercept = practical_threshold_pct, colour = "grey70", linetype = "dotted") +
  ggplot2::geom_line(linewidth = 0.7) + ggplot2::geom_point(size = 2) +
  ggplot2::scale_x_continuous(breaks = 1:H_max) +
  ggplot2::labs(title = "% RMSE Improvement Over Persistence, by Horizon (Curve-Scale)",
                subtitle = paste0("Dotted line = practical-meaningfulness threshold (", practical_threshold_pct, "%)"),
                x = "Forecast horizon (days)", y = "% RMSE improvement over persistence", colour = NULL) +
  pub_theme + ggplot2::theme(legend.position = "bottom")

## PLOT 4 — Pairwise DM p-values heatmap (h=1, curve-scale)
p4_dm_pvalue_heatmap <- ggplot2::ggplot(pairwise_DM_curve_MSE |> dplyr::filter(horizon == 1),
                                        ggplot2::aes(x = model_1, y = model_2, fill = p_value)) +
