p18 <- function(n) file.path("data_clean", n)
step_files <- c("01_imported_gwl.rds", "03_hourly_regularized_gwl.rds", "04_exploratory_results.rds",
                "05_daily_curves.rds", "06_centered_daily_curves.rds", "07_bspline_fit.rds",
                "08_fpca.rds", "09_selected_fpca.rds", "10_basic_FSSM.rds",
                "11_HQ_covariance_comparison.rds", "12_level_state_space.rds", "13_seasonal_FSSM.rds",
                "14_final_GWL_FSSM.rds", "15_persistence_benchmarks.rds", "16_scalar_benchmarks.rds",
                "17_FPCA_score_forecast.rds", "18_rolling_origin_validation.rds", "19_statistical_comparison.rds")
stopifnot(all(file.exists(p18(step_files))))

gwl_raw_obj             <- readRDS(p18("01_imported_gwl.rds"))
gwl_regularized         <- readRDS(p18("03_hourly_regularized_gwl.rds"))
