fpca_results                       <- readRDS(p18("08_fpca.rds"))
selected_fpca_results                 <- readRDS(p18("09_selected_fpca.rds"))
basic_FSSM_results                       <- readRDS(p18("10_basic_FSSM.rds"))
step11_results                              <- readRDS(p18("11_HQ_covariance_comparison.rds"))
step12_results                                 <- readRDS(p18("12_level_state_space.rds"))
step13_results                                    <- readRDS(p18("13_seasonal_FSSM.rds"))
final_GWL_FSSM_results                               <- readRDS(p18("14_final_GWL_FSSM.rds"))
persistence_benchmarks_results                          <- readRDS(p18("15_persistence_benchmarks.rds"))
scalar_benchmarks_results                                  <- readRDS(p18("16_scalar_benchmarks.rds"))
FPCA_score_forecast_results                                   <- readRDS(p18("17_FPCA_score_forecast.rds"))
rolling_origin_validation_results                                <- readRDS(p18("18_rolling_origin_validation.rds"))
statistical_comparison_results                                      <- readRDS(p18("19_statistical_comparison.rds"))

cat("All 18 prior-step .rds files loaded successfully.\n")

