score_cols <- paste0("PC", 1:p)

pub_theme <- ggplot2::theme_minimal(base_size = 12) +
  ggplot2::theme(plot.title = ggplot2::element_text(face = "bold"),
                 panel.grid.minor = ggplot2::element_blank())

save_fig_pub <- function(plot_obj, name, width = 10, height = 6) {
  ggplot2::ggsave(file.path(fig_png_dir, paste0(name, ".png")), plot_obj, width = width, height = height, dpi = 300)
  ggplot2::ggsave(file.path(fig_pdf_dir, paste0(name, ".pdf")), plot_obj, width = width, height = height)
  ggplot2::ggsave(file.path(fig_tiff300_dir, paste0(name, ".tiff")), plot_obj, width = width, height = height,
                  dpi = 300, compression = "lzw")
  ggplot2::ggsave(file.path(fig_tiff600_dir, paste0(name, ".tiff")), plot_obj, width = width, height = height,
                  dpi = 600, compression = "lzw")
}


