## FIGURE 13 — Residual diagnostics (preferred FSSM variant). Step 11 EXPLICITLY
## deferred residual diagnostics for non-basic variants to "a later, dedicated
## step" -- this is that step. If the preferred variant IS the basic one,
## Step 10's already-computed residuals are reused directly (no recomputation).
if (preferred_variant_id == "H_diag_Q_diag") {
  resid_df_13 <- basic_FSSM_results$residuals_df
  cat("\nPreferred variant IS the Step 10 basic model -- residual diagnostics REUSED, not recomputed.\n")
} else {
  cat("\nPreferred variant differs from Step 10's basic model -- computing residual\n",
      "diagnostics NOW (Step 11's own deferred task), using the same F_t = Z_t P_t Z_t' + H\n",
      "identity Step 10 established.\n", sep = "")
  ## Rebuild Zt_full exactly as Steps 10/11 did (same procedure, not redefined)
  acf_segment_dates_13 <- selected_fpca_results$forecast_evaluation$acf_segment_dates
  scores_seg_13 <- selected_fpca_results$scores_selected |> dplyr::filter(date %in% acf_segment_dates_13) |> dplyr::arrange(date)
  scores_seg_mat_13 <- as.matrix(scores_seg_13[, score_cols, drop = FALSE])
  lagged_13 <- scores_seg_mat_13[-nrow(scores_seg_mat_13), , drop = FALSE]
  n_t_13 <- nrow(lagged_13)
  Zt_full_13 <- array(0, dim = c(p, p, n_t_13))
  for (t in seq_len(n_t_13)) { sl <- matrix(0, p, p); diag(sl) <- lagged_13[t, ]; Zt_full_13[, , t] <- sl }
  H_hat_13 <- step11_results$variant_results[[preferred_variant_id]]$H_hat
  P_13 <- preferred_kfs$P
  std_resid_13 <- matrix(NA_real_, n_t_13, p)
  for (t in seq_len(n_t_13)) {
    Zt <- matrix(Zt_full_13[, , t], p, p); Pt <- matrix(P_13[, , t], p, p)
    Ft <- Zt %*% Pt %*% t(Zt) + H_hat_13
    std_resid_13[t, ] <- preferred_kfs$v[t, ] / sqrt(diag(Ft))
  }
  colnames(std_resid_13) <- score_cols
  resid_df_13 <- data.frame(date = basic_FSSM_results$model_dates, std_resid_13, check.names = FALSE)
}
fig13 <- resid_df_13 |> dplyr::select(date, dplyr::all_of(score_cols[1:n_show_states])) |>
  tidyr::pivot_longer(-date, names_to = "component", values_to = "std_resid") |>
  ggplot2::ggplot(ggplot2::aes(std_resid)) + ggplot2::geom_histogram(ggplot2::aes(y = ggplot2::after_stat(density)), bins = 50, fill = "steelblue3", colour = "white") +
  ggplot2::stat_function(fun = dnorm, colour = "firebrick3") + ggplot2::facet_wrap(~component, ncol = 2) +
  ggplot2::labs(title = "Standardized Residual Diagnostics — Preferred FSSM", x = "Standardized residual", y = "Density") + pub_theme
save_fig_pub(fig13, "Fig13_residual_diagnostics")

