useful_horizons <- table7b_improvement_over_persistence |> dplyr::filter(method == "Final FSSM (Step 11+12/13)", pct_RMSE_improvement >= 5) |> dplyr::pull(horizon)
q_evidence <- step11_results$q_evidence_table
