cat("First forecast timestamp:", as.character(min(forecast_168h$datetime)), "\n")
cat("Final forecast timestamp:", as.character(max(forecast_168h$datetime)), "\n")
get_at <- function(h) forecast_168h$gwl_forecast[forecast_168h$datetime == last_observed_datetime + h * 3600]
cat("Forecast at +1h  :", round(get_at(1), 5), "\n")
cat("Forecast at +24h :", round(get_at(24), 5), "\n")
cat("Forecast at +72h :", round(get_at(72), 5), "\n")
