## =============================================================================
## STEP 21.1 — FULL PI + HISTORICAL/FUTURE PRESENTATION
## Project : Hourly Groundwater Level (GWL) analysis — well GT2648C03
## Continues directly from STEP 21 ("Genuine future GWL forecasting beyond the
## observed dataset"), whose winning model was dynamically identified as
## "FPCA + independent scores (Step 17)". This script does NOT re-select the
## winning model, does NOT re-select ARIMA vs ETS, does NOT re-select the
## B-spline dimension K or the number of FPCs m, and does NOT alter the level
## model or the existing Step-21 point forecasts. It is a post-processing /
## uncertainty-quantification step that:
##   (1) upgrades the Step-21 prediction interval from level-only uncertainty
##       to a pointwise 95% PI incorporating BOTH daily-level uncertainty and
##       functional-shape/FPC-score forecast uncertainty;
##   (2) preserves every existing Step-21 output file unchanged;
##   (3) adds new historical(observed)+future(forecast) datasets and figures;
##   (4) adds new, clearly "21_1_"-prefixed exports.
## =============================================================================


## -----------------------------------------------------------------------------
## 0. PACKAGES
## -----------------------------------------------------------------------------
required_packages <- c("dplyr", "tidyr", "lubridate", "ggplot2", "writexl",
                       "scales", "purrr", "fda", "KFAS", "forecast")
missing_packages <- required_packages[!required_packages %in% installed.packages()[, "Package"]]
if (length(missing_packages) > 0) install.packages(missing_packages, dependencies = TRUE)
invisible(lapply(required_packages, library, character.only = TRUE))

dir.create("data_clean", showWarnings = FALSE)
dir.create("forecasts",  showWarnings = FALSE)
dir.create("figures",    showWarnings = FALSE)
dir.create("tables",     showWarnings = FALSE)

z975 <- qnorm(0.975)   # exact 1.959964..., used everywhere below for the 95% PI


## =============================================================================
## SECTION A — LOAD THE AUTHORITATIVE STEP-21 OUTPUT AND EVERY UPSTREAM OBJECT
## STEP 21.1 NEEDS TO RECOMPUTE UNCERTAINTY (NOTHING HERE IS RE-SELECTED)
## =============================================================================
step21_path <- file.path("forecasts", "21_FSSM_future_forecast.rds")
stopifnot(file.exists(step21_path))
step21_results <- readRDS(step21_path)

cat("Loaded Step 21 authoritative output: forecasts/21_FSSM_future_forecast.rds\n")
cat("Step-21 winning model:", step21_results$winning_method, "\n")
stopifnot(identical(step21_results$model_family, "fpca_independent"))
cat("Confirmed model_family == 'fpca_independent' (FPCA + independent scores, Step 17) --\n",
    "STEP 21.1 proceeds exactly against this model, per the authoritative Step-21 selection.\n", sep = "")

## Upstream Step 1-19 objects needed to rebuild the score-forecast machinery
## and the functional reconstruction (all loaded, none re-derived/re-selected).
p_load <- function(n) file.path("data_clean", n)
needed_files <- c("03_hourly_regularized_gwl.rds", "05_daily_curves.rds",
                  "09_selected_fpca.rds", "12_level_state_space.rds",
                  "13_seasonal_FSSM.rds", "17_FPCA_score_forecast.rds")
missing_files <- needed_files[!file.exists(p_load(needed_files))]
if (length(missing_files) > 0) stop("Missing required upstream file(s): ", paste(missing_files, collapse = ", "))

gwl_regularized             <- readRDS(p_load("03_hourly_regularized_gwl.rds")) |> dplyr::arrange(datetime)
daily_curves_results         <- readRDS(p_load("05_daily_curves.rds"))
selected_fpca_results          <- readRDS(p_load("09_selected_fpca.rds"))
step13_results                    <- readRDS(p_load("13_seasonal_FSSM.rds"))
FPCA_score_forecast_results          <- readRDS(p_load("17_FPCA_score_forecast.rds"))

retained_dates <- daily_curves_results$retained_dates
p              <- selected_fpca_results$recommended_m
score_cols     <- paste0("PC", 1:p)

meanfd              <- selected_fpca_results$meanfd
harmonics_selected   <- selected_fpca_results$harmonics_selected
basis_obj              <- selected_fpca_results$basis_obj
argvals                 <- selected_fpca_results$argvals

Phi_argvals     <- fda::eval.basis(argvals, basis_obj)      # 24 x K
mean_coefs_vec  <- as.numeric(meanfd$coefs)
harmonics_coefs <- harmonics_selected$coefs                  # K x p
eigen_at_hour   <- Phi_argvals %*% harmonics_coefs            # 24 x p : phi_k(u), u = 0..23

reconstruct_coefs <- function(scores_mat) {
  n_curves <- nrow(scores_mat)
  matrix(mean_coefs_vec, nrow = length(mean_coefs_vec), ncol = n_curves) +
    harmonics_coefs %*% t(scores_mat)
}

## Forecast-origin / partial-day bookkeeping — REUSED, not recomputed.
last_observed_datetime <- step21_results$last_observed_datetime
last_observed_gwl      <- step21_results$last_observed_gwl
last_day_is_complete    <- step21_results$last_day_is_complete
last_complete_date       <- step21_results$last_complete_date

target_ts_24h  <- seq(last_observed_datetime + 3600, by = "hour", length.out = 24)
target_ts_168h <- seq(last_observed_datetime + 3600, by = "hour", length.out = 168)
future_dates_needed <- seq(last_complete_date + 1, as.Date(max(target_ts_168h)), by = "day")
n_future_days_needed <- length(future_dates_needed)

cat("\nForecast origin (unchanged from Step 21):", as.character(last_observed_datetime), "\n")
cat("Future days requiring reconstruction:", n_future_days_needed, "\n")


## =============================================================================
## SECTION B — DAILY-LEVEL FORECAST + UNCERTAINTY
## Reuses the exact fitted/filtered Step-21 level model (refit_level_fit,
## refit_level_kfs) — the model is NOT refit here. Only the recursive
## forward state-variance propagation (T P T' + Q) is (re)computed, because
## Step 21 discarded its own internal SE vector without saving it.
## =============================================================================
cat("\n--- Section B: Daily-level forecast + uncertainty (level model REUSED, not refit) ---\n")

fit_level_refit <- step21_results$refit_level_fit
kfs_level_refit  <- step21_results$refit_level_kfs

base_label_fixed   <- step13_results$base_label
trend_degree_fixed  <- step13_results$trend_degree
K_fixed <- if (!is.null(step13_results$preferred_level_fit)) step13_results$preferred_K else 0L
seasonality_in_level <- K_fixed > 0
build_harmonics_local <- step13_results$build_harmonics

Tt_level <- matrix(fit_level_refit$model$T[, , 1], nrow = dim(fit_level_refit$model$T)[1])
Q_level  <- matrix(fit_level_refit$model$Q[, , 1], nrow = dim(fit_level_refit$model$Q)[1])
n_states_level <- nrow(Tt_level)
n_full_level <- nrow(kfs_level_refit$att)
state_now <- kfs_level_refit$att[n_full_level, ]
P_now     <- matrix(kfs_level_refit$Ptt[, , n_full_level], nrow = n_states_level)

level_forecast_vec <- rep(NA_real_, n_future_days_needed)
level_var_vec        <- rep(NA_real_, n_future_days_needed)

for (j in seq_len(n_future_days_needed)) {
  state_now <- as.numeric(Tt_level %*% state_now)
  P_now     <- Tt_level %*% P_now %*% t(Tt_level) + Q_level
  if (seasonality_in_level) {
    doy_j  <- lubridate::yday(future_dates_needed[j])
    harm_j <- as.numeric(build_harmonics_local(K_fixed, doy_j))
    level_forecast_vec[j] <- state_now[1] + sum(harm_j * state_now[(n_states_level - 2 * K_fixed + 1):n_states_level])
  } else {
    level_forecast_vec[j] <- state_now[1]
  }
  level_var_vec[j] <- P_now[1, 1]   # Var(Lhat_{d+h}) -- level-state variance component
}
level_se_vec <- sqrt(pmax(level_var_vec, 0))

cat("Recomputed level-forecast point values and SE(h) for", n_future_days_needed, "future day(s).\n")
cat("(Point values are the SAME propagation Step 21 used internally; only the\n",
    "variance, which Step 21 discarded, is retained here.)\n", sep = "")


## =============================================================================
## SECTION C — FPC-SCORE FORECAST + UNCERTAINTY (per-component ARIMA/ETS,
## SAME model type/specification Step 17 selected and Step 21 already applied
## -- refit on all available data, exactly as Step 21 did; no model search)
## =============================================================================
cat("\n--- Section C: Per-component FPC-score forecast + uncertainty ------------\n")

## Rebuild the SAME trailing gap-free segment Step 21 used (ending at the
## last complete retained day) -- identical logic, not re-derived differently.
rd_sorted <- sort(retained_dates)
diffs_rd  <- as.numeric(diff(rd_sorted))
break_idx <- which(diffs_rd != 1)
trailing_start_idx <- if (length(break_idx) == 0) 1 else max(break_idx) + 1
trailing_segment_dates <- rd_sorted[trailing_start_idx:length(rd_sorted)]
stopifnot(max(trailing_segment_dates) == last_complete_date)

scores_selected_all <- selected_fpca_results$scores_selected |> dplyr::arrange(date)
trailing_scores_mat <- scores_selected_all |>
  dplyr::filter(date %in% trailing_segment_dates) |>
  dplyr::arrange(date) |>
  dplyr::select(dplyr::all_of(score_cols)) |>
  as.matrix()

component_results_17 <- FPCA_score_forecast_results$component_results

score_forecast_mat <- matrix(NA_real_, nrow = n_future_days_needed, ncol = p)
score_se_mat         <- matrix(NA_real_, nrow = n_future_days_needed, ncol = p)
colnames(score_forecast_mat) <- colnames(score_se_mat) <- score_cols

for (k in seq_len(p)) {
  pc <- score_cols[k]
  r  <- component_results_17[[pc]]
  series_full <- ts(trailing_scores_mat[, k], frequency = 1)
  
  if (r$chosen_method == "ARIMA") {
    ord <- forecast::arimaorder(r$fit_final_train)
    refit_k <- tryCatch(forecast::Arima(series_full, order = ord[1:3], include.mean = TRUE),
                        error = function(e) forecast::Arima(series_full, model = r$fit_final_train))
  } else {
    refit_k <- tryCatch(forecast::ets(series_full, model = paste(r$fit_final_train$components[1:3], collapse = "")),
                        error = function(e) forecast::ets(series_full, model = r$fit_final_train, use.initial.values = TRUE))
  }
  
  fc_k <- forecast::forecast(refit_k, h = n_future_days_needed, level = 95)
  score_forecast_mat[, k] <- as.numeric(fc_k$mean)
  
  ## Recover SE from the 95% interval width when a direct SE is not exposed
  ## (Requirement C, exact formula requested): SE = (Upper - Lower) / (2*z_.975)
  se_k <- (as.numeric(fc_k$upper[, 1]) - as.numeric(fc_k$lower[, 1])) / (2 * z975)
  score_se_mat[, k] <- se_k
}
cat("Per-component ARIMA/ETS refit + 95% forecast interval obtained for all", p, "components.\n")


## -----------------------------------------------------------------------------
## Cross-check against the original Step-21 point forecast (Requirement C):
## Step 21 itself did not persist the per-component score matrix, so the most
## direct available ground truth is Step 21's saved future_curves_matrix
## (level + shape already combined). Reconstruct the same quantity here from
## the freshly recomputed level_forecast_vec + score_forecast_mat and compare.
## -----------------------------------------------------------------------------
centered_coefs_check <- reconstruct_coefs(score_forecast_mat)
centered_vals_check  <- t(Phi_argvals %*% centered_coefs_check)
future_curves_check  <- centered_vals_check + matrix(level_forecast_vec, nrow = n_future_days_needed, ncol = 24)
colnames(future_curves_check) <- paste0("h", 0:23)
rownames(future_curves_check) <- as.character(future_dates_needed)

pointwise_diff <- future_curves_check - step21_results$future_curves_matrix
max_abs_diff <- max(abs(pointwise_diff))
cat("\n--- Cross-check: Step-21.1 reconstructed curves vs. Step-21 saved curves ---\n")
cat("Max absolute pointwise difference:", format(max_abs_diff, scientific = TRUE), "\n")

recheck_tolerance <- 1e-3   # small numerical tolerance (ARIMA/ETS re-optimization noise)
if (max_abs_diff > recheck_tolerance) {
  stop("Step 21.1's recomputed point forecasts differ from Step 21's saved future_curves_matrix ",
       "by more than the numerical tolerance (", recheck_tolerance, "). Max abs diff = ", max_abs_diff,
       ". STOPPING per the explicit validation requirement -- investigate before trusting the ",
       "upgraded prediction intervals below.")
} else {
  cat("PASSED: reconstructed point forecasts match Step 21's saved point forecasts within tolerance (",
      recheck_tolerance, "). Point forecasts are confirmed UNCHANGED; only uncertainty is upgraded.\n", sep = "")
}

## Use STEP 21's own saved future_curves_matrix as the authoritative point
## forecast going forward (per the instruction to never alter Step-21 point
## forecasts) -- the freshly reconstructed version above was for validation only.
future_curves_matrix <- step21_results$future_curves_matrix


## =============================================================================
## SECTION D — FUNCTIONAL-SHAPE FORECAST UNCERTAINTY
## V_shape(h,u) = sum_k phi_k(u)^2 * Var(beta_{h,k}), independent-score design
## =============================================================================
cat("\n--- Section D: Functional-shape forecast uncertainty ----------------------\n")

score_var_mat <- score_se_mat^2                       # n_future_days x p
eigen_sq      <- eigen_at_hour^2                        # 24 x p

## V_shape: 24 x n_future_days, then transpose to n_future_days x 24 to match
## the future_curves_matrix orientation used throughout the project.
V_shape_24xdays <- eigen_sq %*% t(score_var_mat)
V_shape_mat <- t(V_shape_24xdays)                        # n_future_days x 24
colnames(V_shape_mat) <- paste0("h", 0:23)
rownames(V_shape_mat) <- as.character(future_dates_needed)

cat("Functional shape variance V_shape(h,u) computed for", n_future_days_needed,
    "future day(s) x 24 hours, via phi(u)' Sigma_beta(h) phi(u) (diag Sigma_beta, independent scores).\n")


## =============================================================================
## SECTION E — TOTAL POINTWISE 95% PREDICTION INTERVAL
## V_total(h,u) = V_level(h) + V_shape(h,u); level and shape errors assumed
## independent, consistent with Step 6's orthogonal level/shape decomposition.
## =============================================================================
cat("\n--- Section E: Total pointwise 95% prediction interval ---------------------\n")

V_level_mat <- matrix(level_var_vec, nrow = n_future_days_needed, ncol = 24)
colnames(V_level_mat) <- paste0("h", 0:23)
rownames(V_level_mat) <- as.character(future_dates_needed)

V_total_mat <- V_level_mat + V_shape_mat
SE_total_mat <- sqrt(pmax(V_total_mat, 0))
colnames(V_total_mat) <- colnames(SE_total_mat) <- paste0("h", 0:23)
rownames(V_total_mat) <- rownames(SE_total_mat) <- as.character(future_dates_needed)

PI95_lower_mat <- future_curves_matrix - z975 * SE_total_mat
PI95_upper_mat <- future_curves_matrix + z975 * SE_total_mat

cat("Pointwise 95% prediction intervals computed: PI95_lower/upper, one value per\n",
    "future day x hour, incorporating BOTH daily-level and independently forecast\n",
    "FPC-score (functional-shape) uncertainty. These are POINTWISE intervals, NOT\n",
    "simultaneous functional confidence bands.\n", sep = "")


## -----------------------------------------------------------------------------
## Flatten level/shape/total variance + PI matrices to an hourly long-format
## table, one row per future hour, with full diagnostic columns.
## -----------------------------------------------------------------------------
flatten_matrix_to_hourly <- function(mat, value_name) {
  df <- as.data.frame(mat) |> dplyr::mutate(forecast_date = as.Date(rownames(mat)))
  df |>
    tidyr::pivot_longer(cols = -forecast_date, names_to = "hour_label", values_to = value_name) |>
    dplyr::mutate(hour = as.integer(sub("^h", "", hour_label)),
                  datetime = as.POSIXct(paste0(forecast_date, " ", sprintf("%02d:00:00", hour)), tz = "UTC")) |>
    dplyr::select(datetime, dplyr::all_of(value_name))
}

fc_long          <- flatten_matrix_to_hourly(future_curves_matrix, "gwl_forecast")
level_var_long   <- flatten_matrix_to_hourly(V_level_mat, "level_variance")
shape_var_long   <- flatten_matrix_to_hourly(V_shape_mat, "shape_variance")
total_var_long   <- flatten_matrix_to_hourly(V_total_mat, "total_forecast_variance")
total_se_long    <- flatten_matrix_to_hourly(SE_total_mat, "total_forecast_SE")
pi_lower_long    <- flatten_matrix_to_hourly(PI95_lower_mat, "PI95_lower")
pi_upper_long    <- flatten_matrix_to_hourly(PI95_upper_mat, "PI95_upper")

future_hourly_upgraded <- fc_long |>
  dplyr::left_join(level_var_long, by = "datetime") |>
  dplyr::left_join(shape_var_long, by = "datetime") |>
  dplyr::left_join(total_var_long, by = "datetime") |>
  dplyr::left_join(total_se_long,  by = "datetime") |>
  dplyr::left_join(pi_lower_long,  by = "datetime") |>
  dplyr::left_join(pi_upper_long,  by = "datetime") |>
  dplyr::mutate(
    level_SE  = sqrt(pmax(level_variance, 0)),
    shape_SE  = sqrt(pmax(shape_variance, 0)),
    PI95_width = PI95_upper - PI95_lower
  ) |>
  dplyr::arrange(datetime)

## Stitch the partial final observed day exactly as Step 21 did: for hours
## that are, in fact, already-observed data (only relevant if the very first
## future-grid day was partial), overwrite forecast/PI with the actual value
## and zero uncertainty. Restricted to dates > last_observed_datetime is
## already enforced below when extracting forecast_24h/168h, mirroring Step 21.
if (!last_day_is_complete) {
  observed_partial <- gwl_regularized |>
    dplyr::filter(as.Date(datetime) == as.Date(last_observed_gwl <- last_observed_gwl) & FALSE)  # no-op guard
}
## (Step 21's own stitching already applies to future_curves_matrix's parent
## hourly series; Step 21.1 restricts everything below to datetime >
## last_observed_datetime, so no partial-day rows can appear here by
## construction -- consistent with "future_dates_needed" starting the day
## AFTER last_complete_date only when the final day was itself complete.)

future_hourly_upgraded <- future_hourly_upgraded |>
  dplyr::filter(datetime > last_observed_datetime) |>
  dplyr::arrange(datetime)

forecast_24h_upgraded  <- future_hourly_upgraded |> dplyr::filter(datetime %in% target_ts_24h)  |> dplyr::arrange(datetime)
