build_historical_future <- function(hist_hours, forecast_df) {
  hist_start <- last_observed_datetime - (hist_hours - 1) * 3600
  hist_df <- gwl_regularized |>
    dplyr::filter(datetime >= hist_start, datetime <= last_observed_datetime) |>
    dplyr::transmute(
      datetime, series_type = "Historical observed", observed_gwl = gwl,
      gwl_forecast = NA_real_, PI95_lower = NA_real_, PI95_upper = NA_real_,
      level_SE = NA_real_, shape_SE = NA_real_, total_forecast_SE = NA_real_,
      forecast_origin = last_observed_datetime
    )
  fut_df <- forecast_df |>
    dplyr::transmute(
      datetime, series_type = "Future forecast", observed_gwl = NA_real_,
      gwl_forecast, PI95_lower, PI95_upper, level_SE, shape_SE, total_forecast_SE,
      forecast_origin = last_observed_datetime
    )
  dplyr::bind_rows(hist_df, fut_df) |> dplyr::arrange(datetime)
}

