make_hist_future_plot <- function(df, title_txt, subtitle_txt) {
  hist_df <- df |> dplyr::filter(series_type == "Historical observed")
  fut_df  <- df |> dplyr::filter(series_type == "Future forecast")
  ggplot2::ggplot() +
    ggplot2::geom_ribbon(data = fut_df, ggplot2::aes(x = datetime, ymin = PI95_lower, ymax = PI95_upper),
                         fill = "steelblue1", alpha = 0.35, inherit.aes = FALSE) +
    ggplot2::geom_line(data = hist_df, ggplot2::aes(x = datetime, y = observed_gwl, colour = "Historical observed"),
                       linewidth = 0.45) +
    ggplot2::geom_line(data = fut_df, ggplot2::aes(x = datetime, y = gwl_forecast, colour = "Future forecast"),
                       linewidth = 0.6, linetype = "dashed") +
    ggplot2::geom_vline(xintercept = as.numeric(last_observed_datetime), linetype = "dotted", colour = "grey35") +
    ggplot2::annotate("text", x = last_observed_datetime, y = Inf, label = "Forecast origin",
                      angle = 90, vjust = -0.6, hjust = 1.1, size = 3, colour = "grey35") +
    ggplot2::scale_colour_manual(values = c("Historical observed" = "steelblue4", "Future forecast" = "firebrick3")) +
    ggplot2::labs(title = title_txt, subtitle = subtitle_txt, x = "Datetime", y = "GWL", colour = NULL) +
    pub_theme + ggplot2::theme(legend.position = "bottom")
}

