daily_summary_forecast <- forecast_168h |>
  dplyr::group_by(forecast_date) |>
  dplyr::summarise(mean_gwl = mean(gwl_forecast), min_gwl = min(gwl_forecast),
                   max_gwl = max(gwl_forecast), range_gwl = max_gwl - min_gwl, .groups = "drop") |>
  dplyr::mutate(daily_change = mean_gwl - dplyr::lag(mean_gwl))

cat("\n--- 7-day daily forecast summary (Basic GWL-FSSM) ---------------------------\n")
print(daily_summary_forecast)


## =============================================================================
