p2_168h <- ggplot2::ggplot() +
  {if (!all(is.na(forecast_168h$PI95_lower)))
    ggplot2::geom_ribbon(data = forecast_168h, ggplot2::aes(x = datetime, ymin = PI95_lower, ymax = PI95_upper),
                         fill = "seagreen1", alpha = 0.3, inherit.aes = FALSE)} +
  ggplot2::geom_line(data = recent_actual_wk, ggplot2::aes(datetime, value, colour = series), linewidth = 0.35) +
  ggplot2::geom_line(data = fc168_plot, ggplot2::aes(datetime, value, colour = series), linewidth = 0.5, linetype = "dashed") +
  ggplot2::geom_vline(xintercept = as.numeric(last_observed_datetime), linetype = "dotted", colour = "grey40") +
  ggplot2::scale_colour_manual(values = c(Observed = "steelblue4", Forecast = "seagreen4")) +
  ggplot2::labs(title = paste0(label_prefix, ": Next 168-Hour (7-Day) Forecast"),
                subtitle = "NOT the best-performing model (Step 21) -- FSSM-specific application only",
                x = "Datetime", y = "GWL", colour = NULL) +
