  tidyr::pivot_longer(cols = -date, names_to = "hour_label", values_to = "value") |>
  dplyr::mutate(hour = as.integer(sub("^h", "", hour_label)))

p4_heatmap <- ggplot2::ggplot(heatmap_df, ggplot2::aes(x = hour, y = date, fill = value)) +
  ggplot2::geom_raster() +
  ggplot2::scale_fill_viridis_c(name = "GWL") +
  ggplot2::scale_x_continuous(breaks = seq(0, 23, 6), expand = c(0, 0)) +
  ggplot2::scale_y_date(expand = c(0, 0)) +
  ggplot2::labs(title = paste0(label_prefix, ": Day x Hour Forecast Heatmap"),
                x = "Hour of day", y = "Date") +
