# =============================================================================
# STEP 22.1 — BASIC FSSM FULL PI + HISTORICAL/FUTURE PRESENTATION
# =============================================================================
## Project : Hourly Groundwater Level (GWL) analysis — well GT2648C03
## Continues directly from STEP 22 ("Basic GWL-FSSM genuine future
## forecasting"). Step 22 is NOT rewritten, refit, or replaced here. This
## script REUSES Step 22's saved, all-data-refitted level model and Basic
## FSSM (diagonal H, diagonal Q) exactly as fitted, and adds:
##   (1) a full pointwise 95% PREDICTIVE interval via Monte Carlo simulation
##       that propagates BOTH daily-level state/observation uncertainty AND
##       Basic-FSSM state/score uncertainty (the FSSM recursively forecasts
##       latent states and multiplicatively-coupled future scores, so a
##       closed-form analytic variance -- as used for the independent-score
##       model in Step 21.1 -- is not available here; Monte Carlo is used
##       instead, per explicit instruction);
##   (2) preservation of every existing Step-22 output file, unchanged;
##   (3) new historical(observed)+future(forecast) datasets and figures,
##       "22_1_"-prefixed.
## The existing Step-22 DETERMINISTIC point forecast is never replaced by
## the Monte Carlo mean; it remains the official "gwl_forecast".
## =============================================================================


## -----------------------------------------------------------------------------
## 0. PACKAGES, FOLDERS, CONFIGURABLE SIMULATION SETTINGS
## -----------------------------------------------------------------------------
required_packages <- c("dplyr", "tidyr", "lubridate", "ggplot2", "writexl",
                       "scales", "purrr", "fda", "KFAS")
missing_packages <- required_packages[!required_packages %in% installed.packages()[, "Package"]]
if (length(missing_packages) > 0) install.packages(missing_packages, dependencies = TRUE)
invisible(lapply(required_packages, library, character.only = TRUE))

dir.create("data_clean", showWarnings = FALSE)
dir.create("forecasts",  showWarnings = FALSE)
dir.create("figures",    showWarnings = FALSE)
dir.create("tables",     showWarnings = FALSE)

## Requirement A: B and seed are configurable simulation settings.
B    <- 5000
seed <- 20260101
set.seed(seed)

z975 <- qnorm(0.975)


## =============================================================================
## SECTION A — LOAD THE AUTHORITATIVE STEP-22 OUTPUT AND UPSTREAM OBJECTS
## (NOTHING IS RE-FIT, RE-SELECTED, OR RE-DERIVED IN THIS SECTION)
## =============================================================================
step22_path <- file.path("forecasts", "22_FSSM_future_forecast.rds")
stopifnot(file.exists(step22_path))
step22_results <- readRDS(step22_path)

cat("Loaded Step 22 authoritative output: forecasts/22_FSSM_future_forecast.rds\n")
cat("Label:", step22_results$label, "\n")
cat("H structure:", step22_results$H_structure, "| Q structure:", step22_results$Q_structure, "\n")
stopifnot(identical(step22_results$H_structure, "diagonal"), identical(step22_results$Q_structure, "diagonal"))
cat("Confirmed diagonal H / diagonal Q (Basic FSSM, Step 10 specification) -- UNCHANGED.\n")

p_load <- function(n) file.path("data_clean", n)
needed_files <- c("03_hourly_regularized_gwl.rds", "09_selected_fpca.rds", "13_seasonal_FSSM.rds")
missing_files <- needed_files[!file.exists(p_load(needed_files))]
if (length(missing_files) > 0) stop("Missing required upstream file(s): ", paste(missing_files, collapse = ", "))

gwl_regularized       <- readRDS(p_load("03_hourly_regularized_gwl.rds")) |> dplyr::arrange(datetime)
selected_fpca_results  <- readRDS(p_load("09_selected_fpca.rds"))
step13_results            <- readRDS(p_load("13_seasonal_FSSM.rds"))

## Functional reconstruction machinery -- EXACT existing Step-22 basis/mean/
## eigenfunctions/m; nothing re-fit here.
p               <- step22_results$p
score_cols        <- paste0("PC", 1:p)
meanfd              <- selected_fpca_results$meanfd
harmonics_selected     <- selected_fpca_results$harmonics_selected
basis_obj                <- selected_fpca_results$basis_obj
argvals                    <- selected_fpca_results$argvals

Phi_argvals     <- fda::eval.basis(argvals, basis_obj)     # 24 x K
mean_coefs_vec  <- as.numeric(meanfd$coefs)
harmonics_coefs <- harmonics_selected$coefs                 # K x p

## Forecast-origin / partial-day bookkeeping — REUSED, not recomputed.
last_observed_datetime <- step22_results$last_observed_datetime
last_observed_gwl      <- step22_results$last_observed_gwl
last_day_is_complete    <- step22_results$last_day_is_complete
last_complete_date       <- step22_results$last_complete_date

target_ts_24h  <- seq(last_observed_datetime + 3600, by = "hour", length.out = 24)
target_ts_168h <- seq(last_observed_datetime + 3600, by = "hour", length.out = 168)
future_dates_needed <- seq(last_complete_date + 1, as.Date(max(target_ts_168h)), by = "day")
n_future_days_needed <- length(future_dates_needed)

cat("\nForecast origin (unchanged from Step 22):", as.character(last_observed_datetime), "\n")
cat("Future days requiring simulation:", n_future_days_needed, "\n")
cat("Monte Carlo simulations B =", B, "| seed =", seed, "\n")


## =============================================================================
## SECTION B — REUSE THE STEP-22 FITTED DAILY-LEVEL MODEL (NOT RE-SELECTED,
## NOT REFIT) AND ITS FINAL FILTERED STATE DISTRIBUTION
## =============================================================================
cat("\n--- Section B: Daily-level model setup (REUSED from Step 22) --------------\n")

fit_level_refit <- step22_results$refit_level_fit
kfs_level_refit  <- step22_results$refit_level_kfs

base_label_fixed   <- step13_results$base_label
trend_degree_fixed  <- step13_results$trend_degree
K_fixed <- if (!is.null(step13_results$preferred_level_fit)) step13_results$preferred_K else 0L
seasonality_in_level <- K_fixed > 0
build_harmonics_local <- step13_results$build_harmonics

Tt_level <- matrix(fit_level_refit$model$T[, , 1], nrow = dim(fit_level_refit$model$T)[1])
Q_level  <- matrix(fit_level_refit$model$Q[, , 1], nrow = dim(fit_level_refit$model$Q)[1])
H_level  <- matrix(fit_level_refit$model$H[, , 1], nrow = dim(fit_level_refit$model$H)[1])
n_states_level <- nrow(Tt_level)
n_full_level <- nrow(kfs_level_refit$att)
level_state_hat <- kfs_level_refit$att[n_full_level, ]
level_P_hat      <- matrix(kfs_level_refit$Ptt[, , n_full_level], nrow = n_states_level)

## Z_j: derived from the fitted level model's own structure (trend + any
## deterministic harmonic regression states), exactly as in Step 21.1 -- the
## deterministic seasonal/harmonic contribution is preserved unchanged; only
## the trend state(s) are propagated stochastically.
build_Z_level <- function(doy_j) {
  Z_j <- rep(0, n_states_level)
  Z_j[1] <- 1
  if (seasonality_in_level) {
    harm_j <- as.numeric(build_harmonics_local(K_fixed, doy_j))
    Z_j[(n_states_level - 2 * K_fixed + 1):n_states_level] <- harm_j
  }
  Z_j
}

cat("Level model: trend degree =", trend_degree_fixed, ", harmonic K =", K_fixed,
    ", n_states =", n_states_level, "(reused, not re-selected).\n")


## =============================================================================
## SECTION C — REUSE THE STEP-22 FITTED BASIC FSSM (diagonal H, diagonal Q)
## AND ITS FINAL FILTERED STATE DISTRIBUTION
## =============================================================================
cat("\n--- Section C: Basic FSSM setup (REUSED from Step 22, diagonal H/Q) -------\n")

kfs_fssm_refit <- step22_results$refit_fssm_kfs
q_vars_refit    <- step22_results$q_vars_refit
h_vars_refit     <- step22_results$h_vars_refit
stopifnot(all(score_cols %in% names(q_vars_refit)), all(score_cols %in% names(h_vars_refit)))

n_t_all       <- nrow(kfs_fssm_refit$att)
alpha_hat     <- kfs_fssm_refit$att[n_t_all, ]                                  # final filtered state mean
alpha_P_hat    <- matrix(kfs_fssm_refit$Ptt[, , n_t_all], nrow = p)               # final filtered state covariance
last_score      <- as.numeric(kfs_fssm_refit$model$y[n_t_all, ])                    # last KNOWN (observed) score vector -- never simulated

cat("Basic FSSM: p =", p, "components, diagonal Q variances and diagonal H variances\n",
    "reused unchanged from Step 22's all-data refit.\n", sep = "")


## =============================================================================
## SECTION D — COVARIANCE VALIDITY CHECKS (Requirement J)
## =============================================================================
cat("\n--- Section D: Covariance-matrix validity checks ---------------------------\n")

eig_ok <- function(mat, tol = -1e-8) {
  if (length(mat) == 1) return(as.numeric(mat) >= tol)
  all(eigen(mat, symmetric = TRUE, only.values = TRUE)$values >= tol)
}
cov_checks <- data.frame(
  matrix = c("Q_level", "H_level", "level_P_hat (initial state cov.)",
             "Q_fssm (diag)", "H_fssm (diag)", "alpha_P_hat (initial state cov.)"),
  valid_psd = c(eig_ok(Q_level), eig_ok(H_level), eig_ok(level_P_hat),
                all(q_vars_refit >= -1e-8), all(h_vars_refit >= -1e-8), eig_ok(alpha_P_hat))
)
print(cov_checks)
if (!all(cov_checks$valid_psd)) stop("One or more covariance matrices failed the positive-semi-definiteness check -- see table above.")
cat("All covariance matrices confirmed valid (positive semi-definite).\n")


## =============================================================================
## SECTION E — MONTE CARLO PREDICTIVE SIMULATION
## -----------------------------------------------------------------------------
## Requirement A/B/C/D: B independent draws, no refitting inside the loop,
## the Step-22 deterministic point forecast is never altered by this section.
## A safe (eigen-based) multivariate normal sampler handles possibly
## near-singular covariance matrices (e.g. a 1x1 Q_level when trend degree=1,
## or filtered-state covariances with small/zero eigenvalues).
## =============================================================================
cat("\n--- Section E: Monte Carlo predictive simulation (B =", B, ") ---------------\n")

rmvn_safe <- function(n, mu, Sigma) {
  d <- length(mu)
  if (d == 1) return(matrix(rnorm(n, mean = mu, sd = sqrt(pmax(as.numeric(Sigma), 0))), ncol = 1))
  ee <- eigen(Sigma, symmetric = TRUE)
  vals <- pmax(ee$values, 0)
  A <- ee$vectors %*% diag(sqrt(vals), nrow = d)
  Zm <- matrix(rnorm(n * d), nrow = n, ncol = d)
  sweep(Zm %*% t(A), 2, mu, "+")
}

## --- D/B: daily-level simulation -------------------------------------------
## Initial state distribution drawn per simulation (Requirement B: "use the
## final filtered state distribution"); then recursively evolved with the
## SAME transition matrix T and process-noise covariance Q_level Step 22 used
## (no refitting); deterministic harmonic contribution preserved via Z_j.
level_state_mat <- rmvn_safe(B, level_state_hat, level_P_hat)   # B x n_states_level
level_sim_mat   <- matrix(NA_real_, nrow = B, ncol = n_future_days_needed)  # simulated L_j^(b)

for (j in seq_len(n_future_days_needed)) {
  proc_noise <- rmvn_safe(B, rep(0, n_states_level), Q_level)
  level_state_mat <- level_state_mat %*% t(Tt_level) + proc_noise
  doy_j <- lubridate::yday(future_dates_needed[j])
  Z_j <- build_Z_level(doy_j)
  obs_noise <- rnorm(B, mean = 0, sd = sqrt(pmax(H_level[1, 1], 0)))
  level_sim_mat[, j] <- as.numeric(level_state_mat %*% Z_j) + obs_noise
}
cat("Daily-level Monte Carlo simulation complete:", B, "trajectories x",
    n_future_days_needed, "future day(s).\n")

## --- D/C: Basic-FSSM score simulation --------------------------------------
## alpha_{j}^(b) = alpha_{j-1}^(b) + eta_j^(b), eta_j^(b) ~ N(0,Q)  (T = I,
## the fixed Basic-FSSM structure established since Step 10 -- not re-derived
## here, only reused);
## y_{j}^(b) = Z_j^(b) alpha_j^(b) + e_j^(b), e_j^(b) ~ N(0,H), with
## Z_j^(b) = diag(y_{j-1}^(b)) -- the SAME recursive Hadamard loading-matrix
## construction Step 22 used for its deterministic point forecast, applied
## here elementwise across all B simulations for efficiency (mathematically
## identical to building the p x p diagonal Z_j^(b) and computing Z_j^(b)
## alpha_j^(b) per simulation). The simulated y_j^(b) feeds forward into the
## NEXT day's loading matrix, exactly as instructed.
alpha_mat <- rmvn_safe(B, alpha_hat, alpha_P_hat)          # B x p
y_mat     <- matrix(rep(last_score, each = B), nrow = B, ncol = p)   # known, deterministic starting point (never simulated)

q_sd_vec <- sqrt(pmax(q_vars_refit[score_cols], 0))
h_sd_vec <- sqrt(pmax(h_vars_refit[score_cols], 0))

score_sims_by_day <- vector("list", n_future_days_needed)

for (j in seq_len(n_future_days_needed)) {
  eta_mat <- matrix(rnorm(B * p, mean = 0, sd = rep(q_sd_vec, each = B)), nrow = B, ncol = p)
  alpha_mat <- alpha_mat + eta_mat                                     # T = I
  e_mat <- matrix(rnorm(B * p, mean = 0, sd = rep(h_sd_vec, each = B)), nrow = B, ncol = p)
  y_mat_new <- y_mat * alpha_mat + e_mat                                  # Hadamard: diag(y_prev) %*% alpha == y_prev * alpha
  score_sims_by_day[[j]] <- y_mat_new
  y_mat <- y_mat_new    # feed forward into the next day's loading matrix
}
cat("Basic-FSSM Monte Carlo score simulation complete:", B, "trajectories x",
    n_future_days_needed, "future day(s) x", p, "components.\n")


## =============================================================================
## SECTION F — RECONSTRUCT SIMULATED GWL CURVES AND SUMMARIZE (Requirement D/E)
## X_j^(b)(u) = L_j^(b) + mu_c(u) + sum_k beta_jk^(b) phi_k(u)
## Uses the EXACT existing Step-22 B-spline basis, mean function, FPC
## eigenfunctions, selected m, hour grid, and level-shape decomposition.
## =============================================================================
cat("\n--- Section F: Reconstruct simulated curves; compute pointwise 95% PI -----\n")

predictive_mean_mat   <- matrix(NA_real_, nrow = n_future_days_needed, ncol = 24)
predictive_median_mat <- matrix(NA_real_, nrow = n_future_days_needed, ncol = 24)
predictive_sd_mat     <- matrix(NA_real_, nrow = n_future_days_needed, ncol = 24)
PI95_lower_mat          <- matrix(NA_real_, nrow = n_future_days_needed, ncol = 24)
PI95_upper_mat           <- matrix(NA_real_, nrow = n_future_days_needed, ncol = 24)

for (j in seq_len(n_future_days_needed)) {
  scores_b <- score_sims_by_day[[j]]                                    # B x p
  centered_coefs_b <- matrix(mean_coefs_vec, nrow = length(mean_coefs_vec), ncol = B) +
    harmonics_coefs %*% t(scores_b)                                       # K x B
  centered_vals_b <- t(Phi_argvals %*% centered_coefs_b)                    # B x 24
  X_sim_day_j <- centered_vals_b + matrix(level_sim_mat[, j], nrow = B, ncol = 24)  # B x 24
  
  predictive_mean_mat[j, ]   <- colMeans(X_sim_day_j)
  predictive_median_mat[j, ] <- apply(X_sim_day_j, 2, median)
  predictive_sd_mat[j, ]      <- apply(X_sim_day_j, 2, sd)
  PI95_lower_mat[j, ]           <- apply(X_sim_day_j, 2, quantile, probs = 0.025, names = FALSE, type = 7)
  PI95_upper_mat[j, ]            <- apply(X_sim_day_j, 2, quantile, probs = 0.975, names = FALSE, type = 7)
}
colnames(predictive_mean_mat) <- colnames(predictive_median_mat) <- colnames(predictive_sd_mat) <-
  colnames(PI95_lower_mat) <- colnames(PI95_upper_mat) <- paste0("h", 0:23)
rownames(predictive_mean_mat) <- rownames(predictive_median_mat) <- rownames(predictive_sd_mat) <-
  rownames(PI95_lower_mat) <- rownames(PI95_upper_mat) <- as.character(future_dates_needed)

pi_methodology_description <- paste(
  "Pointwise 95% predictive intervals obtained by Monte Carlo propagation",
  "(B =", B, "simulations, seed =", seed, ") of daily-level state/observation",
  "uncertainty and Basic-FSSM (diagonal H, diagonal Q) state/score uncertainty.",
  "PI95_lower/upper are the empirical 2.5th/97.5th percentiles of the simulated",
  "GWL distribution at each future hour. The OFFICIAL point forecast remains",
  "Step 22's own deterministic gwl_forecast (NOT the Monte Carlo mean/median,",
  "which are reported alongside only as diagnostics). These are POINTWISE",
  "predictive intervals, not simultaneous functional bands."
)
cat(pi_methodology_description, "\n")


## =============================================================================
## SECTION G — BUILD UPGRADED FORECAST TABLES (24h / 168h), KEEPING STEP-22's
## DETERMINISTIC POINT FORECAST AS THE OFFICIAL gwl_forecast
## =============================================================================
cat("\n--- Section G: Build upgraded forecast tables -------------------------------\n")

future_curves_matrix <- step22_results$future_curves_matrix   # Step-22's own deterministic point forecast, UNCHANGED

flatten_matrix_to_hourly <- function(mat, value_name) {
  df <- as.data.frame(mat) |> dplyr::mutate(forecast_date = as.Date(rownames(mat)))
  df |>
    tidyr::pivot_longer(cols = -forecast_date, names_to = "hour_label", values_to = value_name) |>
    dplyr::mutate(hour = as.integer(sub("^h", "", hour_label)),
                  datetime = as.POSIXct(paste0(forecast_date, " ", sprintf("%02d:00:00", hour)), tz = "UTC")) |>
    dplyr::select(datetime, dplyr::all_of(value_name))
}

fc_long        <- flatten_matrix_to_hourly(future_curves_matrix, "gwl_forecast")   # official, deterministic (Step 22)
pmean_long     <- flatten_matrix_to_hourly(predictive_mean_mat, "predictive_mean")
pmedian_long   <- flatten_matrix_to_hourly(predictive_median_mat, "predictive_median")
psd_long       <- flatten_matrix_to_hourly(predictive_sd_mat, "predictive_sd")
pi_lower_long  <- flatten_matrix_to_hourly(PI95_lower_mat, "PI95_lower")
pi_upper_long  <- flatten_matrix_to_hourly(PI95_upper_mat, "PI95_upper")

future_hourly_upgraded <- fc_long |>
  dplyr::left_join(pmean_long,  by = "datetime") |>
  dplyr::left_join(pmedian_long, by = "datetime") |>
  dplyr::left_join(psd_long,     by = "datetime") |>
  dplyr::left_join(pi_lower_long, by = "datetime") |>
  dplyr::left_join(pi_upper_long,  by = "datetime") |>
  dplyr::mutate(PI95_width = PI95_upper - PI95_lower) |>
  dplyr::filter(datetime > last_observed_datetime) |>
  dplyr::arrange(datetime)

forecast_24h  <- future_hourly_upgraded |> dplyr::filter(datetime %in% target_ts_24h)  |> dplyr::arrange(datetime)
forecast_168h <- future_hourly_upgraded |> dplyr::filter(datetime %in% target_ts_168h) |> dplyr::arrange(datetime)

stopifnot(nrow(forecast_24h) == 24)
stopifnot(nrow(forecast_168h) == 168)
cat("VERIFIED: nrow(forecast_24h) == 24  ->", nrow(forecast_24h) == 24, "\n")
cat("VERIFIED: nrow(forecast_168h) == 168 ->", nrow(forecast_168h) == 168, "\n")


## =============================================================================
## SECTION H — EXISTING STEP-22 OUTPUTS: EXPLICITLY PRESERVED, NOT MODIFIED
## =============================================================================
cat("\n--- Section H: Existing Step-22 outputs -------------------------------------\n")
cat("The following Step-22 files are NOT modified, overwritten, or renamed:\n",
    "  forecasts/22_basic_FSSM_future_forecast.xlsx, forecasts/22_FSSM_future_24h.csv,\n",
    "  forecasts/22_FSSM_future_168h.csv, forecasts/22_daily_summary_forecast.csv,\n",
    "  forecasts/22_fssm_specification_table.csv, forecasts/22_FSSM_future_forecast.rds,\n",
    "  models/22_final_refitted_FSSM.rds,\n",
    "  figures/22_01_basic_FSSM_24h_forecast.*, figures/22_02_basic_FSSM_168h_forecast.*,\n",
    "  figures/22_03_basic_FSSM_seven_daily_curves.*, figures/22_04_basic_FSSM_dayhour_heatmap.*.\n",
    "Only the NEW, separately-prefixed '22_1_' outputs below use the upgraded PI.\n", sep = "")


## =============================================================================
## SECTION I — HISTORICAL + FUTURE DATASETS (Requirement G)
## =============================================================================
cat("\n--- Section I: Historical + future datasets ---------------------------------\n")

build_historical_future <- function(hist_hours, forecast_df) {
  hist_start <- last_observed_datetime - (hist_hours - 1) * 3600
  hist_df <- gwl_regularized |>
    dplyr::filter(datetime >= hist_start, datetime <= last_observed_datetime) |>
    dplyr::transmute(
      datetime, series_type = "Historical observed", observed_gwl = gwl,
      gwl_forecast = NA_real_, PI95_lower = NA_real_, PI95_upper = NA_real_,
      predictive_sd = NA_real_, forecast_origin = last_observed_datetime
    )
  fut_df <- forecast_df |>
    dplyr::transmute(
      datetime, series_type = "Future forecast", observed_gwl = NA_real_,
      gwl_forecast, PI95_lower, PI95_upper, predictive_sd,
      forecast_origin = last_observed_datetime
    )
  dplyr::bind_rows(hist_df, fut_df) |> dplyr::arrange(datetime)
}

historical_future_24h  <- build_historical_future(72,  forecast_24h)
historical_future_168h <- build_historical_future(336, forecast_168h)

cat("historical_future_24h  built:", nrow(historical_future_24h),  "rows (72h historical + 24h future).\n")
cat("historical_future_168h built:", nrow(historical_future_168h), "rows (336h/14d historical + 168h future).\n")


## =============================================================================
## SECTION J — VALIDATION (Requirement J)
## =============================================================================
cat("\n--- Section J: Validation ----------------------------------------------------\n")

n_hist_24  <- sum(historical_future_24h$series_type  == "Historical observed")
n_fut_24   <- sum(historical_future_24h$series_type  == "Future forecast")
n_hist_168 <- sum(historical_future_168h$series_type == "Historical observed")
n_fut_168  <- sum(historical_future_168h$series_type == "Future forecast")

chk_n24_total  <- nrow(forecast_24h) == 24
chk_n168_total <- nrow(forecast_168h) == 168
chk_hist72     <- n_hist_24 == 72
chk_fut24      <- n_fut_24 == 24
chk_hist336    <- n_hist_168 == 336
chk_fut168     <- n_fut_168 == 168
chk_future_after_origin <- all(forecast_168h$datetime > last_observed_datetime) && all(forecast_24h$datetime > last_observed_datetime)
chk_hist_only_actual_24  <- all(!is.na(historical_future_24h$observed_gwl[historical_future_24h$series_type == "Historical observed"])) &&
  all(is.na(historical_future_24h$gwl_forecast[historical_future_24h$series_type == "Historical observed"]))
chk_hist_only_actual_168 <- all(!is.na(historical_future_168h$observed_gwl[historical_future_168h$series_type == "Historical observed"])) &&
  all(is.na(historical_future_168h$gwl_forecast[historical_future_168h$series_type == "Historical observed"]))
chk_fut_no_actual_24  <- all(is.na(historical_future_24h$observed_gwl[historical_future_24h$series_type == "Future forecast"]))
chk_fut_no_actual_168 <- all(is.na(historical_future_168h$observed_gwl[historical_future_168h$series_type == "Future forecast"]))
chk_no_hist_pi_24  <- all(is.na(historical_future_24h$PI95_lower[historical_future_24h$series_type == "Historical observed"]))
chk_no_hist_pi_168 <- all(is.na(historical_future_168h$PI95_lower[historical_future_168h$series_type == "Historical observed"]))
chk_pi_ordering <- all(forecast_168h$PI95_lower <= forecast_168h$PI95_upper)
chk_point_forecast_unchanged <- max(abs(future_curves_matrix - step22_results$future_curves_matrix)) < 1e-12

validation_checks <- data.frame(
  check = c("nrow(forecast_24h) == 24", "nrow(forecast_168h) == 168",
            "historical_future_24h historical rows == 72", "historical_future_24h future rows == 24",
            "historical_future_168h historical rows == 336", "historical_future_168h future rows == 168",
            "all future timestamps > last_observed_datetime",
            "historical portion contains only actual observed GWL (24h)",
            "historical portion contains only actual observed GWL (168h)",
            "future portion contains no unavailable actual GWL (24h)",
            "future portion contains no unavailable actual GWL (168h)",
            "no artificial PI on historical rows (24h)", "no artificial PI on historical rows (168h)",
            "PI95_lower <= PI95_upper", "Step-22 point forecast unchanged (gwl_forecast)"),
  passed = c(chk_n24_total, chk_n168_total, chk_hist72, chk_fut24, chk_hist336, chk_fut168,
             chk_future_after_origin, chk_hist_only_actual_24, chk_hist_only_actual_168,
             chk_fut_no_actual_24, chk_fut_no_actual_168, chk_no_hist_pi_24, chk_no_hist_pi_168,
             chk_pi_ordering, chk_point_forecast_unchanged)
)
print(validation_checks)
if (!all(validation_checks$passed)) stop("One or more Step 22.1 validation checks FAILED -- see table above.")
cat("\nAll Step 22.1 validation checks PASSED. No future leakage detected.\n")


## =============================================================================
## SECTION K — NEW PUBLICATION-QUALITY HISTORICAL + FUTURE FIGURES
## =============================================================================
cat("\n--- Section K: New historical + future figures --------------------------------\n")

pub_theme <- ggplot2::theme_minimal(base_size = 12) +
  ggplot2::theme(plot.title = ggplot2::element_text(face = "bold"),
                 panel.grid.minor = ggplot2::element_blank())

## Colour scheme matches Step 22's own Basic-FSSM plots (seagreen family).
make_hist_future_plot <- function(df, title_txt, subtitle_txt) {
  hist_df <- df |> dplyr::filter(series_type == "Historical observed")
  fut_df  <- df |> dplyr::filter(series_type == "Future forecast")
  ggplot2::ggplot() +
    ggplot2::geom_ribbon(data = fut_df, ggplot2::aes(x = datetime, ymin = PI95_lower, ymax = PI95_upper),
                         fill = "seagreen1", alpha = 0.35, inherit.aes = FALSE) +
    ggplot2::geom_line(data = hist_df, ggplot2::aes(x = datetime, y = observed_gwl, colour = "Historical observed"),
                       linewidth = 0.45) +
    ggplot2::geom_line(data = fut_df, ggplot2::aes(x = datetime, y = gwl_forecast, colour = "Future forecast"),
                       linewidth = 0.6, linetype = "dashed") +
    ggplot2::geom_vline(xintercept = as.numeric(last_observed_datetime), linetype = "dotted", colour = "grey35") +
    ggplot2::annotate("text", x = last_observed_datetime, y = Inf, label = "Forecast origin",
                      angle = 90, vjust = -0.6, hjust = 1.1, size = 3, colour = "grey35") +
    ggplot2::scale_colour_manual(values = c("Historical observed" = "steelblue4", "Future forecast" = "seagreen4")) +
    ggplot2::labs(title = title_txt, subtitle = subtitle_txt, x = "Datetime", y = "GWL", colour = NULL) +
    pub_theme + ggplot2::theme(legend.position = "bottom")
}

fig_22_1A_24h <- make_hist_future_plot(
  historical_future_24h,
  "Observed and Basic GWL-FSSM Forecast: 24-Hour Horizon",
  "Final 72 observed hours followed by 24-hour Basic GWL-FSSM forecast; shaded area = pointwise 95% predictive interval."
)

fig_22_1B_168h <- make_hist_future_plot(
  historical_future_168h,
  "Observed and Basic GWL-FSSM Forecast: 7-Day Horizon",
  "Final 14 observed days followed by 168-hour Basic GWL-FSSM forecast; shaded area = pointwise 95% predictive interval."
)

cat("Two new historical+future figures generated (22.1A: 24h, 22.1B: 168h).\n")


