# =============================================================================
# STEP 23.1 — SELECTED FSSM FULL PI + HISTORICAL/FUTURE PRESENTATION
# =============================================================================
## Project : Hourly Groundwater Level (GWL) analysis — well GT2648C03
## Continues directly from STEP 23 ("Final GWL-FSSM genuine future
## forecasting", using Step 11's PREFERRED H/Q covariance structure). Step 23
## is NOT rewritten, refit, or replaced here. This script REUSES Step 23's
## saved, all-data-refitted level model and selected FSSM (whatever H/Q
## structure Step 11 actually preferred -- zero/diagonal/full, for H and Q
## independently) exactly as fitted, and adds:
##   (1) a full pointwise 95% PREDICTIVE interval via Monte Carlo simulation
##       that propagates daily-level state/observation uncertainty AND the
##       selected FSSM's latent-state / future-score uncertainty, INCLUDING
##       cross-component covariance whenever the selected H and/or Q matrix
##       is full (never silently diagonalized);
##   (2) preservation of every existing Step-23 output file, unchanged;
##   (3) new historical(observed)+future(forecast) datasets and figures,
##       "23_1_"-prefixed.
## The existing Step-23 DETERMINISTIC point forecast is never replaced by
## the Monte Carlo mean; it remains the official "gwl_forecast", and this is
## verified with an explicit all.equal()-based check.
## =============================================================================


## -----------------------------------------------------------------------------
## 0. PACKAGES, FOLDERS, CONFIGURABLE SIMULATION SETTINGS
## -----------------------------------------------------------------------------
required_packages <- c("dplyr", "tidyr", "lubridate", "ggplot2", "writexl",
                       "scales", "purrr", "fda", "KFAS")
missing_packages <- required_packages[!required_packages %in% installed.packages()[, "Package"]]
if (length(missing_packages) > 0) install.packages(missing_packages, dependencies = TRUE)
invisible(lapply(required_packages, library, character.only = TRUE))

dir.create("data_clean", showWarnings = FALSE)
dir.create("forecasts",  showWarnings = FALSE)
dir.create("figures",    showWarnings = FALSE)
dir.create("tables",     showWarnings = FALSE)

## Requirement A: B and seed are configurable simulation settings.
B    <- 5000
seed <- 20260101
set.seed(seed)

z975 <- qnorm(0.975)


## =============================================================================
## SECTION A — LOAD THE AUTHORITATIVE STEP-23 OUTPUT AND UPSTREAM OBJECTS
## (NOTHING IS RE-FIT, RE-SELECTED, OR RE-DERIVED IN THIS SECTION)
## =============================================================================
step23_path <- file.path("forecasts", "23_FSSM_future_forecast.rds")
stopifnot(file.exists(step23_path))
step23_results <- readRDS(step23_path)

cat("Loaded Step 23 authoritative output: forecasts/23_FSSM_future_forecast.rds\n")
cat("Label:", step23_results$label, "\n")

## Requirement B: read the EXISTING selected Step-11 structure, do not
## re-select, do not force diagonal, do not discard off-diagonal covariance.
H_type_fixed <- step23_results$H_structure
Q_type_fixed <- step23_results$Q_structure
preferred_structure_label <- step23_results$preferred_structure_label
cat("Selected Step-11 structure (READ, not re-selected): H =", H_type_fixed,
    "| Q =", Q_type_fixed, "| label:", preferred_structure_label, "\n")

p_load <- function(n) file.path("data_clean", n)
needed_files <- c("03_hourly_regularized_gwl.rds", "09_selected_fpca.rds", "13_seasonal_FSSM.rds")
missing_files <- needed_files[!file.exists(p_load(needed_files))]
if (length(missing_files) > 0) stop("Missing required upstream file(s): ", paste(missing_files, collapse = ", "))

gwl_regularized       <- readRDS(p_load("03_hourly_regularized_gwl.rds")) |> dplyr::arrange(datetime)
selected_fpca_results  <- readRDS(p_load("09_selected_fpca.rds"))
step13_results            <- readRDS(p_load("13_seasonal_FSSM.rds"))

## Functional reconstruction machinery -- EXACT existing Step-23 basis/mean/
## eigenfunctions/m; nothing re-fit here.
p               <- step23_results$p
score_cols        <- paste0("PC", 1:p)
meanfd              <- selected_fpca_results$meanfd
harmonics_selected     <- selected_fpca_results$harmonics_selected
basis_obj                <- selected_fpca_results$basis_obj
argvals                    <- selected_fpca_results$argvals

Phi_argvals     <- fda::eval.basis(argvals, basis_obj)     # 24 x K
mean_coefs_vec  <- as.numeric(meanfd$coefs)
harmonics_coefs <- harmonics_selected$coefs                 # K x p

## Forecast-origin / partial-day bookkeeping — REUSED, not recomputed.
last_observed_datetime <- step23_results$last_observed_datetime
last_observed_gwl      <- step23_results$last_observed_gwl
last_day_is_complete    <- step23_results$last_day_is_complete
last_complete_date       <- step23_results$last_complete_date

target_ts_24h  <- seq(last_observed_datetime + 3600, by = "hour", length.out = 24)
target_ts_168h <- seq(last_observed_datetime + 3600, by = "hour", length.out = 168)
future_dates_needed <- seq(last_complete_date + 1, as.Date(max(target_ts_168h)), by = "day")
n_future_days_needed <- length(future_dates_needed)

cat("\nForecast origin (unchanged from Step 23):", as.character(last_observed_datetime), "\n")
cat("Future days requiring simulation:", n_future_days_needed, "\n")
cat("Monte Carlo simulations B =", B, "| seed =", seed, "\n")


## =============================================================================
## SECTION B — REUSE THE STEP-23 FITTED DAILY-LEVEL MODEL (NOT RE-SELECTED,
## NOT REFIT) AND ITS FINAL FILTERED STATE DISTRIBUTION
## =============================================================================
cat("\n--- Section B: Daily-level model setup (REUSED from Step 23) --------------\n")

fit_level_refit <- step23_results$refit_level_fit
kfs_level_refit  <- step23_results$refit_level_kfs

base_label_fixed   <- step13_results$base_label
trend_degree_fixed  <- step13_results$trend_degree
K_fixed <- if (!is.null(step13_results$preferred_level_fit)) step13_results$preferred_K else 0L
seasonality_in_level <- K_fixed > 0
build_harmonics_local <- step13_results$build_harmonics

Tt_level <- matrix(fit_level_refit$model$T[, , 1], nrow = dim(fit_level_refit$model$T)[1])
Q_level  <- matrix(fit_level_refit$model$Q[, , 1], nrow = dim(fit_level_refit$model$Q)[1])
H_level  <- matrix(fit_level_refit$model$H[, , 1], nrow = dim(fit_level_refit$model$H)[1])
n_states_level <- nrow(Tt_level)
n_full_level <- nrow(kfs_level_refit$att)
level_state_hat <- kfs_level_refit$att[n_full_level, ]
level_P_hat      <- matrix(kfs_level_refit$Ptt[, , n_full_level], nrow = n_states_level)

## Z_j: derived from the fitted level model's own structure (trend + any
## deterministic harmonic regression states) -- deterministic seasonal/
## harmonic contribution preserved unchanged; only trend state(s) stochastic.
build_Z_level <- function(doy_j) {
  Z_j <- rep(0, n_states_level)
  Z_j[1] <- 1
  if (seasonality_in_level) {
    harm_j <- as.numeric(build_harmonics_local(K_fixed, doy_j))
    Z_j[(n_states_level - 2 * K_fixed + 1):n_states_level] <- harm_j
  }
  Z_j
}
cat("Level model: trend degree =", trend_degree_fixed, ", harmonic K =", K_fixed,
    ", n_states =", n_states_level, "(reused, not re-selected).\n")


## =============================================================================
## SECTION C — REUSE THE STEP-23 FITTED SELECTED FSSM (Step 11's PREFERRED
## H/Q structure) AND ITS FINAL FILTERED STATE DISTRIBUTION
## =============================================================================
cat("\n--- Section C: Selected FSSM setup (REUSED from Step 23) ------------------\n")

kfs_fssm_refit <- step23_results$refit_fssm_kfs
Q_hat            <- step23_results$Q_hat_refit    # p x p, ALREADY reflects the actual selected structure
H_hat             <- step23_results$H_hat_refit    # (zero matrix / diagonal / full, as selected in Step 11)
stopifnot(nrow(Q_hat) == p, ncol(Q_hat) == p, nrow(H_hat) == p, ncol(H_hat) == p)

n_t_all       <- nrow(kfs_fssm_refit$att)
alpha_hat     <- kfs_fssm_refit$att[n_t_all, ]                                  # final filtered state mean
alpha_P_hat    <- matrix(kfs_fssm_refit$Ptt[, , n_t_all], nrow = p)               # final filtered state covariance
last_score      <- as.numeric(kfs_fssm_refit$model$y[n_t_all, ])                    # last KNOWN (observed) score vector -- never simulated

cat("Selected FSSM: p =", p, "components. H type =", H_type_fixed, ", Q type =", Q_type_fixed,
    " -- fitted Q_hat/H_hat matrices REUSED unchanged from Step 23's all-data refit.\n", sep = "")


## =============================================================================
## SECTION D — COVARIANCE DIAGNOSTICS AND VALIDITY CHECKS (Requirement E/M)
## =============================================================================
cat("\n--- Section D: Covariance diagnostics and validity checks ------------------\n")

min_eig <- function(mat) {
  if (length(mat) == 1) return(as.numeric(mat))
  min(eigen(mat, symmetric = TRUE, only.values = TRUE)$values)
}
min_eig_Q_level <- min_eig(Q_level)
min_eig_H_level  <- min_eig(H_level)
min_eig_Q_fssm    <- min_eig(Q_hat)
min_eig_H_fssm     <- min_eig(H_hat)
min_eig_level_Phat   <- min_eig(level_P_hat)
min_eig_alpha_Phat     <- min_eig(alpha_P_hat)

cat("Minimum eigenvalue, Q_level               :", format(min_eig_Q_level, scientific = TRUE), "\n")
cat("Minimum eigenvalue, H_level                :", format(min_eig_H_level, scientific = TRUE), "\n")
cat("Minimum eigenvalue, Q (selected FSSM, ", Q_type_fixed, ") :", format(min_eig_Q_fssm, scientific = TRUE), "\n", sep = "")
cat("Minimum eigenvalue, H (selected FSSM, ", H_type_fixed, ") :", format(min_eig_H_fssm, scientific = TRUE), "\n", sep = "")

tol_eig <- -1e-8
cov_checks <- data.frame(
  matrix = c("Q_level", "H_level", "level_P_hat (initial state cov.)",
             paste0("Q (selected FSSM, ", Q_type_fixed, ")"), paste0("H (selected FSSM, ", H_type_fixed, ")"),
             "alpha_P_hat (initial state cov.)"),
  min_eigenvalue = c(min_eig_Q_level, min_eig_H_level, min_eig_level_Phat,
                     min_eig_Q_fssm, min_eig_H_fssm, min_eig_alpha_Phat),
  valid_psd = c(min_eig_Q_level, min_eig_H_level, min_eig_level_Phat,
                min_eig_Q_fssm, min_eig_H_fssm, min_eig_alpha_Phat) >= tol_eig
)
print(cov_checks)
if (!all(cov_checks$valid_psd)) stop("One or more covariance matrices failed the positive-semi-definiteness check -- see table above.")
cat("All covariance matrices confirmed valid (positive semi-definite).\n")


## =============================================================================
## SECTION E — MONTE CARLO PREDICTIVE SIMULATION
## -----------------------------------------------------------------------------
## Requirement A/D/E/F: B independent draws, no refitting inside the loop,
## the Step-23 deterministic point forecast is never altered here. A
## numerically stable sampler is used for every multivariate draw: Cholesky
## first, with an eigen-decomposition fallback for near-singular / exactly
## positive-semidefinite matrices (e.g. Q = 0, or a rank-deficient filtered
## state covariance). This is REQUIRED (not optional) whenever H and/or Q is
## "full", so that the complete cross-component covariance structure
## selected in Step 11 is genuinely propagated, not silently diagonalized.
## =============================================================================
cat("\n--- Section E: Monte Carlo predictive simulation (B =", B, ") ---------------\n")

build_mvn_draw_fn <- function(Sigma) {
  d <- nrow(Sigma)
  if (d == 1) {
    sd1 <- sqrt(pmax(as.numeric(Sigma), 0))
    return(list(draw = function(n) matrix(rnorm(n, mean = 0, sd = sd1), ncol = 1), method = "scalar"))
  }
  A <- tryCatch(t(chol(Sigma)), error = function(e) NULL)
  method <- "cholesky"
  if (is.null(A)) {
    ee <- eigen(Sigma, symmetric = TRUE)
    vals <- pmax(ee$values, 0)
    A <- ee$vectors %*% diag(sqrt(vals), nrow = d)
    method <- "eigen_fallback"
  }
  list(draw = function(n) { Zm <- matrix(rnorm(n * d), nrow = n, ncol = d); Zm %*% t(A) }, method = method)
}

## --- D: daily-level simulation ---------------------------------------------
level_init_sampler <- build_mvn_draw_fn(level_P_hat)
level_proc_sampler  <- build_mvn_draw_fn(Q_level)
cat("Level model: initial-state sampler method =", level_init_sampler$method,
    "| process-noise sampler method =", level_proc_sampler$method, "\n")

level_state_mat <- matrix(rep(level_state_hat, each = B), nrow = B, ncol = n_states_level) + level_init_sampler$draw(B)
level_sim_mat   <- matrix(NA_real_, nrow = B, ncol = n_future_days_needed)

for (j in seq_len(n_future_days_needed)) {
  proc_noise <- level_proc_sampler$draw(B)
  level_state_mat <- level_state_mat %*% t(Tt_level) + proc_noise
  doy_j <- lubridate::yday(future_dates_needed[j])
  Z_j <- build_Z_level(doy_j)
  obs_noise <- rnorm(B, mean = 0, sd = sqrt(pmax(H_level[1, 1], 0)))
  level_sim_mat[, j] <- as.numeric(level_state_mat %*% Z_j) + obs_noise
}
cat("Daily-level Monte Carlo simulation complete:", B, "trajectories x",
    n_future_days_needed, "future day(s).\n")

## --- E/F: selected-FSSM state and score simulation -------------------------
## alpha_{j}^(b) = alpha_{j-1}^(b) + eta_j^(b), eta_j^(b) ~ N(0,Q)  (T = I,
## the fixed structure established since Step 10/11 across ALL six H/Q
## variants -- Z_t/T remain diagonal/identity even for "full" H or Q, so no
## re-derivation is needed here, only reuse);
## y_{j}^(b) = Z_j^(b) alpha_j^(b) + e_j^(b), e_j^(b) ~ N(0,H), with
## Z_j^(b) = diag(y_{j-1}^(b)) -- the SAME recursive Hadamard loading-matrix
## construction Step 23 used for its deterministic point forecast, applied
## elementwise across all B simulations. eta_j^(b) and e_j^(b) are drawn
## JOINTLY across all p components using the FULL Q_hat / H_hat matrices
## (via build_mvn_draw_fn), so cross-component covariance is genuinely
## propagated whenever the selected structure is "full" -- never diagonalized.
alpha_init_sampler <- build_mvn_draw_fn(alpha_P_hat)
q_sampler            <- build_mvn_draw_fn(Q_hat)
h_sampler             <- build_mvn_draw_fn(H_hat)
cat("Selected FSSM: initial-alpha sampler method =", alpha_init_sampler$method,
    "| Q sampler method =", q_sampler$method, "| H sampler method =", h_sampler$method, "\n")

alpha_mat <- matrix(rep(alpha_hat, each = B), nrow = B, ncol = p) + alpha_init_sampler$draw(B)
y_mat     <- matrix(rep(last_score, each = B), nrow = B, ncol = p)   # known, deterministic starting point -- never simulated

score_sims_by_day <- vector("list", n_future_days_needed)

for (j in seq_len(n_future_days_needed)) {
  eta_mat <- q_sampler$draw(B)                                          # B x p, JOINT draw (full cross-component covariance if Q full)
  alpha_mat <- alpha_mat + eta_mat                                        # T = I
  e_mat <- h_sampler$draw(B)                                                # B x p, JOINT draw (full cross-component covariance if H full)
  y_mat_new <- y_mat * alpha_mat + e_mat                                      # Hadamard: diag(y_prev) %*% alpha == y_prev * alpha
  score_sims_by_day[[j]] <- y_mat_new
  y_mat <- y_mat_new    # feed forward into the next day's loading matrix (Requirement F)
}
cat("Selected-FSSM Monte Carlo score simulation complete:", B, "trajectories x",
    n_future_days_needed, "future day(s) x", p, "components.\n",
    "No actual future scores or GWL observations were used at any point.\n", sep = "")


## =============================================================================
## SECTION F — RECONSTRUCT SIMULATED GWL CURVES AND SUMMARIZE (Requirement G/H)
## X_j^(b)(u) = L_j^(b) + mu_c(u) + sum_k beta_jk^(b) phi_k(u)
## Uses the EXACT existing Step-23 B-spline basis, mean function, FPC
## eigenfunctions, selected m, and hour grid.
## =============================================================================
cat("\n--- Section F: Reconstruct simulated curves; compute pointwise 95% PI -----\n")

predictive_mean_mat   <- matrix(NA_real_, nrow = n_future_days_needed, ncol = 24)
predictive_median_mat <- matrix(NA_real_, nrow = n_future_days_needed, ncol = 24)
predictive_sd_mat     <- matrix(NA_real_, nrow = n_future_days_needed, ncol = 24)
PI95_lower_mat          <- matrix(NA_real_, nrow = n_future_days_needed, ncol = 24)
PI95_upper_mat           <- matrix(NA_real_, nrow = n_future_days_needed, ncol = 24)

for (j in seq_len(n_future_days_needed)) {
  scores_b <- score_sims_by_day[[j]]                                    # B x p
  centered_coefs_b <- matrix(mean_coefs_vec, nrow = length(mean_coefs_vec), ncol = B) +
    harmonics_coefs %*% t(scores_b)                                       # K x B
  centered_vals_b <- t(Phi_argvals %*% centered_coefs_b)                    # B x 24
  X_sim_day_j <- centered_vals_b + matrix(level_sim_mat[, j], nrow = B, ncol = 24)  # B x 24
  
  predictive_mean_mat[j, ]   <- colMeans(X_sim_day_j)
  predictive_median_mat[j, ] <- apply(X_sim_day_j, 2, median)
  predictive_sd_mat[j, ]      <- apply(X_sim_day_j, 2, sd)
  PI95_lower_mat[j, ]           <- apply(X_sim_day_j, 2, quantile, probs = 0.025, names = FALSE, type = 7)
  PI95_upper_mat[j, ]            <- apply(X_sim_day_j, 2, quantile, probs = 0.975, names = FALSE, type = 7)
}
colnames(predictive_mean_mat) <- colnames(predictive_median_mat) <- colnames(predictive_sd_mat) <-
  colnames(PI95_lower_mat) <- colnames(PI95_upper_mat) <- paste0("h", 0:23)
rownames(predictive_mean_mat) <- rownames(predictive_median_mat) <- rownames(predictive_sd_mat) <-
  rownames(PI95_lower_mat) <- rownames(PI95_upper_mat) <- as.character(future_dates_needed)

pi_methodology_description <- paste(
  "Pointwise 95% predictive intervals obtained through Monte Carlo propagation",
  "(B =", B, "simulations, seed =", seed, ") of uncertainty from the daily-level",
  "state-space model AND the selected joint functional state-space score process",
  "(H =", H_type_fixed, ", Q =", Q_type_fixed, ", per Step 11's preferred structure).",
  "PI95_lower/upper are the empirical 2.5th/97.5th percentiles of the simulated",
  "GWL distribution at each future hour. The OFFICIAL point forecast remains",
  "Step 23's own deterministic gwl_forecast (NOT the Monte Carlo mean/median,",
  "reported alongside only as diagnostics). These are POINTWISE predictive",
  "intervals -- NOT simultaneous 95% functional bands."
)
cat(pi_methodology_description, "\n")


## =============================================================================
## SECTION G — BUILD UPGRADED FORECAST TABLES (24h / 168h), KEEPING STEP-23's
## DETERMINISTIC POINT FORECAST AS THE OFFICIAL gwl_forecast (Requirement C)
## =============================================================================
cat("\n--- Section G: Build upgraded forecast tables -------------------------------\n")

future_curves_matrix <- step23_results$future_curves_matrix   # Step-23's own deterministic point forecast, UNCHANGED

flatten_matrix_to_hourly <- function(mat, value_name) {
  df <- as.data.frame(mat) |> dplyr::mutate(forecast_date = as.Date(rownames(mat)))
  df |>
    tidyr::pivot_longer(cols = -forecast_date, names_to = "hour_label", values_to = value_name) |>
    dplyr::mutate(hour = as.integer(sub("^h", "", hour_label)),
                  datetime = as.POSIXct(paste0(forecast_date, " ", sprintf("%02d:00:00", hour)), tz = "UTC")) |>
    dplyr::select(datetime, dplyr::all_of(value_name))
}

fc_long        <- flatten_matrix_to_hourly(future_curves_matrix, "gwl_forecast")   # official, deterministic (Step 23)
pmean_long     <- flatten_matrix_to_hourly(predictive_mean_mat, "predictive_mean")
pmedian_long   <- flatten_matrix_to_hourly(predictive_median_mat, "predictive_median")
psd_long       <- flatten_matrix_to_hourly(predictive_sd_mat, "predictive_sd")
pi_lower_long  <- flatten_matrix_to_hourly(PI95_lower_mat, "PI95_lower")
pi_upper_long  <- flatten_matrix_to_hourly(PI95_upper_mat, "PI95_upper")

future_hourly_upgraded <- fc_long |>
  dplyr::left_join(pmean_long,  by = "datetime") |>
  dplyr::left_join(pmedian_long, by = "datetime") |>
  dplyr::left_join(psd_long,     by = "datetime") |>
  dplyr::left_join(pi_lower_long, by = "datetime") |>
  dplyr::left_join(pi_upper_long,  by = "datetime") |>
  dplyr::mutate(PI95_width = PI95_upper - PI95_lower) |>
  dplyr::filter(datetime > last_observed_datetime) |>
  dplyr::arrange(datetime)

forecast_24h  <- future_hourly_upgraded |> dplyr::filter(datetime %in% target_ts_24h)  |> dplyr::arrange(datetime)
forecast_168h <- future_hourly_upgraded |> dplyr::filter(datetime %in% target_ts_168h) |> dplyr::arrange(datetime)

stopifnot(nrow(forecast_24h) == 24)
stopifnot(nrow(forecast_168h) == 168)
cat("VERIFIED: nrow(forecast_24h) == 24  ->", nrow(forecast_24h) == 24, "\n")
cat("VERIFIED: nrow(forecast_168h) == 168 ->", nrow(forecast_168h) == 168, "\n")

## Requirement C: explicit numerical proof that Step-23.1 did not change the
## existing point forecasts -- compared against Step 23's OWN saved
## forecast_24h/forecast_168h tables (an independent check of the join/
## flatten pipeline above, not merely a tautology).
point_forecast_check_24h  <- isTRUE(all.equal(forecast_24h$gwl_forecast,  step23_results$forecast_24h$gwl_forecast,  tolerance = 1e-10))
point_forecast_check_168h <- isTRUE(all.equal(forecast_168h$gwl_forecast, step23_results$forecast_168h$gwl_forecast, tolerance = 1e-10))
point_forecast_unchanged <- point_forecast_check_24h && point_forecast_check_168h
cat("\nall.equal() check -- point forecast unchanged vs. Step 23 (24h):", point_forecast_check_24h, "\n")
cat("all.equal() check -- point forecast unchanged vs. Step 23 (168h):", point_forecast_check_168h, "\n")
if (!point_forecast_unchanged) {
  stop("Step 23.1's reconstructed point forecasts do NOT match Step 23's saved point forecasts -- STOPPING. ",
       "The deterministic forecast must never be altered by this step.")
}
cat("PASSED: Step-23 deterministic point forecast is confirmed UNCHANGED.\n")


## =============================================================================
## SECTION H — EXISTING STEP-23 OUTPUTS: EXPLICITLY PRESERVED, NOT MODIFIED
## =============================================================================
cat("\n--- Section H: Existing Step-23 outputs -------------------------------------\n")
cat("The following Step-23 files are NOT modified, overwritten, or renamed:\n",
    "  forecasts/23_final_FSSM_future_forecast.xlsx, forecasts/23_FSSM_future_24h.csv,\n",
    "  forecasts/23_FSSM_future_168h.csv, forecasts/23_daily_summary_forecast.csv,\n",
    "  forecasts/23_fssm_specification_table.csv, forecasts/23_FSSM_future_forecast.rds,\n",
    "  models/23_final_refitted_FSSM.rds,\n",
    "  figures/23_01_final_FSSM_24h_forecast.*, figures/23_02_final_FSSM_168h_forecast.*,\n",
    "  figures/23_03_final_FSSM_seven_daily_curves.*, figures/23_04_final_FSSM_dayhour_heatmap.*.\n",
    "Only the NEW, separately-prefixed '23_1_' outputs below use the upgraded PI.\n", sep = "")


## =============================================================================
## SECTION I — HISTORICAL + FUTURE DATASETS (Requirement J)
## =============================================================================
cat("\n--- Section I: Historical + future datasets ---------------------------------\n")

build_historical_future <- function(hist_hours, forecast_df) {
  hist_start <- last_observed_datetime - (hist_hours - 1) * 3600
  hist_df <- gwl_regularized |>
    dplyr::filter(datetime >= hist_start, datetime <= last_observed_datetime) |>
    dplyr::transmute(
      datetime, series_type = "Historical observed", observed_gwl = gwl,
      gwl_forecast = NA_real_, PI95_lower = NA_real_, PI95_upper = NA_real_,
      predictive_sd = NA_real_, PI95_width = NA_real_, forecast_origin = last_observed_datetime
    )
  fut_df <- forecast_df |>
    dplyr::transmute(
      datetime, series_type = "Future forecast", observed_gwl = NA_real_,
      gwl_forecast, PI95_lower, PI95_upper, predictive_sd, PI95_width,
      forecast_origin = last_observed_datetime
    )
  dplyr::bind_rows(hist_df, fut_df) |> dplyr::arrange(datetime)
}

historical_future_24h  <- build_historical_future(72,  forecast_24h)
historical_future_168h <- build_historical_future(336, forecast_168h)

cat("historical_future_24h  built:", nrow(historical_future_24h),  "rows (72h historical + 24h future).\n")
cat("historical_future_168h built:", nrow(historical_future_168h), "rows (336h/14d historical + 168h future).\n")


## =============================================================================
## SECTION J — VALIDATION AND LEAKAGE AUDIT (Requirement M)
## =============================================================================
cat("\n--- Section J: Validation and leakage audit -----------------------------------\n")

n_hist_24  <- sum(historical_future_24h$series_type  == "Historical observed")
n_fut_24   <- sum(historical_future_24h$series_type  == "Future forecast")
n_hist_168 <- sum(historical_future_168h$series_type == "Historical observed")
n_fut_168  <- sum(historical_future_168h$series_type == "Future forecast")

chk_n24_total  <- nrow(forecast_24h) == 24
chk_n168_total <- nrow(forecast_168h) == 168
chk_hist72     <- n_hist_24 == 72
chk_fut24      <- n_fut_24 == 24
chk_hist336    <- n_hist_168 == 336
chk_fut168     <- n_fut_168 == 168
chk_future_after_origin_24  <- all(historical_future_24h$datetime[historical_future_24h$series_type == "Future forecast"] > last_observed_datetime)
chk_future_after_origin_168 <- all(historical_future_168h$datetime[historical_future_168h$series_type == "Future forecast"] > last_observed_datetime)
chk_hist_before_origin_24   <- all(historical_future_24h$datetime[historical_future_24h$series_type == "Historical observed"] <= last_observed_datetime)
chk_hist_before_origin_168  <- all(historical_future_168h$datetime[historical_future_168h$series_type == "Historical observed"] <= last_observed_datetime)
chk_hist_only_actual_24  <- all(!is.na(historical_future_24h$observed_gwl[historical_future_24h$series_type == "Historical observed"])) &&
  all(is.na(historical_future_24h$gwl_forecast[historical_future_24h$series_type == "Historical observed"]))
chk_hist_only_actual_168 <- all(!is.na(historical_future_168h$observed_gwl[historical_future_168h$series_type == "Historical observed"])) &&
  all(is.na(historical_future_168h$gwl_forecast[historical_future_168h$series_type == "Historical observed"]))
chk_fut_no_actual_24  <- all(is.na(historical_future_24h$observed_gwl[historical_future_24h$series_type == "Future forecast"]))
chk_fut_no_actual_168 <- all(is.na(historical_future_168h$observed_gwl[historical_future_168h$series_type == "Future forecast"]))
chk_no_hist_pi_24  <- all(is.na(historical_future_24h$PI95_lower[historical_future_24h$series_type == "Historical observed"]))
chk_no_hist_pi_168 <- all(is.na(historical_future_168h$PI95_lower[historical_future_168h$series_type == "Historical observed"]))
