## =============================================================================
## SECTION A2 — SHARED HELPER FUNCTIONS
## (get_Z_slice / forecast_level_h / forecast_fssm_scores_h are reused,
## verbatim in logic, from Step 18's own script)
## =============================================================================
get_Z_slice <- function(Z, row_idx) {
  n_slices <- dim(Z)[3]
  idx <- if (n_slices == 1) 1 else row_idx
  matrix(Z[, , idx], nrow = dim(Z)[1], ncol = dim(Z)[2])
}

## Deterministic level point forecast (Step 18's forecast_level_h(), reused)
forecast_level_h <- function(kfs_full_level, origin_row, H) {
  model <- kfs_full_level$model
  Tt <- matrix(model$T[, , 1], nrow = dim(model$T)[1], ncol = dim(model$T)[2])
  state_h <- kfs_full_level$att[origin_row, ]
  n_full <- nrow(kfs_full_level$att)
  out <- rep(NA_real_, H)
  for (h in 1:H) {
    state_h <- as.numeric(Tt %*% state_h)
    target_row <- origin_row + h
    if (target_row > n_full) next
    Z_h <- get_Z_slice(model$Z, target_row)
    out[h] <- as.numeric(Z_h %*% state_h)
  }
  out
}

## Closed-form level point + full observation-equation predictive variance
## V_level(h) = Z_h P_h Z_h' + H_L, per Step 21.1's Section B.
forecast_level_point_var <- function(kfs_full_level, origin_row, H) {
  model <- kfs_full_level$model
  Tt <- matrix(model$T[, , 1], nrow = dim(model$T)[1])
  Qc <- matrix(model$Q[, , 1], nrow = dim(model$Q)[1])
  Hc <- matrix(model$H[, , 1], nrow = dim(model$H)[1])
  state <- kfs_full_level$att[origin_row, ]
  P <- matrix(kfs_full_level$Ptt[, , origin_row], nrow = length(state))
  n_full <- nrow(kfs_full_level$att)
  point <- rep(NA_real_, H); varh <- rep(NA_real_, H)
  for (h in 1:H) {
    state <- as.numeric(Tt %*% state)
    P <- Tt %*% P %*% t(Tt) + Qc
    target_row <- origin_row + h
    if (target_row > n_full) next
    Z_h <- get_Z_slice(model$Z, target_row)
    point[h] <- as.numeric(Z_h %*% state)
    varh[h]  <- as.numeric(Z_h %*% P %*% t(Z_h)) + Hc[1, 1]
  }
  list(point = point, var = varh)
}

## Deterministic FSSM score forecast (Hadamard recursion, T = I; Step 18's
## forecast_fssm_scores_h(), reused unchanged). Used as the OFFICIAL point
## forecast for Models 2 and 3 -- never replaced by the Monte Carlo mean.
forecast_fssm_scores_h <- function(kfs_full_scores, origin_row, H, p) {
  alpha_t <- kfs_full_scores$att[origin_row, ]
  y_t     <- kfs_full_scores$model$y[origin_row, ]
  out <- matrix(NA_real_, nrow = H, ncol = p)
  y_prev <- y_t
  for (h in 1:H) {
    y_h <- y_prev * alpha_t
    out[h, ] <- y_h
    y_prev <- y_h
  }
  out
}

## Generic zero-mean multivariate-normal noise sampler: Cholesky first, with
## an eigen-decomposition fallback for near-singular / PSD-boundary matrices
## (e.g. a zero-Q variant, or a rank-deficient filtered covariance). This is
## the SAME design as Step 23.1's build_mvn_draw_fn(), generalized here for
## both the level model and any FSSM H/Q (diagonal or full).
mvn_noise_sampler <- function(Sigma) {
  Sigma <- as.matrix(Sigma)
  d <- nrow(Sigma)
  if (d == 1) {
    sd1 <- sqrt(pmax(as.numeric(Sigma), 0))
    return(list(draw = function(n) matrix(rnorm(n, mean = 0, sd = sd1), ncol = 1), method = "scalar"))
  }
  A <- tryCatch(t(chol(Sigma)), error = function(e) NULL)
  method <- "cholesky"
  if (is.null(A)) {
    ee <- eigen(Sigma, symmetric = TRUE)
    vals <- pmax(ee$values, 0)
    A <- ee$vectors %*% diag(sqrt(vals), nrow = d)
    method <- "eigen_fallback"
  }
  list(draw = function(n) { Zm <- matrix(rnorm(n * d), nrow = n, ncol = d); Zm %*% t(A) },
       method = method)
}

## Monte Carlo daily-level simulation, anchored at a given historical origin
## row (final FILTERED state/covariance at that row -- causal, no leakage).
simulate_level_mc <- function(kfs_full_level, origin_row, H, B) {
  model <- kfs_full_level$model
  Tt <- matrix(model$T[, , 1], nrow = dim(model$T)[1])
  Qc <- matrix(model$Q[, , 1], nrow = dim(model$Q)[1])
  Hc <- matrix(model$H[, , 1], nrow = dim(model$H)[1])
  state_hat <- kfs_full_level$att[origin_row, ]
  n_states  <- length(state_hat)
  P_hat <- matrix(kfs_full_level$Ptt[, , origin_row], nrow = n_states)
  n_full <- nrow(kfs_full_level$att)
  
  init_s <- mvn_noise_sampler(P_hat)
  proc_s <- mvn_noise_sampler(Qc)
  state_mat <- matrix(rep(state_hat, each = B), nrow = B) + init_s$draw(B)
  
  level_sim <- matrix(NA_real_, B, H)
  for (h in 1:H) {
    state_mat <- state_mat %*% t(Tt) + proc_s$draw(B)
    target_row <- origin_row + h
    if (target_row > n_full) { level_sim[, h] <- NA_real_; next }
    Z_h <- get_Z_slice(model$Z, target_row)
    obs_noise <- rnorm(B, mean = 0, sd = sqrt(pmax(Hc[1, 1], 0)))
    level_sim[, h] <- as.numeric(state_mat %*% t(Z_h)) + obs_noise
  }
  list(level_sim = level_sim, init_method = init_s$method, proc_method = proc_s$method)
}

## Monte Carlo FSSM score simulation, anchored at a historical origin row.
## Qmat/Hmat may be diagonal (Model 2) or general/full (Model 3) -- the
## sampler is fully generic; cross-component covariance is never dropped.
simulate_fssm_scores_mc <- function(kfs_full_scores, origin_row, H, p, Qmat, Hmat, B) {
  alpha_hat <- kfs_full_scores$att[origin_row, ]
  alpha_P   <- matrix(kfs_full_scores$Ptt[, , origin_row], nrow = p)
  y_prev0   <- as.numeric(kfs_full_scores$model$y[origin_row, ])   # actual, known score at the origin day
  
  init_s <- mvn_noise_sampler(alpha_P)
  q_s    <- mvn_noise_sampler(Qmat)
  h_s    <- mvn_noise_sampler(Hmat)
  
  alpha_mat <- matrix(rep(alpha_hat, each = B), nrow = B) + init_s$draw(B)
  y_mat     <- matrix(rep(y_prev0, each = B), nrow = B)
  
  scores_by_h <- vector("list", H)
  for (h in 1:H) {
    eta <- q_s$draw(B)
    alpha_mat <- alpha_mat + eta
    e <- h_s$draw(B)
    y_new <- y_mat * alpha_mat + e     # Hadamard: diag(y_prev) %*% alpha == y_prev * alpha
    scores_by_h[[h]] <- y_new
    y_mat <- y_new
  }
  list(scores_by_h = scores_by_h, q_method = q_s$method, h_method = h_s$method)
}

## Reconstruct simulated curves for every horizon and return empirical 95% PI
compute_mc_pi <- function(level_sim, scores_by_h, H) {
  B <- nrow(level_sim)
  PI_lower <- matrix(NA_real_, H, 24); PI_upper <- matrix(NA_real_, H, 24)
  for (h in 1:H) {
    scores_b <- scores_by_h[[h]]
    if (anyNA(level_sim[, h]) || anyNA(scores_b)) next
    coefs_b <- reconstruct_coefs(scores_b)                          # K x B
    curve_b <- t(Phi_argvals %*% coefs_b) + matrix(level_sim[, h], nrow = B, ncol = 24)
    PI_lower[h, ] <- apply(curve_b, 2, quantile, probs = 0.025, names = FALSE, type = 7)
    PI_upper[h, ] <- apply(curve_b, 2, quantile, probs = 0.975, names = FALSE, type = 7)
  }
  list(lower = PI_lower, upper = PI_upper)
}


## =============================================================================
## SECTION B — ROLLING-ORIGIN LOOP: GENERATE POINT FORECASTS + PI FOR ALL
## THREE MODELS, AT EVERY ORIGIN, FOR h = 1..7
## =============================================================================
cat("\n================= ROLLING-ORIGIN FORECAST + PI GENERATION =================\n")
cat("Origins:", n_origins, "| Horizons: 1..", H_max, "| Models: 3\n", sep = "")
cat("No re-estimation occurs at any origin -- all parameters are frozen from\n",
    "Steps 10/11/12/13/17's original training-window fits; only the forecast\n",
    "ORIGIN advances, exactly as in Step 18.\n", sep = "")

model1_rows <- vector("list", n_origins)
model2_rows <- vector("list", n_origins)
model3_rows <- vector("list", n_origins)
invalid_flags <- list()

pb_every <- max(1, round(n_origins / 20))

for (i in seq_len(n_origins)) {
  if (i %% pb_every == 0) cat("  origin", i, "of", n_origins, "...\n")
  
  origin_date   <- origin_dates[i]
  target_dates  <- origin_date + 1:H_max
  origin_row_m  <- origin_rows_model[i]
  origin_row_lv <- level_target_row_idx[i]
  origin_row_sg <- match(origin_date, acf_segment_scores_df$date)
  
  ## ---- Ground truth ----
  raw_idx <- match(as.character(target_dates), rownames(functional_matrix_raw))
  actual_curves <- functional_matrix_raw[raw_idx, , drop = FALSE]   # H_max x 24 (NA row if unavailable)
  
  ## =========================== MODEL 1: FPCA + independent scores ===========
  m1_ok <- TRUE
  lv <- tryCatch(forecast_level_point_var(level_kfs_full, origin_row_lv, H_max),
                 error = function(e) { m1_ok <<- FALSE; NULL })
  
  score_mean <- matrix(NA_real_, H_max, p); score_se <- matrix(NA_real_, H_max, p)
  if (m1_ok) {
    for (k in seq_len(p)) {
      pc <- score_cols[k]
      r  <- component_results_17[[pc]]
      series_through_origin <- ts(acf_segment_scores_df[[pc]][1:origin_row_sg], frequency = 1)
      fc_k <- tryCatch({
        if (r$chosen_method == "ARIMA") {
          refit_k <- forecast::Arima(series_through_origin, model = r$fit_final_train)
        } else {
          refit_k <- forecast::ets(series_through_origin, model = r$fit_final_train, use.initial.values = TRUE)
        }
        forecast::forecast(refit_k, h = H_max, level = 95)
      }, error = function(e) NULL)
      if (is.null(fc_k)) { m1_ok <- FALSE; break }
      score_mean[, k] <- as.numeric(fc_k$mean)
      score_se[, k]   <- (as.numeric(fc_k$upper[, 1]) - as.numeric(fc_k$lower[, 1])) / (2 * z975)
    }
  }
  
  if (m1_ok) {
    coefs_m1 <- reconstruct_coefs(score_mean)                     # K x H_max
    curve_point_m1 <- t(Phi_argvals %*% coefs_m1) + matrix(lv$point, H_max, 24)
    score_var <- score_se^2
    V_shape <- (eigen_at_hour^2) %*% t(score_var)                 # 24 x H_max
    V_shape <- t(V_shape)                                          # H_max x 24
    V_total <- matrix(lv$var, H_max, 24) + V_shape
    SE_total <- sqrt(pmax(V_total, 0))
    PI_lower_m1 <- curve_point_m1 - z975 * SE_total
    PI_upper_m1 <- curve_point_m1 + z975 * SE_total
  } else {
    curve_point_m1 <- matrix(NA_real_, H_max, 24)
    PI_lower_m1 <- PI_upper_m1 <- matrix(NA_real_, H_max, 24)
    invalid_flags[[length(invalid_flags) + 1]] <- data.frame(model = "FPCA + Independent Scores", origin = origin_date, reason = "score/level forecast failed")
  }
  
  model1_rows[[i]] <- list(origin = origin_date, target = target_dates,
                           point = curve_point_m1, lower = PI_lower_m1, upper = PI_upper_m1,
                           actual = actual_curves)
  
  ## =========================== MODEL 2: Basic FSSM (diag H, diag Q) =========
  m2_ok <- TRUE
  level_point_m2 <- tryCatch(forecast_level_h(level_kfs_full, origin_row_lv, H_max),
                             error = function(e) { m2_ok <<- FALSE; rep(NA_real_, H_max) })
  score_point_m2 <- tryCatch(forecast_fssm_scores_h(basic_kfs, origin_row_m, H_max, p),
                             error = function(e) { m2_ok <<- FALSE; matrix(NA_real_, H_max, p) })
  
  if (m2_ok) {
    coefs_m2 <- reconstruct_coefs(score_point_m2)
    curve_point_m2 <- t(Phi_argvals %*% coefs_m2) + matrix(level_point_m2, H_max, 24)
    
    lvl_mc2 <- tryCatch(simulate_level_mc(level_kfs_full, origin_row_lv, H_max, B_validation),
                        error = function(e) { m2_ok <<- FALSE; NULL })
    sc_mc2  <- tryCatch(simulate_fssm_scores_mc(basic_kfs, origin_row_m, H_max, p, Q_basic, H_basic, B_validation),
                        error = function(e) { m2_ok <<- FALSE; NULL })
  }
  if (m2_ok) {
    pi2 <- compute_mc_pi(lvl_mc2$level_sim, sc_mc2$scores_by_h, H_max)
    PI_lower_m2 <- pi2$lower; PI_upper_m2 <- pi2$upper
  } else {
    curve_point_m2 <- matrix(NA_real_, H_max, 24)
    PI_lower_m2 <- PI_upper_m2 <- matrix(NA_real_, H_max, 24)
    invalid_flags[[length(invalid_flags) + 1]] <- data.frame(model = "Basic FSSM", origin = origin_date, reason = "level/FSSM forecast or MC failed")
  }
  
  model2_rows[[i]] <- list(origin = origin_date, target = target_dates,
                           point = curve_point_m2, lower = PI_lower_m2, upper = PI_upper_m2,
                           actual = actual_curves)
  
  ## =========================== MODEL 3: Selected/Dynamic FSSM ===============
  m3_ok <- TRUE
  level_point_m3 <- tryCatch(forecast_level_h(level_kfs_full, origin_row_lv, H_max),
                             error = function(e) { m3_ok <<- FALSE; rep(NA_real_, H_max) })
  score_point_m3 <- tryCatch(forecast_fssm_scores_h(final_kfs, origin_row_m, H_max, p),
                             error = function(e) { m3_ok <<- FALSE; matrix(NA_real_, H_max, p) })
  
  if (m3_ok) {
    coefs_m3 <- reconstruct_coefs(score_point_m3)
    curve_point_m3 <- t(Phi_argvals %*% coefs_m3) + matrix(level_point_m3, H_max, 24)
    
    lvl_mc3 <- tryCatch(simulate_level_mc(level_kfs_full, origin_row_lv, H_max, B_validation),
                        error = function(e) { m3_ok <<- FALSE; NULL })
    sc_mc3  <- tryCatch(simulate_fssm_scores_mc(final_kfs, origin_row_m, H_max, p, Q_final, H_final, B_validation),
                        error = function(e) { m3_ok <<- FALSE; NULL })
  }
  if (m3_ok) {
    pi3 <- compute_mc_pi(lvl_mc3$level_sim, sc_mc3$scores_by_h, H_max)
    PI_lower_m3 <- pi3$lower; PI_upper_m3 <- pi3$upper
  } else {
    curve_point_m3 <- matrix(NA_real_, H_max, 24)
    PI_lower_m3 <- PI_upper_m3 <- matrix(NA_real_, H_max, 24)
    invalid_flags[[length(invalid_flags) + 1]] <- data.frame(model = "Dynamic FSSM", origin = origin_date, reason = "level/FSSM forecast or MC failed")
  }
  
  model3_rows[[i]] <- list(origin = origin_date, target = target_dates,
                           point = curve_point_m3, lower = PI_lower_m3, upper = PI_upper_m3,
                           actual = actual_curves)
}

cat("Rolling-origin forecast + PI generation complete for all", n_origins, "origins.\n")

