## =============================================================================
## SECTION C — ASSEMBLE THE COMMON SCORING DATASET
## =============================================================================
cat("\n--- Assembling the common scoring dataset ---------------------------------\n")

hour_seq <- 0:23

build_scoring_long <- function(rows_list, model_label) {
  purrr::map_dfr(rows_list, function(r) {
    if (anyNA(r$target)) return(NULL)
    ## per-horizon ISFE (sum of squared errors over the 24 hours), computed
    ## once and broadcast to every hour-row of that origin/horizon
    resid <- r$actual - r$point
    isfe_h <- rowSums(resid^2, na.rm = FALSE)
    
    purrr::map_dfr(1:H_max, function(h) {
      data.frame(
        model         = model_label,
        origin        = r$origin,
        forecast_date = r$target[h],
        horizon_day   = h,
        hour          = hour_seq,
        datetime      = as.POSIXct(paste0(r$target[h], " ", sprintf("%02d:00:00", hour_seq)), tz = "UTC"),
        observed_gwl  = as.numeric(r$actual[h, ]),
        point_forecast = as.numeric(r$point[h, ]),
        PI95_lower     = as.numeric(r$lower[h, ]),
        PI95_upper     = as.numeric(r$upper[h, ]),
        ISFE_curve     = isfe_h[h]
      )
    })
  })
}

scoring_m1 <- build_scoring_long(model1_rows, "FPCA + Independent Scores")
scoring_m2 <- build_scoring_long(model2_rows, "Basic FSSM")
scoring_m3 <- build_scoring_long(model3_rows, "Dynamic FSSM")

common_scoring_dataset <- dplyr::bind_rows(scoring_m1, scoring_m2, scoring_m3) |>
  dplyr::mutate(
    covered = dplyr::if_else(!is.na(PI95_lower) & !is.na(PI95_upper) & !is.na(observed_gwl),
                             as.integer(observed_gwl >= PI95_lower & observed_gwl <= PI95_upper), NA_integer_),
    interval_score = dplyr::if_else(
      !is.na(PI95_lower) & !is.na(PI95_upper) & !is.na(observed_gwl),
      (PI95_upper - PI95_lower) +
        mis_mult * pmax(PI95_lower - observed_gwl, 0) +
        mis_mult * pmax(observed_gwl - PI95_upper, 0),
      NA_real_
    )
  ) |>
  dplyr::select(model, origin, forecast_date, horizon_day, hour, datetime,
                observed_gwl, point_forecast, PI95_lower, PI95_upper, covered,
                interval_score, ISFE_curve)

cat("Common scoring dataset built:", nrow(common_scoring_dataset), "rows",
    "(3 models x", n_origins, "origins x", H_max, "horizons x 24 hours, minus invalid origins).\n")

## Enforce a genuinely common sample across all three models: keep only
## (origin, horizon_day) combinations valid for ALL THREE models.
valid_combo <- common_scoring_dataset |>
  dplyr::group_by(origin, horizon_day) |>
  dplyr::summarise(n_models_valid = dplyr::n_distinct(model[!is.na(point_forecast)]), .groups = "drop") |>
  dplyr::filter(n_models_valid == 3) |>
  dplyr::select(origin, horizon_day)

n_before <- nrow(common_scoring_dataset)
common_scoring_dataset <- common_scoring_dataset |>
  dplyr::inner_join(valid_combo, by = c("origin", "horizon_day"))
n_after <- nrow(common_scoring_dataset)
cat("Restricted to (origin, horizon) combinations valid for all three models:",
    n_before, "->", n_after, "rows (", n_before - n_after, "rows dropped due to a model-specific failure).\n")


## =============================================================================
## SECTION D — VALIDATION CHECKS
## =============================================================================
cat("\n--- Validation checks -------------------------------------------------------\n")

chk_no_leakage_structural <- TRUE   # by construction: att/Ptt at origin_row use only data <= origin (Kalman filter is causal); ARIMA/ETS refit via model= uses only series_through_origin
chk_future_after_origin   <- all(common_scoring_dataset$datetime > as.POSIXct(paste0(common_scoring_dataset$origin, " 23:00:00"), tz = "UTC") - 3600 * 24 * (common_scoring_dataset$horizon_day - 1))
chk_24_per_day <- common_scoring_dataset |>
  dplyr::group_by(model, origin, horizon_day) |>
  dplyr::summarise(n_hours = dplyr::n(), .groups = "drop") |>
  dplyr::summarise(all_24 = all(n_hours == 24)) |> dplyr::pull(all_24)
chk_horizons_1to7 <- all(common_scoring_dataset$horizon_day %in% 1:7)
chk_pi_ordering   <- all(common_scoring_dataset$PI95_lower <= common_scoring_dataset$PI95_upper, na.rm = TRUE)
chk_no_na_point   <- all(is.finite(common_scoring_dataset$point_forecast))
chk_no_na_pi      <- all(is.finite(common_scoring_dataset$PI95_lower)) && all(is.finite(common_scoring_dataset$PI95_upper))
chk_same_origins  <- common_scoring_dataset |>
  dplyr::group_by(origin, horizon_day) |>
  dplyr::summarise(n_models = dplyr::n_distinct(model), .groups = "drop") |>
  dplyr::summarise(all_three = all(n_models == 3)) |> dplyr::pull(all_three)
chk_basic_diag    <- isTRUE(all(diag(diag(Q_basic)) == Q_basic)) && isTRUE(all(diag(diag(H_basic)) == H_basic))
chk_dynamic_step11 <- identical(H_type_fixed, step11_results$preferred_structure$H_type) &&
  identical(Q_type_fixed, step11_results$preferred_structure$Q_type)
chk_mc_no_future  <- TRUE   # by construction: MC initial states/scores drawn from filtered (att/Ptt) at origin_row only

validation_checks <- data.frame(
  check = c("1. No future observation used during fitting (structural, by construction)",
            "2. All forecasts occur strictly after the corresponding origin",
            "3. Every scored forecast day contains exactly 24 hours",
            "4. Horizons are Day 1-7 only",
            "5. PI95_lower <= PI95_upper",
            "6. No NA/non-finite point forecasts in scored rows",
            "7. No NA/non-finite PI bounds in scored rows",
            "8. All three models compared on the same origins and horizons",
            "9. Basic FSSM uses diagonal H and diagonal Q",
            "10. Dynamic FSSM uses exactly the Step-11 preferred H/Q structure",
            "11. No future truth enters Monte Carlo simulation (structural, by construction)"),
  passed = c(chk_no_leakage_structural, chk_future_after_origin, chk_24_per_day, chk_horizons_1to7,
             chk_pi_ordering, chk_no_na_point, chk_no_na_pi, chk_same_origins,
             chk_basic_diag, chk_dynamic_step11, chk_mc_no_future)
)
print(validation_checks)
if (!all(validation_checks$passed)) {
  warning("One or more Step 24 validation checks FAILED -- inspect validation_checks before trusting the results below.")
} else {
  cat("\nAll Step 24 validation checks PASSED.\n")
}


## =============================================================================
## SECTION E — METRICS: RMSE, MISFE, PICP, MIS -- BY MODEL AND HORIZON, AND
## OVERALL BY MODEL
## =============================================================================
cat("\n--- Computing RMSE / MISFE / PICP / MIS -------------------------------------\n")

## RMSE and PICP are computed on the hourly-level scoring dataset.
rmse_picp_by_horizon <- common_scoring_dataset |>
  dplyr::group_by(model, horizon_day) |>
  dplyr::summarise(
    RMSE = sqrt(mean((observed_gwl - point_forecast)^2, na.rm = TRUE)),
    PICP_percent = 100 * mean(covered, na.rm = TRUE),
    MIS = mean(interval_score, na.rm = TRUE),
    .groups = "drop"
  )

## MISFE (functional, per origin/horizon curve) computed from ISFE_curve,
## which is identical across the 24 hour-rows of a given (model, origin,
## horizon) -- take one value per origin/horizon before averaging.
misfe_by_horizon <- common_scoring_dataset |>
  dplyr::distinct(model, origin, horizon_day, ISFE_curve) |>
  dplyr::group_by(model, horizon_day) |>
  dplyr::summarise(MISFE = mean(ISFE_curve, na.rm = TRUE), .groups = "drop")

validation_by_horizon <- rmse_picp_by_horizon |>
  dplyr::left_join(misfe_by_horizon, by = c("model", "horizon_day")) |>
  dplyr::select(model, horizon_day, RMSE, MISFE, PICP_percent, MIS) |>
  dplyr::arrange(model, horizon_day)

## Overall (pooled across all horizons) by model
rmse_picp_overall <- common_scoring_dataset |>
  dplyr::group_by(model) |>
  dplyr::summarise(
    RMSE = sqrt(mean((observed_gwl - point_forecast)^2, na.rm = TRUE)),
    PICP_percent = 100 * mean(covered, na.rm = TRUE),
    MIS = mean(interval_score, na.rm = TRUE),
    .groups = "drop"
  )
misfe_overall <- common_scoring_dataset |>
  dplyr::distinct(model, origin, horizon_day, ISFE_curve) |>
  dplyr::group_by(model) |>
  dplyr::summarise(MISFE = mean(ISFE_curve, na.rm = TRUE), .groups = "drop")

validation_overall_rows <- rmse_picp_overall |>
  dplyr::left_join(misfe_overall, by = "model") |>
  dplyr::mutate(horizon_day = NA_integer_) |>
  dplyr::select(model, horizon_day, RMSE, MISFE, PICP_percent, MIS)

cat("RMSE/MISFE/PICP/MIS computed by model x horizon and overall by model.\n")


## =============================================================================
## SECTION F — OUTPUT TABLES
## =============================================================================
cat("\n--- Building publication-ready output tables ---------------------------------\n")

model_labels <- c("FPCA + Independent Scores", "Basic FSSM", "Dynamic FSSM")

horizon_label <- function(h) if (is.na(h)) "Overall" else paste0("Day ", h)

main_summary_table <- dplyr::bind_rows(validation_by_horizon, validation_overall_rows) |>
  dplyr::mutate(
    model = factor(model, levels = model_labels),
    Horizon = sapply(horizon_day, horizon_label),
    Horizon = factor(Horizon, levels = c(paste0("Day ", 1:H_max), "Overall"))
  ) |>
  dplyr::arrange(model, Horizon) |>
  dplyr::transmute(
    Model = as.character(model), Horizon = as.character(Horizon),
    RMSE = round(RMSE, 5), MISFE = round(MISFE, 5),
    PICP_percent = round(PICP_percent, 2), MIS = round(MIS, 5)
  )

cat("\n=== MAIN PUBLICATION SUMMARY TABLE (Model x Horizon, incl. Overall) ===\n")
print(main_summary_table, n = 100)

overall_ranking_table <- rmse_picp_overall |>
  dplyr::left_join(misfe_overall, by = "model") |>
  dplyr::mutate(
    Absolute_Coverage_Deviation = round(abs(PICP_percent / 100 - 0.95), 4),
    model = factor(model, levels = model_labels)
  ) |>
  dplyr::arrange(model) |>
  dplyr::transmute(
    Model = as.character(model),
    Overall_RMSE = round(RMSE, 5), Overall_MISFE = round(MISFE, 5),
    Overall_PICP = round(PICP_percent, 2), Absolute_Coverage_Deviation,
    Overall_MIS = round(MIS, 5)
  )

cat("\n=== OVERALL RANKING TABLE ===\n")
print(overall_ranking_table)


## =============================================================================
## SECTION G — FIGURES (four primary + one optional combined)
## =============================================================================
cat("\n--- Building publication-quality figures --------------------------------------\n")

model_colours <- c("FPCA + Independent Scores" = "#2166AC",   # blue family
                   "Basic FSSM"                = "#1B7837",   # seagreen/green family
                   "Dynamic FSSM"              = "#762A83")   # purple/plum family

pub_theme <- ggplot2::theme_minimal(base_size = 14) +
  ggplot2::theme(
    plot.title = ggplot2::element_text(face = "bold", size = 15),
    plot.subtitle = ggplot2::element_text(size = 11, colour = "grey30"),
    panel.grid.minor = ggplot2::element_blank(),
    legend.position = "bottom",
    axis.title = ggplot2::element_text(size = 12)
  )

plot_df <- validation_by_horizon |>
  dplyr::mutate(model = factor(model, levels = model_labels),
                Horizon = factor(paste0("Day ", horizon_day), levels = paste0("Day ", 1:H_max)))

## FIGURE 1 — RMSE by horizon
fig1_rmse <- ggplot2::ggplot(plot_df, ggplot2::aes(x = Horizon, y = RMSE, colour = model, group = model)) +
  ggplot2::geom_line(linewidth = 0.9) + ggplot2::geom_point(size = 2.6) +
  ggplot2::scale_colour_manual(values = model_colours, name = NULL) +
  ggplot2::labs(title = "Hourly Point-Forecast Accuracy by Forecast Horizon",
                x = "Forecast horizon", y = "RMSE") +
  pub_theme

## FIGURE 2 — MISFE by horizon
fig2_misfe <- ggplot2::ggplot(plot_df, ggplot2::aes(x = Horizon, y = MISFE, colour = model, group = model)) +
  ggplot2::geom_line(linewidth = 0.9) + ggplot2::geom_point(size = 2.6) +
  ggplot2::scale_colour_manual(values = model_colours, name = NULL) +
  ggplot2::labs(title = "Functional Forecast Error by Forecast Horizon",
                subtitle = "Lower MISFE indicates better reconstruction of the 24-hour GWL curve.",
                x = "Forecast horizon", y = "MISFE") +
  pub_theme

## FIGURE 3 — PICP by horizon, with 95% reference line
fig3_picp <- ggplot2::ggplot(plot_df, ggplot2::aes(x = Horizon, y = PICP_percent, colour = model, group = model)) +
  ggplot2::geom_hline(yintercept = 95, linetype = "dashed", colour = "grey40") +
  ggplot2::geom_line(linewidth = 0.9) + ggplot2::geom_point(size = 2.6) +
  ggplot2::scale_colour_manual(values = model_colours, name = NULL) +
  ggplot2::labs(title = "Calibration of 95% Pointwise Predictive Intervals",
                subtitle = "Values closer to the nominal 95% level indicate better calibration.",
                x = "Forecast horizon", y = "Empirical PICP (%)") +
  pub_theme

## FIGURE 4 — MIS by horizon
fig4_mis <- ggplot2::ggplot(plot_df, ggplot2::aes(x = Horizon, y = MIS, colour = model, group = model)) +
  ggplot2::geom_line(linewidth = 0.9) + ggplot2::geom_point(size = 2.6) +
  ggplot2::scale_colour_manual(values = model_colours, name = NULL) +
  ggplot2::labs(title = "Predictive-Interval Performance by Forecast Horizon",
                subtitle = "Lower MIS indicates a better balance between interval sharpness and coverage.",
                x = "Forecast horizon", y = "Mean Interval Score (MIS)") +
  pub_theme

cat("Four primary figures generated.\n")


## -----------------------------------------------------------------------------
## EXPORT FIGURES 1-4 (PNG, PDF, TIFF@300dpi, TIFF@600dpi)
## -----------------------------------------------------------------------------
save_fig_24 <- function(plot_obj, name, width = 9, height = 6) {
  ggplot2::ggsave(file.path("figures", paste0(name, ".png")), plot_obj, width = width, height = height, dpi = 300)
  ggplot2::ggsave(file.path("figures", paste0(name, ".pdf")), plot_obj, width = width, height = height)
  ggplot2::ggsave(file.path("figures", paste0(name, "_300dpi.tiff")), plot_obj, width = width, height = height, dpi = 300, compression = "lzw")
  ggplot2::ggsave(file.path("figures", paste0(name, "_600dpi.tiff")), plot_obj, width = width, height = height, dpi = 600, compression = "lzw")
}
save_fig_24(fig1_rmse,  "24_01_RMSE_by_horizon")
save_fig_24(fig2_misfe, "24_02_MISFE_by_horizon")
save_fig_24(fig3_picp,  "24_03_PICP_by_horizon")
save_fig_24(fig4_mis,   "24_04_MIS_by_horizon")
cat("Figures 1-4 exported to figures/ (PNG, PDF, TIFF 300/600dpi), prefixed '24_'.\n")


## -----------------------------------------------------------------------------
## SECTION H — OPTIONAL COMBINED 2x2 PANEL
## -----------------------------------------------------------------------------
if (have_patchwork) {
  fig1_c <- fig1_rmse  + ggplot2::labs(title = "A. RMSE") + ggplot2::theme(legend.position = "none")
  fig2_c <- fig2_misfe + ggplot2::labs(title = "B. MISFE", subtitle = NULL) + ggplot2::theme(legend.position = "none")
  fig3_c <- fig3_picp  + ggplot2::labs(title = "C. PICP", subtitle = NULL) + ggplot2::theme(legend.position = "none")
  fig4_c <- fig4_mis   + ggplot2::labs(title = "D. MIS", subtitle = NULL) + ggplot2::theme(legend.position = "bottom")
  
  combined_panel <- (fig1_c | fig2_c) / (fig3_c | fig4_c) +
    patchwork::plot_annotation(
      title = "Step 24 — Rolling-Origin Validation of Point and Interval Forecasts",
      subtitle = "Hourly GWL forecasts, well GT2648C03 — three functional forecasting approaches compared"
    )
  save_fig_24(combined_panel, "24_05_combined_validation_panel", width = 12, height = 9)
  cat("Combined 2x2 validation panel exported (figures/24_05_combined_validation_panel.*).\n")
} else {
  combined_panel <- NULL
  cat("Combined 2x2 panel SKIPPED (patchwork not installed).\n")
}


## =============================================================================
## SECTION I — EXPORTS (tables, forecasts, RDS bundle)
## =============================================================================
cat("\n--- Exporting tables and forecasts --------------------------------------------\n")

write.csv(main_summary_table,   file.path("tables", "24_validation_by_horizon.csv"), row.names = FALSE)
write.csv(overall_ranking_table, file.path("tables", "24_overall_model_validation.csv"), row.names = FALSE)
write.csv(validation_checks,      file.path("tables", "24_validation_checks.csv"), row.names = FALSE)
write.csv(common_scoring_dataset,   file.path("forecasts", "24_rolling_origin_validation_predictions.csv"), row.names = FALSE)

writexl::write_xlsx(
  list(
