    Overall_Validation     = overall_ranking_table,
    Validation_Checks        = validation_checks
  ),
  path = file.path("forecasts", "24_forecast_validation.xlsx")
)

step24_results <- list(
  B_validation = B_validation, seed = seed,
  common_scoring_dataset = common_scoring_dataset,
  main_summary_table = main_summary_table,
  overall_ranking_table = overall_ranking_table,
