make_enhanced_plot <- function(tbl, model_name, last_obs_dt, hist_hours, title_txt) {
  fut <- tbl
  hist_df <- NULL
  if (!is.null(gwl_hourly_hist)) {
    hist_start <- last_obs_dt - (hist_hours - 1) * 3600
    hist_df <- gwl_hourly_hist |> dplyr::filter(datetime >= hist_start, datetime <= last_obs_dt, !is.na(gwl))
  }
  col <- model_colour[[model_name]]
  ggplot2::ggplot() +
    ggplot2::geom_ribbon(data = fut, ggplot2::aes(x = datetime, ymin = enhanced_PI95_lower, ymax = enhanced_PI95_upper),
                         fill = col, alpha = 0.30, inherit.aes = FALSE) +
    { if (!is.null(hist_df)) ggplot2::geom_line(data = hist_df, ggplot2::aes(x = datetime, y = gwl), colour = "grey30", linewidth = 0.4) } +
    ggplot2::geom_line(data = fut, ggplot2::aes(x = datetime, y = original_PI95_lower), colour = col, linetype = "dashed", linewidth = 0.35, alpha = 0.8) +
    ggplot2::geom_line(data = fut, ggplot2::aes(x = datetime, y = original_PI95_upper), colour = col, linetype = "dashed", linewidth = 0.35, alpha = 0.8) +
    ggplot2::geom_line(data = fut, ggplot2::aes(x = datetime, y = gwl_forecast), colour = col, linewidth = 0.8) +
    ggplot2::geom_vline(xintercept = as.numeric(last_obs_dt), linetype = "dotted", colour = "grey40") +
    ggplot2::labs(title = title_txt,
                  subtitle = "Shaded band = enhanced 95% PI; dashed lines = original 95% PI (reference); solid = official point forecast",
                  x = "Datetime", y = "GWL") +
    pub_theme
}

