basic_FSSM_results           <- readRDS(p26("10_basic_FSSM.rds"))
step11_results                <- readRDS(p26("11_HQ_covariance_comparison.rds"))
step12_results                  <- readRDS(p26("12_level_state_space.rds"))
step13_results                    <- readRDS(p26("13_seasonal_FSSM.rds"))
FPCA_score_forecast_results          <- readRDS(p26("17_FPCA_score_forecast.rds"))

step24_results <- readRDS(pF("24_forecast_validation.rds"))
step25_results <- readRDS(pF("25_enhanced_prediction_intervals.rds"))

cat("All required Step 5/6/9/10/11/12/13/17/24/25 outputs loaded successfully.\n")

functional_matrix_raw <- daily_curves_results$functional_matrix
retained_dates          <- daily_curves_results$retained_dates
daily_level_df             <- centered_curves_results$daily_level_df

p          <- selected_fpca_results$recommended_m
score_cols <- paste0("PC", 1:p)
meanfd              <- selected_fpca_results$meanfd
harmonics_selected  <- selected_fpca_results$harmonics_selected
basis_obj           <- selected_fpca_results$basis_obj
argvals             <- selected_fpca_results$argvals

Phi_argvals     <- fda::eval.basis(argvals, basis_obj)
mean_coefs_vec  <- as.numeric(meanfd$coefs)
harmonics_coefs <- harmonics_selected$coefs

reconstruct_coefs <- function(scores_mat) {
  n_curves <- nrow(scores_mat)
  matrix(mean_coefs_vec, nrow = length(mean_coefs_vec), ncol = n_curves) +
    harmonics_coefs %*% t(scores_mat)
}

## Rolling-origin scaffolding -- REUSED EXACTLY from Step 24, not redefined
origin_dates <- step24_results$origin_dates
n_origins    <- step24_results$n_origins
H_max        <- step24_results$H_max
