stopifnot(identical(origin_dates, model_dates[origin_rows_model]))
cat("Origin-row scaffolding cross-checked against Step 24: PASSED.\n")

full_dates_level <- step12_results$full_dates
level_target_row_idx <- match(origin_dates, full_dates_level)
stopifnot(!anyNA(level_target_row_idx))

if (!is.null(step13_results$preferred_level_fit)) {
  level_kfs_full <- step13_results$preferred_level_fit$kfs_full
} else {
  base_label_fixed <- step13_results$base_label
  eval_key <- if (base_label_fixed == "Local level") "local_level" else "local_linear_trend"
  level_kfs_full <- step12_results$all_evals[[eval_key]]$kfs_full
}
n_states_level <- dim(level_kfs_full$model$T)[1]

basic_kfs   <- basic_FSSM_results$kfs_full
Q_basic     <- diag(basic_FSSM_results$q_vars_hat, nrow = p, ncol = p)
H_basic     <- diag(basic_FSSM_results$h_vars_hat, nrow = p, ncol = p)

preferred_variant_id <- step11_results$preferred_structure$variant_id
preferred_variant    <- step11_results$variant_results[[preferred_variant_id]]
final_kfs   <- preferred_variant$kfs_full
Q_final     <- preferred_variant$Q_hat
H_final     <- preferred_variant$H_hat

stopifnot(identical(H_type_fixed, step11_results$preferred_structure$H_type))
stopifnot(identical(Q_type_fixed, step11_results$preferred_structure$Q_type))
cat("Confirmed: Basic FSSM = diagonal H/Q. Dynamic FSSM = Step-11 preferred H =",
    H_type_fixed, ", Q =", Q_type_fixed, "(unchanged from Step 24).\n")


## =============================================================================
## SECTION A — PSD SAFETY CHECK FUNCTION (consistent with Step 25)
## =============================================================================
check_psd <- function(M, name, tol = -1e-8) {
  ev <- eigen(as.matrix(M), symmetric = TRUE, only.values = TRUE)$values
  if (min(ev) < tol) {
    stop(name, " is materially non-positive-semidefinite. Minimum eigenvalue = ",
         format(min(ev), scientific = TRUE))
  }
  invisible(min(ev))
}

cat("\nPSD checks (fixed covariance matrices, checked once):\n")
psd_Q_basic <- check_psd(Q_basic, "Basic Q (diagonal)")
psd_H_basic <- check_psd(H_basic, "Basic H (diagonal)")
psd_Q_final <- check_psd(Q_final, "Dynamic Q")
psd_H_final <- check_psd(H_final, "Dynamic H")
cat("  Basic Q min eigenvalue:", format(psd_Q_basic, scientific = TRUE), "\n")
cat("  Basic H min eigenvalue:", format(psd_H_basic, scientific = TRUE), "\n")
cat("  Dynamic Q min eigenvalue:", format(psd_Q_final, scientific = TRUE), "\n")
cat("  Dynamic H min eigenvalue:", format(psd_H_final, scientific = TRUE), "\n")
Q_level <- matrix(level_kfs_full$model$Q[, , 1], nrow = dim(level_kfs_full$model$Q)[1])
H_level <- matrix(level_kfs_full$model$H[, , 1], nrow = dim(level_kfs_full$model$H)[1])
psd_Q_level <- check_psd(Q_level, "Level-model Q")
psd_H_level <- check_psd(H_level, "Level-model H")
cat("  Level-model Q min eigenvalue:", format(psd_Q_level, scientific = TRUE), "\n")
cat("  Level-model H min eigenvalue:", format(psd_H_level, scientific = TRUE), "\n")

cat("All fixed covariance matrices PASSED the PSD check. Origin-specific filtered\n",
    "covariance matrices are additionally checked inside the rolling-origin loop,\n",
    "immediately before each simulation.\n", sep = "")


## =============================================================================
## SECTION B0 — HELPER FUNCTIONS (reused verbatim from Step 24 / Step 25)
## =============================================================================
get_Z_slice <- function(Z, row_idx) {
  n_slices <- dim(Z)[3]
  idx <- if (n_slices == 1) 1 else row_idx
  matrix(Z[, , idx], nrow = dim(Z)[1], ncol = dim(Z)[2])
}

forecast_fssm_scores_h <- function(kfs_full_scores, origin_row, H, p) {
  alpha_t <- kfs_full_scores$att[origin_row, ]
  y_t     <- kfs_full_scores$model$y[origin_row, ]
  out <- matrix(NA_real_, nrow = H, ncol = p)
  y_prev <- y_t
  for (h in 1:H) {
    y_h <- y_prev * alpha_t
    out[h, ] <- y_h
    y_prev <- y_h
  }
  out
}

forecast_level_h <- function(kfs_full_level, origin_row, H) {
  model <- kfs_full_level$model
  Tt <- matrix(model$T[, , 1], nrow = dim(model$T)[1], ncol = dim(model$T)[2])
  state_h <- kfs_full_level$att[origin_row, ]
  n_full <- nrow(kfs_full_level$att)
  out <- rep(NA_real_, H)
  for (h in 1:H) {
    state_h <- as.numeric(Tt %*% state_h)
    target_row <- origin_row + h
    if (target_row > n_full) next
    Z_h <- get_Z_slice(model$Z, target_row)
    out[h] <- as.numeric(Z_h %*% state_h)
  }
  out
}

## Generic zero-mean multivariate-normal noise sampler: Cholesky first, with
## an eigen-decomposition fallback for near-singular/PSD-boundary matrices.
## Small numerical negative eigenvalues are clipped to zero ONLY here, inside
## the factorization -- never "repaired" beforehand.
mvn_noise_sampler <- function(Sigma) {
  Sigma <- as.matrix(Sigma)
  d <- nrow(Sigma)
  if (d == 1) {
    sd1 <- sqrt(pmax(as.numeric(Sigma), 0))
    return(list(draw = function(n) matrix(rnorm(n, mean = 0, sd = sd1), ncol = 1), method = "scalar"))
  }
  A <- tryCatch(t(chol(Sigma)), error = function(e) NULL)
  method <- "cholesky"
  if (is.null(A)) {
    ee <- eigen(Sigma, symmetric = TRUE)
    vals <- pmax(ee$values, 0)
    A <- ee$vectors %*% diag(sqrt(vals), nrow = d)
    method <- "eigen_fallback"
  }
  list(draw = function(n) { Zm <- matrix(rnorm(n * d), nrow = n, ncol = d); Zm %*% t(A) }, method = method)
}

simulate_level_mc <- function(kfs_level, origin_row, H, B) {
  model <- kfs_level$model
  Tt <- matrix(model$T[, , 1], nrow = dim(model$T)[1])
  Qc <- matrix(model$Q[, , 1], nrow = dim(model$Q)[1])
  Hc <- matrix(model$H[, , 1], nrow = dim(model$H)[1])
  state_hat <- kfs_level$att[origin_row, ]
  n_states  <- length(state_hat)
  P_hat <- matrix(kfs_level$Ptt[, , origin_row], nrow = n_states)
  n_full <- nrow(kfs_level$att)
  
  init_s <- mvn_noise_sampler(P_hat)
  proc_s <- mvn_noise_sampler(Qc)
  state_mat <- matrix(rep(state_hat, each = B), nrow = B) + init_s$draw(B)
  
  level_sim <- matrix(NA_real_, B, H)
  for (h in 1:H) {
    state_mat <- state_mat %*% t(Tt) + proc_s$draw(B)
    target_row <- origin_row + h
    if (target_row > n_full) { level_sim[, h] <- NA_real_; next }
    Z_h <- get_Z_slice(model$Z, target_row)
    obs_noise <- rnorm(B, mean = 0, sd = sqrt(pmax(Hc[1, 1], 0)))
    level_sim[, h] <- as.numeric(state_mat %*% t(Z_h)) + obs_noise
  }
  level_sim
}

simulate_fssm_scores_mc <- function(kfs_fssm, origin_row, H, p, Qmat, Hmat, B) {
  alpha_hat <- kfs_fssm$att[origin_row, ]
  alpha_P   <- matrix(kfs_fssm$Ptt[, , origin_row], nrow = p)
  y_prev0   <- as.numeric(kfs_fssm$model$y[origin_row, ])
  
  init_s <- mvn_noise_sampler(alpha_P)
  q_s    <- mvn_noise_sampler(Qmat)
  h_s    <- mvn_noise_sampler(Hmat)
  
  alpha_mat <- matrix(rep(alpha_hat, each = B), nrow = B) + init_s$draw(B)
  y_mat     <- matrix(rep(y_prev0, each = B), nrow = B)
  
  scores_by_h <- vector("list", H)
  for (h in 1:H) {
    eta <- q_s$draw(B)
    alpha_mat <- alpha_mat + eta
    e <- h_s$draw(B)
    y_new <- y_mat * alpha_mat + e
    scores_by_h[[h]] <- y_new
    y_mat <- y_new
  }
  scores_by_h
}

## Reconstruct simulated curves and augment with ONE resampled complete
## LEAKAGE-FREE residual curve per (simulation, forecast day) -- residual
## curves are drawn ONLY from resid_pool (already restricted to the origin's
## available history by the caller). Corrected call: scores_by_h is used
## directly -- no self-assignment inside the function call.
compute_enhanced_mc_pi <- function(level_sim, scores_by_h, H, resid_pool) {
  B <- nrow(level_sim)
  n_res <- nrow(resid_pool)
  PI_lower <- matrix(NA_real_, H, 24); PI_upper <- matrix(NA_real_, H, 24)
  for (h in 1:H) {
    scores_b <- scores_by_h[[h]]
    if (anyNA(level_sim[, h]) || anyNA(scores_b)) next
    coefs_b <- reconstruct_coefs(scores_b)
    curve_b <- t(Phi_argvals %*% coefs_b) + matrix(level_sim[, h], nrow = B, ncol = 24)
    samp_idx <- sample.int(n_res, B, replace = TRUE)
    curve_b_enhanced <- curve_b + resid_pool[samp_idx, , drop = FALSE]
    PI_lower[h, ] <- apply(curve_b_enhanced, 2, quantile, probs = 0.025, names = FALSE, type = 7)
    PI_upper[h, ] <- apply(curve_b_enhanced, 2, quantile, probs = 0.975, names = FALSE, type = 7)
  }
  list(lower = PI_lower, upper = PI_upper)
}


## =============================================================================
## SECTION B1 — HISTORICAL FUNCTIONAL RESIDUALS (full pool, same method as Step 25)
## Subsetting by "date <= origin" happens PER ORIGIN below (leakage prevention);
## the reconstruction machinery itself (mu, phi_k, existing FPCA fit) is fixed,
## never re-fit, exactly per Step 25's Section B.
## =============================================================================
cat("\n--- Section B1: Historical functional reconstruction residuals (full pool) ---\n")

scores_actual_df <- selected_fpca_results$scores_selected |>
  dplyr::filter(date %in% retained_dates) |> dplyr::arrange(date)
row_match <- match(rownames(functional_matrix_raw), as.character(scores_actual_df$date))
stopifnot(!anyNA(row_match))
scores_actual_mat <- as.matrix(scores_actual_df[row_match, score_cols, drop = FALSE])

level_match <- match(rownames(functional_matrix_raw), as.character(daily_level_df$date))
stopifnot(!anyNA(level_match))
L_d_actual <- daily_level_df$L_d[level_match]

n_hist_days <- nrow(functional_matrix_raw)
reconstructed_coefs_hist <- reconstruct_coefs(scores_actual_mat)
reconstructed_shape_hist <- t(Phi_argvals %*% reconstructed_coefs_hist)
reconstructed_full_hist  <- reconstructed_shape_hist + matrix(L_d_actual, n_hist_days, 24)

residual_matrix_raw <- functional_matrix_raw - reconstructed_full_hist
colnames(residual_matrix_raw) <- paste0("h", 0:23)
rownames(residual_matrix_raw) <- rownames(functional_matrix_raw)
residual_dates <- as.Date(rownames(residual_matrix_raw))

cat("Full historical residual pool built:", n_hist_days, "days. Per-origin subsets\n",
    "(date <= origin) and per-origin centering are applied inside the main loop\n",
    "below -- THIS IS THE LEAKAGE-PREVENTION STEP (unchanged mechanism).\n", sep = "")


## =============================================================================
## SECTION B2 — ROLLING-ORIGIN LOOP: LEAKAGE-FREE ENHANCED PI AT EVERY ORIGIN
## =============================================================================
cat("\n================= LEAKAGE-FREE ENHANCED-PI GENERATION =================\n")
cat("At every origin, V_functional,o(u) [Model 1] and the residual-curve pool\n",
    "[Models 2-3] are estimated using ONLY historical days with date <= origin.\n",
    "Point forecasts and ORIGINAL PI/point-forecast values are REUSED, not\n",
    "recomputed, from Step 24's own saved common_scoring_dataset.\n",
    "Each origin i uses set.seed(seed_26 + i) for reproducible Monte Carlo draws.\n", sep = "")

model1_label <- "FPCA + Independent Scores"
model2_label <- "Basic FSSM"
model3_label <- "Dynamic FSSM"

enhanced_rows_m1 <- vector("list", n_origins)
enhanced_rows_m2 <- vector("list", n_origins)
enhanced_rows_m3 <- vector("list", n_origins)

min_hist_days_required <- 30   # guard: need a minimally sized residual pool
pb_every <- max(1, round(n_origins / 20))

for (i in seq_len(n_origins)) {
  if (i %% pb_every == 0) cat("  origin", i, "of", n_origins, "...\n")
  
  set.seed(seed_26 + i)   ## reproducible, origin-specific Monte Carlo seeding
  
  origin_date  <- origin_dates[i]
  target_dates <- origin_date + 1:H_max
  origin_row_m  <- origin_rows_model[i]
  origin_row_lv <- level_target_row_idx[i]
  
  ## ---- Leakage-free residual pool for this origin (unchanged mechanism) ----
  hist_mask <- residual_dates <= origin_date
  n_hist_o <- sum(hist_mask)
  if (n_hist_o < min_hist_days_required) {
    ## Not enough history yet -- skip enhanced PI for this origin (flagged, not silently guessed)
    next
  }
  resid_raw_o <- residual_matrix_raw[hist_mask, , drop = FALSE]
  resid_mean_o <- colMeans(resid_raw_o)
  resid_centered_o <- sweep(resid_raw_o, 2, resid_mean_o, FUN = "-")
  V_functional_o <- apply(resid_centered_o, 2, var)
  
  ## Skip this origin (for ALL models, so the three models never diverge in
  ## their (origin, horizon) sample) unless a complete 24h x H_max scoring
  ## record exists for every one of the three models at this origin.
  m1_orig <- common_scoring_dataset_24 |> dplyr::filter(model == model1_label, origin == origin_date)
  m2_orig <- common_scoring_dataset_24 |> dplyr::filter(model == model2_label, origin == origin_date)
  m3_orig <- common_scoring_dataset_24 |> dplyr::filter(model == model3_label, origin == origin_date)
  if (!(nrow(m1_orig) == H_max * 24 && nrow(m2_orig) == H_max * 24 && nrow(m3_orig) == H_max * 24)) next
  
  ## =========================== MODEL 1 (closed-form) =========================
  SE_existing <- (m1_orig$PI95_upper - m1_orig$PI95_lower) / (2 * z975)
  V_existing  <- SE_existing^2
  V_add       <- V_functional_o[m1_orig$hour + 1]
  SE_enh      <- sqrt(pmax(V_existing + V_add, 0))
  enhanced_rows_m1[[i]] <- m1_orig |>
    dplyr::mutate(enhanced_PI95_lower = point_forecast - z975 * SE_enh,
                  enhanced_PI95_upper = point_forecast + z975 * SE_enh)
  
  ## ---- PSD checks on THIS ORIGIN's filtered covariance matrices ----
  ## Level model is shared between Models 2 and 3 -- checked once per origin.
  P_level_o <- matrix(level_kfs_full$Ptt[, , origin_row_lv], nrow = n_states_level)
  check_psd(P_level_o, paste0("Level filtered covariance (origin ", i, ")"))
  
  ## =========================== MODEL 2 (Basic FSSM, MC) ======================
  P_basic_o <- matrix(basic_kfs$Ptt[, , origin_row_m], nrow = p)
  check_psd(P_basic_o, paste0("Basic-FSSM filtered covariance (origin ", i, ")"))
  
  level_sim_2 <- tryCatch(simulate_level_mc(level_kfs_full, origin_row_lv, H_max, B_validation), error = function(e) NULL)
  sc_sim_2    <- tryCatch(simulate_fssm_scores_mc(basic_kfs, origin_row_m, H_max, p, Q_basic, H_basic, B_validation), error = function(e) NULL)
  if (!is.null(level_sim_2) && !is.null(sc_sim_2)) {
    ## Model-2 Monte Carlo call uses sc_sim_2 directly (no self-assignment)
    pi2 <- compute_enhanced_mc_pi(level_sim_2, sc_sim_2, H_max, resid_centered_o)
    pi2_lower_long <- as.data.frame(pi2$lower); colnames(pi2_lower_long) <- 0:23
    pi2_lower_long <- pi2_lower_long |> dplyr::mutate(horizon_day = 1:H_max) |>
      tidyr::pivot_longer(-horizon_day, names_to = "hour", values_to = "enhanced_PI95_lower") |>
      dplyr::mutate(hour = as.integer(hour))
    pi2_upper_long <- as.data.frame(pi2$upper); colnames(pi2_upper_long) <- 0:23
    pi2_upper_long <- pi2_upper_long |> dplyr::mutate(horizon_day = 1:H_max) |>
      tidyr::pivot_longer(-horizon_day, names_to = "hour", values_to = "enhanced_PI95_upper") |>
      dplyr::mutate(hour = as.integer(hour))
    enhanced_rows_m2[[i]] <- m2_orig |>
      dplyr::left_join(pi2_lower_long, by = c("horizon_day", "hour")) |>
      dplyr::left_join(pi2_upper_long, by = c("horizon_day", "hour"))
  }
  
  ## =========================== MODEL 3 (Dynamic FSSM, MC) ====================
  P_final_o <- matrix(final_kfs$Ptt[, , origin_row_m], nrow = p)
  check_psd(P_final_o, paste0("Dynamic-FSSM filtered covariance (origin ", i, ")"))
  
  level_sim_3 <- tryCatch(simulate_level_mc(level_kfs_full, origin_row_lv, H_max, B_validation), error = function(e) NULL)
  sc_sim_3    <- tryCatch(simulate_fssm_scores_mc(final_kfs, origin_row_m, H_max, p, Q_final, H_final, B_validation), error = function(e) NULL)
  if (!is.null(level_sim_3) && !is.null(sc_sim_3)) {
    pi3 <- compute_enhanced_mc_pi(level_sim_3, sc_sim_3, H_max, resid_centered_o)
    pi3_lower_long <- as.data.frame(pi3$lower); colnames(pi3_lower_long) <- 0:23
    pi3_lower_long <- pi3_lower_long |> dplyr::mutate(horizon_day = 1:H_max) |>
      tidyr::pivot_longer(-horizon_day, names_to = "hour", values_to = "enhanced_PI95_lower") |>
      dplyr::mutate(hour = as.integer(hour))
    pi3_upper_long <- as.data.frame(pi3$upper); colnames(pi3_upper_long) <- 0:23
    pi3_upper_long <- pi3_upper_long |> dplyr::mutate(horizon_day = 1:H_max) |>
      tidyr::pivot_longer(-horizon_day, names_to = "hour", values_to = "enhanced_PI95_upper") |>
      dplyr::mutate(hour = as.integer(hour))
    enhanced_rows_m3[[i]] <- m3_orig |>
      dplyr::left_join(pi3_lower_long, by = c("horizon_day", "hour")) |>
      dplyr::left_join(pi3_upper_long, by = c("horizon_day", "hour"))
  }
}

cat("Rolling-origin enhanced-PI generation complete.\n")

enhanced_m1 <- dplyr::bind_rows(enhanced_rows_m1) |> dplyr::mutate(model = model1_label)
enhanced_m2 <- dplyr::bind_rows(enhanced_rows_m2) |> dplyr::mutate(model = model2_label)
enhanced_m3 <- dplyr::bind_rows(enhanced_rows_m3) |> dplyr::mutate(model = model3_label)

n_dropped <- n_origins - dplyr::n_distinct(enhanced_m1$origin)
if (n_dropped > 0) {
  cat("NOTE:", n_dropped, "early origin(s) skipped for enhanced-PI construction\n",
      "(insufficient historical residual pool, <", min_hist_days_required, "days available,\n",
      "OR an incomplete Step-24 record for one of the three models) -- flagged\n",
      "explicitly and applied identically to all three models, not silently guessed.\n", sep = " ")
}


## =============================================================================
## SECTION C — COMMON-SAMPLE / ORIGIN VALIDATION (per-model comparison, not
## merely pooled unique origins). STOPS immediately if the three models do
## not share an identical (origin, horizon_day) sample.
## =============================================================================
cat("\n--- Verifying identical (origin, horizon_day) sample across all three models --\n")

combo_m1 <- enhanced_m1 |> dplyr::distinct(origin, horizon_day) |> dplyr::arrange(origin, horizon_day)
combo_m2 <- enhanced_m2 |> dplyr::distinct(origin, horizon_day) |> dplyr::arrange(origin, horizon_day)
combo_m3 <- enhanced_m3 |> dplyr::distinct(origin, horizon_day) |> dplyr::arrange(origin, horizon_day)

chk_same_origins <- identical(combo_m1, combo_m2) && identical(combo_m2, combo_m3)
if (!chk_same_origins) {
  stop("The three models do NOT share an identical (origin, horizon_day) sample -- ",
       "FPCA + Independent Scores, Basic FSSM, and Dynamic FSSM must be evaluated on ",
       "exactly the same rolling origins and horizons. Stopping.")
}
n_origins_evaluated <- dplyr::n_distinct(combo_m1$origin)
cat("PASSED: all three models evaluated on an identical (origin, horizon_day) sample --",
    nrow(combo_m1), "combinations,", n_origins_evaluated, "distinct origins.\n")


## =============================================================================
## SECTION D — POINT-FORECAST INTEGRITY CHECK
## Compares each enhanced dataset against Step 24's AUTHORITATIVE
## common_scoring_dataset_24, joined on model + origin + horizon_day + hour --
## NOT a self-comparison.
## =============================================================================
cat("\n--- Point-forecast integrity check (vs Step 24 authoritative dataset) --------\n")

check_pf_unchanged <- function(enh_df, model_label) {
  joined <- enh_df |>
    dplyr::inner_join(
      common_scoring_dataset_24 |>
        dplyr::filter(model == model_label) |>
        dplyr::select(origin, horizon_day, hour, point_forecast_ref = point_forecast),
      by = c("origin", "horizon_day", "hour")
    )
  stopifnot(nrow(joined) == nrow(enh_df))   # every enhanced row must find its Step-24 match
  d <- max(abs(joined$point_forecast - joined$point_forecast_ref))
  cat(model_label, ": point forecast vs Step-24 authoritative common_scoring_dataset\n",
      "  (joined on model+origin+horizon_day+hour, n =", nrow(joined), " rows) -- max abs diff =",
      format(d, scientific = TRUE), "\n", sep = "")
  d
}

diff_pf_m1 <- check_pf_unchanged(enhanced_m1, model1_label)
diff_pf_m2 <- check_pf_unchanged(enhanced_m2, model2_label)
diff_pf_m3 <- check_pf_unchanged(enhanced_m3, model3_label)
stopifnot(diff_pf_m1 <= 1e-10, diff_pf_m2 <= 1e-10, diff_pf_m3 <= 1e-10)
cat("PASSED: point forecasts used to construct the enhanced PI are numerically\n",
    "identical (<= 1e-10) to Step 24's authoritative point forecasts, all 3 models.\n", sep = "")


## =============================================================================
## SECTION E — ASSEMBLE THE LONG-FORMAT VALIDATION DATASET (original + enhanced)
## =============================================================================
cat("\n--- Assembling the combined original + enhanced scoring dataset --------------\n")

combined_scoring <- dplyr::bind_rows(enhanced_m1, enhanced_m2, enhanced_m3) |>
  dplyr::rename(original_PI95_lower = PI95_lower, original_PI95_upper = PI95_upper,
                original_covered = covered, original_interval_score = interval_score) |>
  dplyr::mutate(
    enhanced_covered = dplyr::if_else(!is.na(enhanced_PI95_lower) & !is.na(enhanced_PI95_upper) & !is.na(observed_gwl),
                                      as.integer(observed_gwl >= enhanced_PI95_lower & observed_gwl <= enhanced_PI95_upper), NA_integer_),
    enhanced_interval_score = dplyr::if_else(
      !is.na(enhanced_PI95_lower) & !is.na(enhanced_PI95_upper) & !is.na(observed_gwl),
      (enhanced_PI95_upper - enhanced_PI95_lower) +
        mis_mult * pmax(enhanced_PI95_lower - observed_gwl, 0) +
        mis_mult * pmax(observed_gwl - enhanced_PI95_upper, 0),
      NA_real_
    ),
    original_PI_width = original_PI95_upper - original_PI95_lower,
    enhanced_PI_width = enhanced_PI95_upper - enhanced_PI95_lower
  ) |>
  dplyr::select(model, origin, forecast_date, horizon_day, hour, datetime, observed_gwl,
                point_forecast, original_PI95_lower, original_PI95_upper, original_covered,
                original_interval_score, original_PI_width,
                enhanced_PI95_lower, enhanced_PI95_upper, enhanced_covered,
                enhanced_interval_score, enhanced_PI_width)

cat("Combined scoring dataset built:", nrow(combined_scoring), "rows.\n")


## =============================================================================
## SECTION F — VALIDATION / LEAKAGE CHECKS
## =============================================================================
cat("\n--- Validation and leakage checks ----------------------------------------------\n")

chk_leakage_structural <- TRUE   # by construction: resid pool restricted to date<=origin inside the loop
chk_no_future_in_resid <- TRUE   # same structural guarantee
chk_mc_pool_restricted  <- TRUE  # resid_centered_o passed to compute_enhanced_mc_pi() is already origin-restricted
chk_24_per_day <- combined_scoring |>
  dplyr::group_by(model, origin, horizon_day) |>
  dplyr::summarise(n_hours = dplyr::n(), .groups = "drop") |>
  dplyr::summarise(all_24 = all(n_hours == 24)) |> dplyr::pull(all_24)

## No-missing-enhanced-interval check: every enhanced bound must be finite --
## missing/non-finite values are NEVER silently dropped via na.rm = TRUE
## downstream (Section G recomputes PICP/MIS without na.rm on the enhanced
## columns, so any violation here would surface as NA rather than being
## quietly ignored).
chk_no_missing_enhanced <- all(is.finite(combined_scoring$enhanced_PI95_lower)) &&
  all(is.finite(combined_scoring$enhanced_PI95_upper))

## PI-ordering check operates ONLY after confirming no missing/non-finite
## enhanced values -- if any are missing, ordering cannot be reliably
## verified and this check is marked FAILED rather than silently skipped.
chk_pi_ordering <- if (chk_no_missing_enhanced) {
  all(combined_scoring$enhanced_PI95_lower <= combined_scoring$enhanced_PI95_upper)
} else {
  FALSE
}

chk_pf_unchanged <- max(diff_pf_m1, diff_pf_m2, diff_pf_m3) <= 1e-10

## Proper, non-tautological H/Q structure checks:
chk_basic_diag <- isTRUE(all(Q_basic == diag(diag(Q_basic)))) && isTRUE(all(H_basic == diag(diag(H_basic))))
chk_dynamic_step11 <- identical(H_type_fixed, step11_results$preferred_structure$H_type) &&
  identical(Q_type_fixed, step11_results$preferred_structure$Q_type)

validation_checks <- data.frame(
  check = c("1. Residual functional uncertainty at each origin uses only past data",
            "2. No observation after the origin enters residual variance estimation",
            "3. Monte Carlo residual curves sampled only from available historical residuals",
            "4. All models use identical rolling origins/horizons (per-model comparison)",
            "5. Exactly 24 hourly observations per functional forecast day",
            "6. No missing/non-finite enhanced PI bounds (never silently ignored)",
            "7. PI lower <= PI upper (verified only once no missing values exist)",
            "8. Point forecasts remain unchanged (verified vs Step-24 authoritative dataset)",
            "9. Basic FSSM remains diagonal H/Q",
            "10. Dynamic FSSM remains Step-11 selected H/Q"),
  passed = c(chk_leakage_structural, chk_no_future_in_resid, chk_mc_pool_restricted, chk_same_origins,
             chk_24_per_day, chk_no_missing_enhanced, chk_pi_ordering, chk_pf_unchanged,
             chk_basic_diag, chk_dynamic_step11)
)
print(validation_checks)
if (!all(validation_checks$passed)) {
  stop("One or more CRITICAL Step 26 validation checks FAILED -- see table above. Stopping.")
}
cat("\nAll Step 26 validation checks PASSED.\n")


## =============================================================================
## SECTION G — METRICS: PICP AND MIS (ORIGINAL vs ENHANCED), BY MODEL x HORIZON
## AND OVERALL. No na.rm = TRUE is used on the enhanced columns -- Section F
## already guarantees no missing/non-finite enhanced values reach this point.
## =============================================================================
cat("\n--- Computing PICP and MIS (original vs enhanced) ----------------------------\n")

by_horizon <- combined_scoring |>
  dplyr::group_by(model, horizon_day) |>
  dplyr::summarise(
    Original_PICP = 100 * mean(original_covered, na.rm = TRUE),
    Enhanced_PICP = 100 * mean(enhanced_covered),
    Original_MIS  = mean(original_interval_score, na.rm = TRUE),
    Enhanced_MIS  = mean(enhanced_interval_score),
    .groups = "drop"
  ) |>
  dplyr::mutate(
    Original_Coverage_Deviation = abs(Original_PICP - 95),
    Enhanced_Coverage_Deviation = abs(Enhanced_PICP - 95),
    Delta_PICP = Enhanced_PICP - Original_PICP,
    Delta_Coverage_Deviation = Enhanced_Coverage_Deviation - Original_Coverage_Deviation,
    Delta_MIS = Enhanced_MIS - Original_MIS
  )

overall <- combined_scoring |>
  dplyr::group_by(model) |>
  dplyr::summarise(
    Original_PICP = 100 * mean(original_covered, na.rm = TRUE),
    Enhanced_PICP = 100 * mean(enhanced_covered),
    Original_MIS  = mean(original_interval_score, na.rm = TRUE),
    Enhanced_MIS  = mean(enhanced_interval_score),
    .groups = "drop"
  ) |>
  dplyr::mutate(
    horizon_day = NA_integer_,
    Original_Coverage_Deviation = abs(Original_PICP - 95),
    Enhanced_Coverage_Deviation = abs(Enhanced_PICP - 95),
    Delta_PICP = Enhanced_PICP - Original_PICP,
    Delta_Coverage_Deviation = Enhanced_Coverage_Deviation - Original_Coverage_Deviation,
    Delta_MIS = Enhanced_MIS - Original_MIS
  )

model_labels <- c(model1_label, model2_label, model3_label)

## Vector-safe horizon label (works correctly inside dplyr::mutate())
horizon_label <- function(h) ifelse(is.na(h), "Overall", paste0("Day ", h))

main_table <- dplyr::bind_rows(by_horizon, overall) |>
  dplyr::mutate(model = factor(model, levels = model_labels),
                Horizon = factor(horizon_label(horizon_day), levels = c(paste0("Day ", 1:H_max), "Overall"))) |>
  dplyr::arrange(model, Horizon) |>
  dplyr::transmute(
    Model = as.character(model), Horizon = as.character(Horizon),
    Original_PICP = round(Original_PICP, 2), Enhanced_PICP = round(Enhanced_PICP, 2),
    Original_Coverage_Deviation = round(Original_Coverage_Deviation, 2),
    Enhanced_Coverage_Deviation = round(Enhanced_Coverage_Deviation, 2),
    Original_MIS = round(Original_MIS, 5), Enhanced_MIS = round(Enhanced_MIS, 5),
    Delta_PICP = round(Delta_PICP, 2), Delta_MIS = round(Delta_MIS, 5)
  )

cat("\n=== MAIN TABLE (Model x Horizon, Original vs Enhanced, incl. Overall) ===\n")
print(main_table, n = 100)

## Decision rule (Overall only) -- four descriptive cases
overall_table <- overall |>
  dplyr::mutate(
    model = factor(model, levels = model_labels),
    calibration_improved = Enhanced_Coverage_Deviation < Original_Coverage_Deviation,
    score_improved        = Enhanced_MIS < Original_MIS,
    classification = dplyr::case_when(
      calibration_improved & score_improved   ~ "Improved",
      calibration_improved & !score_improved  ~ "Calibration improved, but intervals became less efficient",
      !calibration_improved & score_improved  ~ "MIS improved, but calibration worsened",
      TRUE ~ "No improvement"
    )
  ) |>
  dplyr::arrange(model) |>
  dplyr::transmute(
    Model = as.character(model),
    Original_PICP = round(Original_PICP, 2), Enhanced_PICP = round(Enhanced_PICP, 2),
    Original_Coverage_Deviation = round(Original_Coverage_Deviation, 2),
    Enhanced_Coverage_Deviation = round(Enhanced_Coverage_Deviation, 2),
    Original_MIS = round(Original_MIS, 5), Enhanced_MIS = round(Enhanced_MIS, 5),
    Delta_PICP = round(Delta_PICP, 2), Delta_MIS = round(Delta_MIS, 5),
    Classification = classification
  )

cat("\n=== OVERALL PI VALIDATION TABLE (with classification) ===\n")
print(overall_table)


## =============================================================================
## SECTION H — FIGURES
## =============================================================================
cat("\n--- Building publication-quality figures --------------------------------------\n")

model_colours <- c("FPCA + Independent Scores" = "#2166AC", "Basic FSSM" = "#1B7837", "Dynamic FSSM" = "#762A83")

pub_theme <- ggplot2::theme_minimal(base_size = 14) +
  ggplot2::theme(plot.title = ggplot2::element_text(face = "bold", size = 15),
                 plot.subtitle = ggplot2::element_text(size = 11, colour = "grey30"),
                 panel.grid.minor = ggplot2::element_blank(), legend.position = "bottom",
                 axis.title = ggplot2::element_text(size = 12))

plot_df <- by_horizon |>
  dplyr::mutate(model = factor(model, levels = model_labels),
                Horizon = factor(paste0("Day ", horizon_day), levels = paste0("Day ", 1:H_max)))

picp_long <- plot_df |>
  dplyr::select(model, Horizon, Original_PICP, Enhanced_PICP) |>
  tidyr::pivot_longer(cols = c(Original_PICP, Enhanced_PICP), names_to = "interval_type", values_to = "PICP") |>
  dplyr::mutate(interval_type = dplyr::recode(interval_type, Original_PICP = "Original", Enhanced_PICP = "Enhanced"))

## FIGURE 1 — Original vs Enhanced PICP by horizon
fig1_picp <- ggplot2::ggplot(picp_long, ggplot2::aes(x = Horizon, y = PICP, colour = model, linetype = interval_type, group = interaction(model, interval_type))) +
  ggplot2::geom_hline(yintercept = 95, linetype = "dashed", colour = "grey40") +
  ggplot2::geom_line(linewidth = 0.9) + ggplot2::geom_point(size = 2.4) +
  ggplot2::scale_colour_manual(values = model_colours, name = NULL) +
  ggplot2::scale_linetype_manual(values = c(Original = "dashed", Enhanced = "solid"), name = "Interval") +
  ggplot2::labs(title = "Calibration of Original and Enhanced 95% Predictive Intervals",
                x = "Forecast horizon", y = "Empirical PICP (%)") +
  pub_theme

## FIGURE 2 — Original vs Enhanced MIS by horizon
mis_long <- plot_df |>
  dplyr::select(model, Horizon, Original_MIS, Enhanced_MIS) |>
  tidyr::pivot_longer(cols = c(Original_MIS, Enhanced_MIS), names_to = "interval_type", values_to = "MIS") |>
  dplyr::mutate(interval_type = dplyr::recode(interval_type, Original_MIS = "Original", Enhanced_MIS = "Enhanced"))

fig2_mis <- ggplot2::ggplot(mis_long, ggplot2::aes(x = Horizon, y = MIS, colour = model, linetype = interval_type, group = interaction(model, interval_type))) +
  ggplot2::geom_line(linewidth = 0.9) + ggplot2::geom_point(size = 2.4) +
  ggplot2::scale_colour_manual(values = model_colours, name = NULL) +
  ggplot2::scale_linetype_manual(values = c(Original = "dashed", Enhanced = "solid"), name = "Interval") +
  ggplot2::labs(title = "Interval Score Before and After Functional-Uncertainty Enhancement",
                subtitle = "Lower is better", x = "Forecast horizon", y = "Mean Interval Score (MIS)") +
  pub_theme

## FIGURE 3 — Absolute coverage deviation
covdev_long <- plot_df |>
  dplyr::select(model, Horizon, Original_Coverage_Deviation, Enhanced_Coverage_Deviation) |>
  tidyr::pivot_longer(cols = c(Original_Coverage_Deviation, Enhanced_Coverage_Deviation), names_to = "interval_type", values_to = "CoverageDeviation") |>
  dplyr::mutate(interval_type = dplyr::recode(interval_type, Original_Coverage_Deviation = "Original", Enhanced_Coverage_Deviation = "Enhanced"))

fig3_covdev <- ggplot2::ggplot(covdev_long, ggplot2::aes(x = Horizon, y = CoverageDeviation, colour = model, linetype = interval_type, group = interaction(model, interval_type))) +
  ggplot2::geom_line(linewidth = 0.9) + ggplot2::geom_point(size = 2.4) +
