## FIGURE 4 — Interval width diagnostic
width_by_horizon <- combined_scoring |>
  dplyr::group_by(model, horizon_day) |>
  dplyr::summarise(Original_Width = mean(original_PI_width, na.rm = TRUE),
                   Enhanced_Width = mean(enhanced_PI_width), .groups = "drop") |>
  dplyr::mutate(model = factor(model, levels = model_labels),
                Horizon = factor(paste0("Day ", horizon_day), levels = paste0("Day ", 1:H_max))) |>
  tidyr::pivot_longer(cols = c(Original_Width, Enhanced_Width), names_to = "interval_type", values_to = "Width") |>
  dplyr::mutate(interval_type = dplyr::recode(interval_type, Original_Width = "Original", Enhanced_Width = "Enhanced"))

fig4_width <- ggplot2::ggplot(width_by_horizon, ggplot2::aes(x = Horizon, y = Width, colour = model, linetype = interval_type, group = interaction(model, interval_type))) +
  ggplot2::geom_line(linewidth = 0.9) + ggplot2::geom_point(size = 2.4) +
