for (i in seq_len(nrow(overall_table))) {
  row <- overall_table[i, ]
  cat("\nModel:", row$Model, "\n")
  cat("  Original overall PICP :", row$Original_PICP, "% | Enhanced overall PICP :", row$Enhanced_PICP, "%\n")
  cat("  Original coverage deviation :", row$Original_Coverage_Deviation,
      "| Enhanced coverage deviation :", row$Enhanced_Coverage_Deviation, "\n")
  cat("  Original overall MIS :", row$Original_MIS, "| Enhanced overall MIS :", row$Enhanced_MIS, "\n")
  
  concl <- dplyr::case_when(
    row$Classification == "Improved" ~
      paste0("Enhanced functional uncertainty improved calibration for ", row$Model,
             ", moving empirical coverage closer to the nominal 95% level while reducing the mean interval score."),
    row$Classification == "Calibration improved, but intervals became less efficient" ~
      paste0("For ", row$Model, ", the enhancement moved coverage closer to the nominal 95% level, ",
             "but the mean interval score worsened -- calibration improved at the cost of interval efficiency."),
    row$Classification == "MIS improved, but calibration worsened" ~
      paste0("For ", row$Model, ", the mean interval score improved, but empirical coverage moved further ",
             "from the nominal 95% level -- the enhancement sharpened intervals at the cost of calibration."),
    TRUE ~ paste0("For ", row$Model, ", the enhancement did not improve calibration or interval score relative to the original interval.")
  )
  cat("  Conclusion:", concl, "\n")
}
