## -----------------------------------------------------------------------------
## 0. HELPERS — safe retrieval, size, and a running record of missing objects
## -----------------------------------------------------------------------------
missing_object_log <- data.frame(step = character(0), object_name = character(0),
                                 stringsAsFactors = FALSE)

## safe_get(): returns the object if it exists in the calling environment,
## otherwise returns NULL and logs the miss (never fabricates a substitute).
safe_get <- function(name, step_label) {
  if (exists(name, envir = .GlobalEnv, inherits = FALSE)) {
    get(name, envir = .GlobalEnv)
  } else {
    missing_object_log <<- rbind(missing_object_log,
                                 data.frame(step = step_label, object_name = name,
                                            stringsAsFactors = FALSE))
    NULL
  }
}

## drop_missing(): strips NULL/absent entries from a named list so the saved
## object stays clean (no NULL placeholders cluttering the archive), while
## the absence itself is still recorded via safe_get()'s missing_object_log.
drop_missing <- function(lst) lst[!vapply(lst, is.null, logical(1))]

obj_size_MB <- function(x) round(as.numeric(object.size(x)) / 1024^2, 4)

cat("\n================= BUILDING MASTER RESULTS ARCHIVE (Steps 1-26) =================\n")


