.forecast_horizons_days  <- if (exists("rolling_origin_validation_results", envir = .GlobalEnv, inherits = FALSE)) {
  seq_len(rolling_origin_validation_results$H_max)
} else if (exists("step18_results", envir = .GlobalEnv, inherits = FALSE)) {
  NA_integer_
} else NA_integer_

