  step22_1 = "Full Monte Carlo 95% PI upgrade for Basic FSSM",
  step23 = "Genuine future forecast, Dynamic/selected FSSM (Step 11 preferred H/Q)",
  step23_1 = "Full Monte Carlo 95% PI upgrade for Dynamic FSSM (general H/Q)",
  step24 = "Rolling-origin validation of point and interval forecasts (RMSE/MISFE/PICP/MIS)",
  step25 = "Enhanced (Hyndman-Ullah-inspired) functional prediction intervals",
  step26 = "Leakage-free validation of original vs. enhanced prediction intervals"
)

inventory_rows <- list()
for (step_name in names(.top_level_groups)) {
  grp <- .top_level_groups[[step_name]]
  if (length(grp) == 0) next
  for (obj_name in names(grp)) {
    obj <- grp[[obj_name]]
    inventory_rows[[length(inventory_rows) + 1]] <- data.frame(
      step = step_name,
      object_name = obj_name,
      object_class = paste(class(obj), collapse = "/"),
      object_size_MB = obj_size_MB(obj),
      description = unname(.step_descriptions[step_name]),
      included_in_master = TRUE,
      stringsAsFactors = FALSE
    )
  }
}
master_object_inventory <- if (length(inventory_rows) > 0) do.call(rbind, inventory_rows) else
  data.frame(step = character(0), object_name = character(0), object_class = character(0),
             object_size_MB = numeric(0), description = character(0), included_in_master = logical(0))

## Also record, in the SAME inventory, every object Steps 1-26 were expected
## to produce but that could not be found (Requirement 13/15) -- these rows
## are marked included_in_master = FALSE so the distinction is explicit and
## auditable in one place, without silently dropping the information.
if (nrow(missing_object_log) > 0) {
  missing_rows <- data.frame(
    step = missing_object_log$step,
    object_name = missing_object_log$object_name,
    object_class = NA_character_,
    object_size_MB = NA_real_,
    description = "EXPECTED BUT NOT FOUND in the current R session",
    included_in_master = FALSE,
    stringsAsFactors = FALSE
  )
  master_object_inventory <- rbind(master_object_inventory, missing_rows)
}
cat("master_object_inventory built: ", sum(master_object_inventory$included_in_master),
