## =============================================================================
## 10. VERIFY THE SAVED FILE IMMEDIATELY (fresh reload, independent of the
## in-memory GWL_master_results object built above)
## =============================================================================
cat("\n--- Verifying saved file ------------------------------------------------------\n")

.file_exists <- file.exists(.save_path)
cat("file.exists():", .file_exists, "\n")

if (.file_exists) {
  cat("file.info()$size:", file.info(.save_path)$size, "bytes (",
      round(file.info(.save_path)$size / 1024^2, 2), " MB)\n", sep = "")
  
  .reloaded <- readRDS(.save_path)
  cat("Reloaded object top-level names():\n")
  print(names(.reloaded))
  
  .critical_checks <- data.frame(
    critical_object = c("Selected FSSM (final_models$preferred_FSSM_variant OR step21$winning_method)",
                        "FPCA representation (step09$selected_fpca_results)",
                        "Level model (step12$level_state_space_results)",
                        "Step 18 rolling forecasts (validation_results$step18_rolling_origin_all_models)",
                        "Step 19 comparisons (statistical_comparisons$step19_DM_tests_and_sensitivity)",
                        "Final forecast outputs (final_forecasts)"),
    present = c(
      !is.null(.reloaded$final_models$preferred_FSSM_variant) || !is.null(.reloaded$final_models$step21_winning_method),
      !is.null(.reloaded$step09$selected_fpca_results),
      !is.null(.reloaded$step12$level_state_space_results),
      !is.null(.reloaded$validation_results$step18_rolling_origin_all_models),
      !is.null(.reloaded$statistical_comparisons$step19_DM_tests_and_sensitivity),
      length(.reloaded$final_forecasts) > 0
    ),
    stringsAsFactors = FALSE
  )
  cat("\nCritical-object verification:\n")
  print(.critical_checks)
  
  if (!all(.critical_checks$present)) {
    cat("\nWARNING: one or more CRITICAL objects are missing from the reloaded archive --\n",
        "see the table above. The archive was still saved (Requirement 13: warn, don't\n",
        "silently omit), but it should not be treated as complete until this is resolved.\n", sep = "")
  } else {
    cat("\nAll critical objects verified present in the reloaded archive.\n")
  }
} else {
  cat("WARNING: the master file does not exist on disk after saveRDS() -- verification\n",
      "could not be completed.\n", sep = "")
}


